with nuevas(numero,viejo,sec) as (values
(1,'ff197f843e60b60298b7e95e86de7773',$q$[{"titulo": "Idea central", "texto": "Èjìogbè es luz, camino abierto y equilibrio. Es el primero de los Odù y el padre de todos: habla de paz, prosperidad, hijos, victoria sobre los enemigos, despertar espiritual y larga vida. Todo eso llega por la vía de la verdad: Ifá pide aquí, antes que nada, honestidad y buen carácter, y que la persona consulte siempre antes de tomar decisiones importantes."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Quiere empezar un proyecto o hacer crecer un negocio que no ha despegado; está buscando otra forma de trabajar o de vender.", "Busca paz y estabilidad, además de dinero. Ve oportunidades, pero alguien o algo le estorba el paso.", "Desea tener hijos o agrandar la familia (relato de la familia de Àgbọnnìrègún).", "Se acerca un viaje o un cambio de lugar que puede endulzarle la vida si se prepara antes (relato de Odunkun, el camote).", "Hay chismes o calumnias en la casa, el trabajo o la calle, pero puede salir adelante (relato de Òrúnmìlà acusado).", "Recibió un bien y no lo está valorando (relato del agricultor y el plátano).", "Se le abre un camino y debe decidir cómo aprovecharlo sin volverse soberbio."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Negocios nuevos y grandes, ampliación de lo que ya se tiene y nuevas formas de ganarse la vida.", "Hijos y crecimiento de la familia.", "Victoria sobre los enemigos que bloqueaban el camino; derrota de la calumnia en la casa y en la calle.", "Un viaje que endulza la vida y hace brillar a la persona por encima de los demás.", "Paz mental, salud y larga vida, si la persona se cuida.", "Nuevas amistades, nuevas relaciones y experiencias espirituales."]}, {"titulo": "Ibi y advertencias", "puntos": ["La ingratitud: pagar con mal el bien recibido, como el agricultor que cortó al plátano que lo alimentaba.", "Perder la cabeza: decidir por impulso, euforia o pasión en lugar de pensar.", "Celos obsesivos que solo se curan con sentido común.", "Calumnias dentro y fuera de la casa.", "Trabajar o negociar sin ganancia mientras no se hace la ofrenda."]}, {"titulo": "Enseñanza principal", "texto": "La honestidad es lo más importante en la vida de una persona: quien vive en la verdad nunca queda sin raíz. Los honestos son pocos y los deshonestos muchos, pero Ifá pide sumarse a los pocos. Junto con eso, Èjìogbè enseña gratitud: el que recibe bien debe saber reconocerlo, porque el ingrato termina destruyendo lo que lo sostenía."}, {"titulo": "Relatos reunidos", "puntos": ["Eleremojú y el Ifá de su hijo. Tres adivinos, Ọwọ́ t'ara (las manos pertenecen al cuerpo), Ẹsẹ̀ t'ara (los pies pertenecen al cuerpo) y Ọtaratara, consultaron para Eleremojú, la madre de Àgbọnnìrègún, cuando ella enfrentaba problemas. Le marcaron dos gallinas, dos palomas y 3,200 cauríes para apaciguar el Ifá de su hijo, y le aseguraron que su vida sería próspera. Ella cumplió y prosperó.", "Eleremojú y los hijos de Ikin. Otro adivino, Òtítọ́l'omifi-ntẹ'lẹ-ìṣà, consultó también para Eleremojú y le dijo que los hijos de Ikin, las dieciséis nueces sagradas de su hijo, la iban a levantar si seguía haciendo sus ofrendas. Le marcó una rata awosin, una gallina o una chiva, y medicina de Ifá: dieciséis hojas de egbee machacadas en agua para lavarle la cabeza. Ella obedeció.", "Àgbọnnìrègún y los hijos sin número. Las esposas de Àgbọnnìrègún no lograban embarazarse. Los adivinos le dijeron que si ofrendaba tendría tantos hijos que nunca sabría cuántos, en vida y después de su muerte. Le marcaron una chiva y medicina de Ifá: una sopa con hojas de yẹnmẹyẹnmẹ y àgbọnyin, condimentada con semillas de irugba u ogiri y pimienta iyèré, cocinada con las trompas de la chiva; la olla se pone delante del Ifá y ahí comen las esposas. Él cumplió y tuvo muchos hijos.", "El agricultor y el plátano. Ökùnkùn-birimubirimu consultó para Ẹniunkokunjú, que quiere decir 'el que no tiene consideración', y le advirtió que nadie le había hecho un bien que él no hubiera pagado con un mal. Le marcaron un machete y una escalera de mano, y se negó a ofrendar. Ẹniunkokunjú es el agricultor: el plátano lo alimentó y le dio todo lo bueno que tenía, y al final el agricultor le cortó el tallo. Por eso este Odù advierte contra la ingratitud y contra perder la cabeza.", "Odunkun, el camote, viaja a la tierra. Odunkun iba de viaje a la tierra donde vivían el ñame (Isu) y el maíz (Agbado). Ifá le aconsejó ofrendar para que su vida fuera más dulce que la de ellos. Cumplió. Cuando la gente de la tierra probó al ñame y al maíz, ninguno resultó tan dulce como el camote. Feliz, Odunkun quiso repetir la ofrenda una y otra vez, pero Ifá le dijo que no hacía falta. Cantó: 'Vida de camote, más dulce que la miel; que los inmortales hagan dulce mi vida'. Quien saca este Odù está por viajar y le espera vida larga, abundancia e hijos; su estrella brillará por encima de los que encuentre en el camino, y debe comer camote como medicina de buena fortuna.", "La calumnia en la casa y en la calle. Ifá consultó para la Calumnia de la casa, para la Calumnia de la calle y para Ọ̀rúnmìlà, y les pidió a todos ofrendar. Las dos calumnias se negaron; Ọ̀rúnmìlà cumplió y venció a sus enemigos dentro y fuera de su casa. Cantó: 'Calumnia de la casa, calumnia de la calle, ¿qué te compré yo?'. Hay quien habla mal de la persona en el hogar y en el trabajo; con la ofrenda se impone y recibe abundancia. Los inmortales insisten en la justicia.", "Ògo tééré y el origen de los hijos. Ifá consultó para Ògo tééré cuando iba a llevar la guerra a una ciudad. Le pidieron ofrecer, ofreció, y le mandaron hacer una guerra sin tregua, tomar hombres y mujeres y traer al mundo 'cautivos sin dientes'. Es la imagen de la unión del hombre y la mujer: la ciudad es la mujer, Ògo tééré es el hombre, y los cautivos sin dientes son los recién nacidos. Así Olódùmarè dio esposas, esposos e hijos a cada quien, y desde entonces la vida se hizo placentera.", "Los honestos son menos de veinte. Ifá consultó para Ọ̀rúnmìlà cuando estaba triste por tanta maldad en el mundo: los honestos eran menos de veinte y los malvados más de ciento cuarenta mil. Le pidieron ofrecer siempre para que no faltaran personas honestas en la Tierra. Ofrecieron, y al poco tiempo empezaron a aparecer los honestos y la vida se equilibró. Las divinidades no aceptan que se comprometa la verdad."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Eleremojú: dos gallinas, dos palomas y 3,200 cauríes para el Ifá de su hijo.", "Eleremojú (segunda consulta): una rata awosin, una gallina o una chiva y medicina de Ifá; lavado de cabeza con dieciséis hojas de egbee.", "Àgbọnnìrègún: una chiva y sopa medicinal de yẹnmẹyẹnmẹ, àgbọnyin, irugba u ogiri e iyèré para las esposas.", "Ẹniunkokunjú (rechazado): un machete y una escalera de mano.", "Odunkun: 4 palomas, 4 gallos, aceite de palma, un plato blanco, 4 ẹ̀kọ, harina de maíz con aceite (àádùn), cosas dulces (miel, azúcar) y dinero, a Ọbàtálá y Ògún.", "Contra la calumnia: 3 palomas, aceite de palma, 3 ẹ̀kọ y dinero, a Ọbàtálá y Ògún. Prohibido: semillas del suelo, hongos y telas negras."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá y Ọ̀rúnmìlà, con su título Àgbọnnìrègún, están en el centro del signo. Ọbàtálá y Ògún reciben las ofrendas de prosperidad y de victoria sobre la calumnia. Orí, la cabeza, decide el destino y se lava con hojas de Ifá. Èṣù pone el canto en la boca de quien cumplió. Olódùmarè es quien reparte esposas, esposos e hijos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Egbee (lavado de cabeza), yẹnmẹyẹnmẹ, àgbọnyin, irugba u ogiri, pimienta iyèré, camote (Odunkun), ñame, maíz, plátano, cacahuate (ẹ̀pà), chufa (ìmùmù), miel, aceite de palma, ẹ̀kọ y àádùn."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 1.1 (yorùbá): Ọwọ́ t'ara, / Ẹsẹ̀ t'ara, Ọtaratara: / ló dífá f'Eleremojú / tí í ṣe Ìyá Àgbọnnìrègún. / Wọ́n ní kí ó rú: / Abo adìyẹ Méjì, ẹyẹlé Méjì / àti Alesan ẹgbẹ̀rìndínlógún owó / Kí ó fi bọ Ifá ọmọ rẹ̀ / Wọ́n ní: / Ìwà rẹ̀ a s'ùrẹ / Ó gbọ́ ó rú.", "Verso 1.2 (yorùbá): Òtítọ́l'omifi-ntẹ'lẹ-ìṣà: / ló dífá f'Eleremojú / tí í ṣe Ìyá Àgbọnnìrègún. / Ifá ní: / Ikin ọmọ rẹ̀ ni yóò gbé e / nítorínáà kí ó rú: / Eku-awosin, / abo adìyẹ tàbí ewúrẹ́ / àti ewé Ifá / Ó gbọ́ ó rú.", "Verso 1.3 (yorùbá): Ọtọ̀ọ̀tọ̀, / Ọrọ̀ọ̀rọ̀, / Ọtọ̀ọ̀tọ̀ ni a í j'ẹpà, / Ọtọ̀ọ̀tọ̀ ni a í jẹ ìmùmù, / Tọ̀ritirú l'afi nfẹ́ Ọba'Mákin l'óde Ìrànjé: / Ló dífá f'Àgbọnnìrègún / Wọ́n ní: / \"kí ó rúbọ, a rẹ / kò tilẹ̀ níí mọ iye ọmọ rẹ̀ l'ójú rẹ̀ / àti lẹ́hìn rẹ̀ pẹ̀lú\". / Wọ́n ní kí ó rú: / ewúrẹ́ àti ewé Ifá. / B'ó bá rúbọ, / kí a ṣe ewé Ifá fún un kí ó / fún àwọn ìyàwó rẹ̀ jẹ. / Ó gbọ́ ó rú.", "Verso 1.4 (yorùbá): Ökùnkùn-birimubirimu: / li o dífá f'Ẹniunkokunjú. / Wọ̀n ni: / \"kosi eniti o maa fi oore sẹ / ti ko maa fi ibi suu\" / A niki ó rú: / àdá ati akaso. / Ó kọ ko rú. / Eniunkokunjú-orukọ ti a npe Àgbẹ̀ / Gbogbo oore ti gèdẹ̀ se f' Àgbẹ̀ / Ko kun lojú / Bibẹ ni Agbẹ̀ bẹ Ôgèdẹ̀ lorí nikẹhin.", "REZO: BABA EJIOGBE ALOKUYE IRE MOWADE ABATA BUTU AYE ERU OSHE BANU OBARANIREGUN IRU OBATALA OGBONI ASIFAFUN GBOGBO ORUN GBOGBO LOWO ESHU OMA ATOTOLO OLE AFEKAN ADIFAFUN OBATALA OSHEREIGBO OBI ITANA AMBIAMA ITANA AMBIAMA EYELE MEDILOGUN ELEBO.", "SUYERE: ASHINIMA ASHINIMA IKU FURIBUYEMA ” ” ARUN ” ” ” OFO ” ” ” EYO ” ” ” EGUO ” ” ” ONA ” ” ” ARAYE ” AWO OSHEMINIE, OSHEMINMIE, …", "REZO: ORUNMILA NI ODI ELESE MESA, MONI ODI MESE ONI OKO MESE TIRE KO BAJA.", "REZO: BABA EJIOGBE ORUNMILA MIGBATI OLOGBA ASHE LAWO OLODU- MARE ORUBO. OLORDUMARE MEWA FI ASHO FUN MIGBATI GBOGBO KIYE GBOGBO OTIGBA ASHE LOWO OLORDUMARE AWON NIWO TO- GBOGBO EYI TI SHINSHE LATI IBA MOWA NI AMUPE ASHO.", "REZO: BABA EJIOGBE ONI WAYU OWO OBA OÑI ODE ADIFAFUN IFE LOYA TINSHOMOBE GBOGBO KOEYEBO AGBOBOADIE LEBO, ONI LENO OWO BOYURINA ONA DAKE ADIFAFUN ORIBIDE, ADA, ARIDA, TUTU AGUTAN LEBO, OPOLOPO OWO ADASILA KOSILE, INSHERI LEBO.", "REZO: BABA EJIOGBE ALALOKUN MONI LEKUN OKO, AYA LALA OMODU ABOSHUN OMO ONIKOSHE OISHE KAMU ILEKE OMO LERI ADIFAFUN ALADESHE IMAPAPORO TIMBALORDI AGOGO.", "SUYERE: BABA EJIOGBE ORUNMILA NIODERE LEYERI ERAN ” ” ” ” ” EKU ” ” ” ” ” EYA ” ” ” ” ” EPO ” ” ” ” ” ADIE ” ” ” ” ” EURE", "NIODRE LEYERI ASHANA IKU ” ” ” ARUN ” ” ” OFO ” ” ” EYO, ONA, OGU, ETC.", "REZO: BABA EJIOGBE ALALAKUN OBA ONI FAKUN BABA AUN BINIYA OKUN DABA ALALA BI OKU BABA OTOKO BABA ARARRORO ATONO NISHE IFA BABA OFIDEYABA LODAFUN BARABAIREGUN.", "REZO: BABA EJIOGBE IBE ALAPILI YOKO DIDO BABALAWO LODAFUN BARABA ODDUN ONIRE DAFUN.", "REZO: ETA ONI BABALAWO LODAFUN ARDERE. AWO ARDERETE ORUBO AUN META.", "REZO: ERIN ONO BABALAWO LODAFUN AREBE OKO AWO AREBEOKO KORUBO NI ARAYE AFIBORAN SHE UNYO. IFA ONI BABALAWO LODAFUN ADFA ORUBO AUN MEFA. EYI ONO BABALAWO LOFAFUN BARABARIREGUN ONI BABALAWO ONI BARABANIREGUN ORUBO AUN MESAN MEFAKI AYA OBANIRI KOBESA LASHARE.EWA ONI BABALAWO LODAFUN BARABANIREGUN AWO BARABANIREGUN ORUBO AUN MEWA LAWAGIRO ADO AWO LAWAGORI ILE AWO.", "REZO: BABA EJIOGBE ONI TEGUN ONI TOSAN ENLO SODE ONI YERI ENLALO OFE OYE ODUWA TANI AUN SOYE KETEFA AYA TOYA TAMI OBA OPA OLOKUN KOTAKUN KITAKUN OMI GODO AWO APALOKUN BANILU BANLORUN GBOGBO LOWAYU PETUKIE SODE ALAGUEDE OMA ORIKU BABAWA.", "SUYERE: TINI YOBI ABE OBILENA ADAFUN GBOGBO TENUYEN ABANSHE-KE ASHOKO ODUFUO BEWA."]}]$q$::jsonb),
(2,'04ce1ab774b02ebc20c19d3fe922b8fc',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Méjì es el segundo de los Odù y representa el principio femenino; junto con Èjìogbè dio vida a los demás. Habla de oscuridad, tristeza, enfermedad y peligro de muerte, pero trae en sí misma la solución a todo eso. Cuando la persona está en mala fortuna solo encuentra obstáculos; cuando está en buena, tiene un fuerte respaldo de sus ancestros."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Siente que una etapa se cierra antes de dar fruto: tristeza, obstáculos o incertidumbre.", "Le preocupa la salud o la vida de un hijo o de alguien de la familia (relato de Onibijé).", "Busca prosperidad en su trabajo y no ve el valor de algo que tiene enfrente (relato de Òyè y el amanecer).", "La casa y el trabajo van cada uno por su lado; cuando se unen, llega la alegría (relato de Onikabidun).", "Hay celos o relaciones que le frenan; le conviene escuchar a los mayores.", "Necesita resistir sin quebrarse ante un viento fuerte (relato de la palma).", "Debe distinguir qué ciclo le toca cerrar y cuál le toca proteger."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Riqueza que llega desde el lugar de trabajo.", "Larga vida para la persona y para sus hijos.", "Algo que hoy no valora se convertirá en su fortuna.", "Alegría duplicada en la casa y en el trabajo, con abundancia e hijos.", "Paz después de haber luchado, y conservar lo ganado.", "Hijos que, aun con alguna limitación física, triunfarán en la vida."]}, {"titulo": "Ibi y advertencias", "puntos": ["Muerte repentina, enfermedad y preocupaciones si no se atiende la ofrenda.", "Depresión: hay que atender la cabeza (Orí) de vez en cuando.", "Tener relaciones con muchas parejas trae celos y problemas que frenan el progreso.", "No escuchar a los mayores ni honrar a los ancestros.", "Una vida que va en zigzag de la buena a la mala fortuna, y la dificultad para aceptar la alegría."]}, {"titulo": "Enseñanza principal", "texto": "La oscuridad no es el final: el amanecer llega aunque la noche sea larga. Ọ̀yẹ̀kú Méjì pide constancia en la ofrenda, respeto a los mayores y a los ancestros, y fidelidad a una sola pareja. Así como la palma resiste el tornado porque ofreció, quien cumple aguanta los vientos de la vida."}, {"titulo": "Relatos reunidos", "puntos": ["Ọlọ́fin y la tela negra. Ọ̀yè dúdú, el adivino de Orí Bìjé, consultó para Ọlọ́fin y le marcó una tela negra, una chiva y hojas y frutos de bìjé, para que ni la muerte se lo llevara a él ni la muerte repentina a sus hijos. Ọlọ́fin cumplió. Por eso, cuando sale este Odù, la familia se marca la cara con bìjé y cubre su Ifá con tela negra y hojas de bìjé: la muerte no reconoce a quien lleva la medicina de bìjé.", "La palma y el tornado. Eesin gbona l'ewé tutu l'egbo consultó para los 165 árboles. A la palma y al árbol de àyìnrẹ̀ les marcó un pollo que debía pasearse alrededor de los árboles. La palma cumplió, y desde entonces, cuando un tornado arrasa, la palma joven dice: 'Yo hice la ofrenda para escapar del peligro'. Ningún viento la tumba.", "Los dos hijos de Ọlọ́fin. Dos Ọ̀yẹ̀ consultaron para Ọlọ́fin y le dijeron que dos de sus hijos se fracturarían las piernas, pero que no se entristeciera, porque los dos triunfarían en la vida. Le marcaron una tela kẹlẹku para cubrir a sus hijos. Cumplió, y la limitación de los hijos no estorbó su prosperidad.", "Òrìṣà-ńlá pregunta por sus hijos. Òrìṣà-ńlá fue a ver a Ọ̀rúnmìlà y le preguntó qué hacer por los hijos que había traído a recorrer el mundo, para que no padecieran frío, dolores de cabeza, fiebres ni otras enfermedades. Ọ̀rúnmìlà le mandó marcar Ọ̀yẹ̀kú Méjì en iyẹ̀rosùn, moler hojas tiernas de pèrègún, mezclarlas con manteca de òrí y untarlas en el cuerpo, diciendo: 'El siempre verde pèrègún echa agua sobre la muerte furiosa; el siempre verde pèrègún echa agua sobre la enfermedad furiosa'.", "El amanecer que quería ser rico. Ifá consultó para Ọ̀yè, el amanecer, que brillaba desde el cielo y preguntaba si llegaría a ser rico. Le pidieron ofrecer para que sus rayos brillaran. Ofreció, sus rayos se volvieron muy brillantes y la vida le sonrió: Ọ̀yè se volvió dos mitades iguales y la bandeja de Ifá se llenó hasta el borde.", "Los campesinos y la chufa. Ifá consultó para un grupo de campesinos que iban a escoger tierra para sembrar dentro del monte y querían saber si volverían con buenas ganancias. Ọ̀rúnmìlà les pidió ofrecer y les dijo que sembraran chufa. Al cosechar, las semillas parecían cuentas de coral (iyùn), y la vida les fue muy provechosa. Cantaron: 'Sembramos chufa y nos llevamos cuentas a casa'.", "Onikabidun y las azadas. Ifá consultó para Onikabidun cuando quería aumentar su felicidad, y le marcó cinco azadas tratadas con medicina de Ifá. Llevó las azadas a su casa; la gente de la casa las llevó a la granja y la gente de la granja llevó las suyas a la casa. Se encontraron a medio camino: los de la granja dijeron que sus azadas servían para cavar fortuna y los de la casa que servían para enterrar placentas de recién nacidos. Feliz, cantó: 'Que la gente venga a mí con alegría: alegría en la casa, alegría en la granja'. Esta persona tiene problema para aceptar la alegría y debe cambiar esa actitud.", "La mona que no suelta a su hijo. Ifá consultó para la mona (Ape) el día que no quería perder lo que tenía, y le aconsejó ofrecer. Ofreció, y desde entonces, cuando la mona se columpia de árbol en árbol con su cría a la espalda, la cría nunca se cae. Cantó: 'Ofrezco ñame machacado; la casa no tiene infortunio'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọlọ́fin: tela negra, una chiva y hojas y frutos de bìjé; marcar la cara con bìjé y cubrir el Ifá con tela negra.", "La palma: un pollo paseado alrededor de los árboles.", "Los hijos de Ọlọ́fin: tela kẹlẹku para cubrirlos.", "Medicina de Òrìṣà-ńlá: hojas tiernas de pèrègún molidas con manteca de òrí e iyẹ̀rosùn marcado con el Odù, untadas en el cuerpo.", "Onikabidun: 4 palomas, 4 gallinas, una rata, un bagre negro, aceite de palma, un plato blanco y dinero, a Ìbejì; cinco azadas marcadas con iyẹ̀rosùn para la casa y cinco para afuera.", "La mona: 5 palomas, 4 gallinas, un plato blanco, aceite de palma, ñame machacado y dinero, a Ìbejì; ñame machacado al Òrìṣà de la persona y lana enrollada en la olla de su Òrìṣà. Prohibido: rata gris, y taparse la cabeza con hojas cuando llueve."]}, {"titulo": "Relaciones espirituales", "texto": "Orí debe apaciguarse con frecuencia para no caer en la tristeza. Los ancestros sostienen a la persona cuando está en buena fortuna. Òrìṣà-ńlá y Ọ̀rúnmìlà aparecen cuidando a los hijos del mundo. Ìbejì recibe las ofrendas de alegría y de conservar lo ganado."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Bìjé (hojas y frutos), pèrègún, manteca de òrí, iyẹ̀rosùn, àyìnrẹ̀, palma, chufa, ñame machacado, tela negra y tela kẹlẹku."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 2.1 (yorùbá): Oyè dúdú awo Orí Bijé: / li o dífá f’Ọlọ́fin. / A niki ò rú: / Aṣo dúdú, ewúrẹ, ewé ati eso bijé. / A ni ikú ti o nbọ yi ko niipaa, / ko niipa omo rè, / bi o ba rúbọ / Ó gbọ̀ ó rú.", "Verso 2.2 (yorùbá): Eesin gbona l'ewé tutu l'egbo: / li o dífá fún Márünlelogéjọ igi oko / Opẹ̀ ati Ayinrẹ li o ru: / Oromodie ninu wọn / Nitorinaa bi iji ba nja / Ọgọ mariwo a ni: / \"Oun ṣẹbọ Öyèkẹṣẹ\".", "Verso 2.3 (yorùbá): Two bye. / Emi ọ̀yọ̀, / Qyẹ̀ Méjì: / li o dífá f’Ọlọ́fin / Wọ̀n nì: / “Méjì a ṣe’tan ninu àwọn ọmọ rẹ̀ / ti o maabi ṣügbọ̀n kioma binu / nitoripe won a ri're\". / Wọ̀n niki ó wa rúbọ: / agp Kplẹku, / ki àwọn ọmọ na mafi bo'ra. / Ó gbọ̀ ó rú.", "Verso 2.4 (yorùbá): Jiji ni mo ji / mo b'omodé wẹrẹwerẹ, / mo bere Isalu Ayé, / mo b'awarẹ sokąsoko, / mo bere Isalu Orun. / Oriṣà-ńlá nlọ sọdọ Ọ̀rúnmìlà, / ò n: / Awọn omodé rẹ ti oun nko lo si Ayè yi? / Otutu mai dee? / Efori mai dee? / Ẹdunra ati bẹẹbẹẹ mai dee? / Kini ki oun maaṣe fún wọn? / Ọ̀rúnmìlà 1 kiotẹ / Odù Ọ̀yẹ̀kúméji ni iyè-iròsù, / kio ja aṣẹṣẹyo pèrègún ki o lọọ / ki o pa wọn pọ mọ òrí / ki o maa fi para fùn wọn / Pèrègún ṣuṣu a d'omi pa'ną ikú / Pèrègún-ṣuṣu a d'omi pa'no arùn.", "REZO: OSHEIWONO OSHEKU OMO OLOKU AWO ONI OGBONI OGUNGUN UMBOWNILE ORUNMILA OSORDE OYIYI EBBO ORINDILOGUA ABO KAN OSHEIWOMO KOBO IYAKU EGGUNGUN BABA ALAGBANAGBA OKUNI OLEJA IKONONIYE TADAGO ASHIKUELU OAJO OYEKUN AWO KOBO OSODE OSHEIWONO OSHEUNLO EGGUN ADIFAFUN OMO OLOKUN AWO KAFEREFUN EGGUN.", "REZO: BABA OYEKUN MEYI ARIKU MADAWA EYO OGGUN SIGUN MOLE POROREYARUN OÑI PO UN BABALAWO ADIFAFUN OGBE OLUWO AGOGO, ABO LEBO.", "REZO: BABA OYEKUN MEYI BABA OLOFIN OYU INLE EGBA NIYERUN EGBA AKUE LELE SHANGO OKO OMO ABBA AYE OWO ORINDILUGUN BEWA OYEKU IFA SHANGO ATEFA ODDUN IFA OKUE DARA ORUNMILA NI LARE IFA ODARA BABA MOKIO SHANGO MORARA OBBA OKUELELE OYEKU MEYI BOYOMIWO AWO KUELELE BABA OLOFIN ORUNMILA AYOYE ORUN OMI BARGABANI LEGUN.", "REZO: OYEKUN MEYI BABA OYEDI ADIFAFUN BAREOKO OYO OYIMI FUN OKANA REFU OKUDA.", "REZO: ADIFAFUN SHANGO OYIYI OPON EYA TUTU EKUADO EYA TUTU EYIGUMEKUN ARUYE OTENURE AYE AIYE CONYE AIKU OFO ARUN IKU OPA NI EGUNGUN KOPONI SHANGO KOPONI OLOFIN EYA BATUTO UMBO WAIYE SEKUN ODARA LODAFUN SHANGO EYA OMOLORUN KAFEREFUN OLEYE KAFEREFUN OLOFIN.", "REZO: AYAYA OMONIFUN AFON BALE BELELE IROKI ADIFAFUN AWOYENI OMOLUNI ORUN OSHUN AWONI ORUBO NATORI OMO OGBONI OFOJI OMI OSI OGBO ERI ATUKESHU OTUN KAKARA EBBO YAFUN AWON OÑI IFA INLE OSHUN OBAYEWO BEWA OBALU AYE OMOLU ORUNMILA ORUN LALA OSHUN KAFEREFUN OBALU AYE KAFEREFUN ORUNMILA.", "REZO: IWO OYE EMIOYE OYE SHESHENLA BOLOKE AWOSHE BOYUMO NIMO ADIFAFUN EYA TINSHOMO WO LADE ODO AWONI EYA ORUBO AWONI PIPO NIRE OMODE SHUGBO BORUKO KORUBO AREYE KORU ONI BAWO LAWO OTA ASHELE ONIRAN ARAWO OMO OUN LALE ODO OPAWO LEKE OPA ESHU LOLE OWORUN ÑAÑA BI ENITI ONIKU OKOTI OSHEBO TOMO ARAYE DIDE AWO NAWO OKO ADA ATI OGBUN AWO SE ODU AWO SIBERE SIGBONO IGBA TO MITALEÑ EYA ATI AWO OMO ORE NI AWO OMO ARBAMU AWO AGBA SIFI AGBALERI IÑA", "ASHE ESHU NI KOYEBI AWO OMO EYA OLE ELAYE ASHUGBO TITI DONI OLONI AWO OMO ARAYE IKO AWO OMO EYANI.", "REZO: OKUNI KIAGE KEKO MAMU OMI LOWO INLE SHISHE MANU OMO INSHE ILE LODAFUN ORUNMILA ADIFAFUN OKUNI KAFEREFUN ASHEDA.", "REZO: BABA OYIYI MEYI ADIKU MADAWA FOFO FORO ORANIYAN OMO OKUNI AKIO ALABARA MANA MANA SHANGO SHANGO OYA MINI BABA ALAFIA OBA EYO LAMORUN IFE ALORUN OLOYO OBANIYAN OBONIBOSHE AKINFA ADIE WAWASHE TI AGUEMA AKUA ODUDUWA WAWASHE TIBONI ASHE OSHA LOWA OSHAGRIÑAN AIGAN INLE IBARIBA EYOLA ORANIYAN OBA ALAIYELUNA.", "SUYERE: EYO PAPA FOCHO WAO SATORI ABORENSE BOBOIKU PAKOLEPA ATORI.", "SUYERE: BABA IKU OSHEUWOMO OSHE UNLO EGUNGUN.", "REZO: OSHEIWONO OSHEKU OMO OLOKU AWO ONI OGBONI OGUNGUN UMBOWNILE RUNMILA SORDE OYIYI EBBO ORINDILOGUA ABO EKAN OSHEIWOMO KOBO IYAKU EGGUN GUN BABA ALAGBANAGBA OKUNI OLEJA IKONONIYE TADAGO ASHIKUELU OAJO OLOKUN AWO KOBO OSODE OSHEIWONO OSHEUNLO EGGUN ADIFAFUN OMO OLOKUN AWO KAFEREFUN EGGUN.", "SUYERE: BABA IKU OSHEUWOMO OSHE UNLO EGUNGUN.", "REZO: OYEKUN MEYI BABA OYEDI ADIFAFUN BAREOKO OYO OYIMI FUN OKANA REFU OKUDA.", "SUYERE: “EYO PAPA FOCHO WAO SATORI ABORENSE BOBOIKU PAKOLEPA ATORI”.", "REZO: ADIFAFUN SHANGO OYIYI OPON EYA TUTU EKUADO EYA TUTO EYIGUMEKUN ARUYE OTENURE AYE AIYE CONYE AIKU OFO ARUN IKU OPA NI EGUNGUN KOPONI SHANGO KOPONI OLOFIN EYA BATUTO UMBO WAIYE SEKUN ODARA LODAFUN SHANGO EYA OMOLORUN KAFEREFUN OLEYE KAFEREFUN OLOFIN.", "REZO: AYAYA OMONIFUN AFON BALE BELELE IROKI ADIFAFUN AWOYENI OMOLUNI ORUN OSHUN AWONI ORUBO NATORI OMO OGBONI OFOJI OMI OSI OGBO ERI ATUKESHU OTUN KAKARA EBBO YAFUN AWON OÑI IFA INLE OSHUN OBAYEWO EWA OBALU AYE OMOLU", "ORUNMILA ORUN LALA OSHUN KAFEREFUN OBALU AYE KAFEREFUN ORUNMILA.", "REZO: IWO OYE EMIOYE OYE SHESHENLA BOLOKE AWOSHE BOYUMO NIMO ADIFAFUN EYA TINSHOMO WO LADE ODO AWONI EYA ORUGBO AWONI PIPO NIRE OMODE SHUGBO BORUKO KORUBO AREYE KORU ONI BAWO LAWO OTA ASHELE ONIRAN ARAWO OMO OUN LALE ODO OPAWO LEKE OPA ESHU LOLE OWORUN ÑAÑA BI ENITI ONIKU OKOTI OSHEBO TOMO ARAYE DIDE AWO NAWO OKO ADA ATI OGBUN AWO SE ODU AWO SIBERE SIGBONO IGBA TO MITALEÑ EYA ATI AWO OMO ORE NI AWO OMO ARBAMU AWO AGBA SIFI AGBALE RI ÑA ASHE ESHU NI KOYEBI AWO OMO EYA OLE ELAYE ASHUGBO TITI DONI OLONI AWO OMO ARAYE IKO AWO MO EYANI.", "REZO: OKUNI KIAGE KEKO MAMU OMI LOWO INLE SHISHE MANU OMO INSHE ILE LODAFUN ORUNMILA ADIFAFUN OKUNI KAFEREFUN OSHEDA."]}]$q$::jsonb),
(3,'6ae77a7cc4e7556b3e40ab3e9f17bd26',$q$[{"titulo": "Idea central", "texto": "Ìwòrì Méjì es el Odù de la gente que ve las cosas como son: sueñan, tienen visiones claras y pueden llegar a ser adivinos. En este signo Ifá confirma que los dieciséis ikin son la representación de Ọ̀rúnmìlà en la Tierra. La persona está revisando su vida y su estado espiritual; lo que se perdió se recupera, y lo bueno que no llegaba ya está cerca."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está repensando su vida y siente que debe cambiar de rumbo, pero no sabe qué conservar.", "Perdió algo o una oportunidad y quiere recuperarla; lo que se veía lejos empieza a acercarse.", "Busca un ascenso o estabilidad en el trabajo y tiene detractores; un éxito rápido no es lo mismo que uno que dura.", "Piensa viajar o entrar en un ambiente desconocido (relato de Olu, que viaja y vuelve con abundancia).", "Le preocupa enfermarse él o alguien cercano (relato de Opakẹrẹ).", "Se siente solo, desea pareja o hijos (relatos de Òde Gbànňsàsà y de Ìwòrì Méjì).", "Tiene un enemigo del que necesita librarse (relato de Òde y Awasa)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Larga vida, abundancia, pareja e hijos para quien adora a Ifá.", "Recuperar lo que se perdió.", "Un ascenso en el trabajo, si se ofrece contra los detractores.", "Un viaje del que se vuelve con abundancia, ganando en tierra ajena.", "Que el enfermo sane con la ofrenda correcta.", "Compañía para quien vivía solo."]}, {"titulo": "Ibi y advertencias", "puntos": ["Éxitos que duran poco: riqueza, trabajo y alegría que se van pronto si no se ofrece por la estabilidad.", "Detractores que buscan degradarlo después de un ascenso.", "Ver cosas malas en un viaje.", "Una enfermedad que se acerca."]}, {"titulo": "Enseñanza principal", "texto": "Lo que llega rápido se va rápido si no se asegura. Òde ofreció para librarse de su enemigo, pero no quiso ofrecer para que su gente se quedara con él, y desde entonces la fiesta llega y se va. Hay que ofrecer también por lo que debe durar."}, {"titulo": "Relatos reunidos", "puntos": ["Opakẹrẹ no enfermará. Mujimuwa, el adivino de Opakẹrẹ, le advirtió que ofreciera para no enfermarse: veinte anzuelos con veinte palomas. Cumplió, y le prepararon hojas de Ifá para lavarse la cabeza y lavar su Ifá. El adivino le aseguró que nunca estaría enfermo.", "Òde y Awasa. Gbẹgi jebete consultó para Òde, que tenía como enemigo a Awasa, y le marcó un garrote y una carga de ñames. Òde cumplió. Machacaron los ñames y los comieron en la noche; se fueron a dormir, y cuando llegó Awasa en la oscuridad, Òde lo mató con el garrote. A la mañana siguiente encontraron su cuerpo afuera.", "Ìwòrì se casa con la hija de Ọlọ́fin. Ògún-ribiti consultó para Ìwòrì Méjì cuando iba a casarse con Ọ̀pẹ, la hija de Ọlọ́fin, y le marcó una gallina para que su esposa nunca fuera estéril. Cumplió, y el adivino dijo: 'Ni la palma hembra ni la palma macho serán estériles'. Por eso los hijos de este Odù siempre tienen descendencia.", "Òde y la fiesta que no se queda. Ifá le dijo a Òde que ofreciera una piedra de afilar y una estera para que todos los que venían a festejar con él se quedaran a su lado. Òde no quiso y dijo que le bastaba con haberse librado de Awasa. Por eso la gente viene a celebrar con él, pero nadie se queda: los hijos de este Odù tienen éxitos de poca duración mientras no ofrezcan por la estabilidad.", "Òde Gbànňsàsà encuentra compañía. 'Grillo, que no se lamente más antes de que caiga la noche.' Así consultaron para Òde Gbànňsàsà, que lloraba porque no tenía compañera. Ofreció, y Èṣù le mandó las fortunas, entre ellas una compañera. Su éxito merecía que se bailara: 'Òde Gbànňsàsà, ven a bailar al ritmo del tambor'.", "La cola del búfalo. Ifá consultó para Ọ̀rúnmìlà cuando dijo que formaría una sombra que cubriera la Tierra y preguntaba si llegaría a ser grande. Ofreció, y no hay lugar en el mundo donde no se le conozca: donde se hace el bien se reconocen sus manos y sus enseñanzas, y su poder trajo paz firme.", "Olu juega ayo con Olókun y Ọlọ́sà. Ifá consultó para Olu cuando iba a la casa de Olókun, el espíritu del mar, y a la casa de Ọlọ́sà, el espíritu de la laguna, y le pidió ofrecer para que el viaje fuera bendecido. Cumplió. En casa de Olókun le ganó tres veces al ayo, y Olókun había prometido la mitad de sus bienes a quien le ganara. En casa de Ọlọ́sà pasó lo mismo. Así recibió la abundancia y cantó: 'Jugué ayo con Olu y recibí una bendición en casa del extranjero'. Esta persona encontrará buena fortuna con un extranjero.", "Los hijos que no son tratados como muertos. 'Lo que a ti te gusta a mí no me gusta.' Así consultaron para los hijos de Omimuti Ìwòrì, que temían ser tratados como si estuvieran muertos. Ofrecieron, y el adivino dijo que nunca se ha visto a un muerto cavando la tierra. Desde entonces se les reconoció entre los vivos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Opakẹrẹ: veinte anzuelos y veinte palomas; lavado de cabeza y de Ifá con hojas de Ifá.", "Òde contra Awasa: un garrote y una carga de ñames, que se machacan y se comen en la noche.", "Ìwòrì Méjì: una gallina para que la esposa sea fértil.", "Òde (rechazado): una piedra de afilar y una estera para que la gente se quede.", "Olu: una paloma, una gallina, un plato blanco, ẹ̀kọ y dinero, a Ọbàtálá; una oveja a Ẹlẹ́dá.", "Contra la muerte y la enfermedad: 4 palomas, 4 gallinas, un plato blanco, 4 ẹ̀kọ de ñame, una rata pequeña, aceite de palma y dinero, a Ìbejì y Ọbàtálá; recibir dos juegos de Ìbejì, uno femenino y uno masculino. Prohibido: perro y fruta òrí."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà está representado por los dieciséis ikin. Èṣù envía la compañía a quien ofrece. Olókun y Ọlọ́sà son dueños del mar y de la laguna. Ọbàtálá, Ìbejì y Ẹlẹ́dá reciben ofrendas de protección."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Anzuelos, ñame, garrote, piedra de afilar, hojas de Ifá para lavar la cabeza, hoja de alájàngbàlúù."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 3.1 (yorùbá): Mujimuwa awo Ọpakẹrẹ / li o dífá f'Opakẹrẹ. / Ó niki ó rúbọ / ki o ma baa ṣaisan: / Ógún Iwọ pẹlu ógún eyẹlé / Ó gbọ̀ ó rú. / Ó ṣe ewé Ifá fún un / ki o fi fọ Ori, / ki o si fi wẹ Ifá rẹ̀. / Ó ni: \"Opakẹrẹ ko maa ṣaisan\".", "Verso 3.2 (yorùbá): Gbẹgi jebete: / li o dífá fún Ode, / nigbi Awasa nbaa iṣo'tá. / Wọ̀n niki ó rú / Olugboro ati ẹru-iṣu. / Ode gbọ̀ ó rú. / Wọ̀n gun'yán / Wọ̀n jẹ yán tán ni alẹ / Wọ̀n sun / Nigbati o di oru / Awasa mbọ / Ode fi Olugboro owọ̀ rẹ paa / Nigbati o di owuro qjẹkeji / Wọ̀n ba okú Awasa ni òde.", "Verso 3.3 (yorùbá): Ogün-ribiti: / ll o difá fún Iwòriméji, / nigbi Iwòriméji mi la fẹ Ọpè / tiiṣe ọmọ Ọlọ́fin / Wọ̀n ni ki o wa rúbọ, / koni'id'àgán. / Abo-adiyẹ li ebọ / Ó gbọ̀ ó rú. / Wọ̀n ni: / \"Tako tabo opè kiid'ágàn\".", "Verso 3.4 (yorùbá): Tijótayọ̀: / li o difá f'Ode / Wọ̀n ni ki o wa rúbọ / ọlọ ati eni, / ki àwọn ti nwa yọ li ọ̀dọ̀ rẹ / le maa joko tii. / Ode kọ ko rúbọ / Ó ni: bi oun ba ti p'Awasa ṣa o to.", "REZO: IWORY MEYI YIGUI YIGUI MAYO MAYO ADIFAFUN KOKOLO YEBEIFA TIROKEYA LAMPE SHANGO ARONI YEO ELEREPIN ORUNLA LORUBO.", "REZO: OSHISHE KOLORI MILLEKAN OKONI FINIGONI HANDU ADIE ANI BABALAWO. LODIFAFUN ARERE ONI OLOKUN OMO AYA ARELELO ORONOPIN IWORY MEYI YIGUI YIGUI MAYO MAYO ADIFAFUN KOKOLO YEBEIFA TIROKEYA LAMPE SHANGO ARONI YEO ELEREPIN ORUNLA LORUBO.QUIOLORUN ABO AKORDIE EKU EPO ABEFA OWO.", "REZO: ASHESHE KODORA ALOSHIN KONI LLEGANARARENI PURU INA GUEGUI IBADU ADIE CUN BABALAWO LODIFAFUN ARERE ONI LORUN UBEALLARERE ARONIPIN EYA LONOBO KOLA ODENE NI MU ABATASHOSHIN OKUTA GUERA LODE EMBORUSHOLA NATA PERE BORO KARAIDEFAFUN AKATO AYARE NIBATI OLO RUN ENGUERE LEBO.", "REZO: OTICOGUE SHOMO NIDE MAGUELE ADAFUN BALE TINSHO MOIGUE ARUMBON AIDO DIE MELLE LEBO OWO LA MEYO MEYO ASHISHA OMO ALARA OTONISHA YEKAN ORONIPINI EYA LENU SHOLA EREBEN Y TINLA BORO BORO SOKO AYA OTAN ADIFA FUN OKOTE AYARE ARIMI BATIALOKUN GUERENGUERE LEBO.", "REZO: IFA ANULA BOBORO KOKO BOISHE BORE KARINKUNKU BORU SHOLA AIDAFUN OLOKUN KOKOTO AYARE.", "REZO: EBENEGU SHOLEN ORE BENINUN ABALU OKUTE BERE OMO NIMA OMO ITI KONIOGUE ANUMIN PANIUN OLDE OUKO BORU SHOLA INATA BOROBORO AYO, OTAN BORO, BORO KAMU ADIFAFUN YOKAFUN OKOTO AYARE OWUNKO AKORDIE EYELE OWO LA MEFA OKU EYA.", "REZO: YIGUI YIGUI MOYO ADAFUN UMBATOLO LOORBA LODA BOBO KEKE OMOLONGO ODAFUN YONLO ODE BALASA ODIYO ODERE ODE BALASA ODERE EBO EWE META GUAGUA BANETA EL LEÑA Y UN EKO.", "REZO: IFA O. ODIFAYOKO OKANIKO ENLE KOKORIOKO LELUN KOKORIOKO RUBO KINKO MELLA AKORDIE ADIE MELLI ADOFA ELBO FUN KORIKO YOMBA, LOIGODO OKON RESHEGUE ASECERO GRI GRI LONIO BABALAWO ADOFA YOKO FUN SHEKERE DIBAYU TANTO LOYE BABARE ARENI IGUS ARE NI ODI OFA SHEGUE ORONI MOLE OFE.", "REZO: OSHISHE OMO LARA ATISHE KONI YEKAN ARONI GUIN NIPONI IBA DUADIE UN BABALAWO LODIFAFUN ARERE ONI OLORUN AYAERELO ARONI GUIN EYA ABEMEBU SHOLA ARE BEUN MABADA SHO ESHUN EKUTA GUEREGUERE NI OMO ITIKOKO MOPE ORUN OSHUPA NI OMODE BARUN SHOLA BORO SOKO AYO OTA BORO KARUN ADIFAFUN KOTO EYELE.", "REZO: AKASO FARATILE LODAFUN KONISA, BOGO ODI AKUKO AKOFA EKU EYA EBETA AOGUO ADIFAYOKO AKORIDO KULE KONKO LELUN KORIKO ORUGBO ADIE MELLI ONLE OKOFA EKU EYA EBETA OWO.", "REZO: IWORY MEYI AKUSHERALA OTOSHE NI YEKU ALERE NI AJALDA OGOLDE DIESDE EYELE IBO. AWO SHEKE ESOKAN QUIERE GRIGRI OLOMA TOLO FALLE GUALE ALIAKA LODAFUN ORUNLA ORUBA AKORDIE AUKO IGUALE META ERU EYA EBETA OWO. DICE QUE LA PERSONA ESTA MUY MAL Y QUE EL COJO NO PUEDE CORRER; Y EL QUE TIENE UN SOLO MEDIO NO PUEDE SONARLO. DESPUES DE LA ROGACION USARA UN PAÑUELO TODOS LOS DIAS Y ASI VERA SU ADELANTO Y LO QUE DESEA.", "REZO: ASHIBE OLARA AWO ATOSHI KONIYEKAN OBINI LANLA NIBANI NIMU NI BANDU ADDIE ODAFUN ADERE OBINI AYA OLORUN LOMU OKAN IÑI KIROSHEKE ESEHAN GUIRI GUIRI LONA ADIFAFUN OBINI AYA SHEKERELUBA OYUPAN UNLE YIWI MAYO MAYOADI AFUN TOKOLUBA OBINI UNLEUN LODE EPEITI ASHISHELEOGODO NISHOYU KEK TOLOKUN ADAPA ALANLA KUTIFIKO GBOBO ARAISHE TOLOYU OBINI KARAWA LODAFUN OBANLA KAFEREFUN OGGUN, SHANGO ATI OZAIN.", "REZO: IWORY MEYI AWO OMO NIFA ENI IFA ELEGBARA AWO OMO NIFA UNSORO AWO OMO NIFA AFEKU ELEGBA AIBALE AIYA SHON SHON LOMA OYU OBATALA OFORANLE OBATALA ILE ORUNLA EGGUN BABA ELEGBA IBURA IFA SHANGO AGBORAN OSHE OMOLO OMA MOTUMBA O IWORY MEYI AWO OMO NIFA MAFEREFUN ELEGBA OBATALA SHANGO ATI EGGUN BABARE.", "REZO: ORI BAWA LORI IBE ONONIRE ILE IKU INTORI AWO ONIRE LORI ABERE ORI OKANA GALERE LERI INA BEKE LESE SHANGO ONI SHANGO KOGIELEKUN WA NI IRE AWO OSHE OBINI ARUN OBARI INTORI IRE ORUNLA.", "REZO: ASOPEMPE YARU ADIFAFUN SARUMI TIODOLORUN ABORI YUGU ADIFAFUN ODE LEIBO OGIRI SAPALA EGIRI SAPALO AJUBU LU KORIKO LODE OBODO ARUGBO.", "REZO: SHEGUE SHEGUE SHEGUERE GUIRI GUIRI KAN GUILONO UMBATI UMPON.", "REZO: BABA IWORY MEYI OBINI META TA OFI OFI OLO ORISIRE IGUERI ALELE IWORY IFA LOGUIFUN LORUBO EURE META ISHU ILU META ERUSHI META OWO.", "REZO: ATAKARA MATIKA AIRA UYO OMA ATANI KARA EYE OKOKO MORELENI ADIFA BABA AKAFILA ELENO APOSHI APOSHIRE AWO EWE IFA AKAKARA MATIKA AJARA JERI OMOLO IKI OPA SHORO SHORO OFOTA KOTA KORU."]}]$q$::jsonb),
(4,'14702d370941279296312ce46fe33bb4',$q$[{"titulo": "Idea central", "texto": "Ìdí Méjì completa los cuatro puntos cardinales del universo y simboliza la maternidad: la unión de lo masculino y lo femenino que da a luz. Habla de enemigos ocultos, de hechizos y de pesadillas, y de una persona que no logra establecerse. Con la ofrenda llegan la buena fortuna, la larga vida y una posición elevada; lo que se hace paso a paso y con firmeza se vuelve grande."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está presionado por problemas de dinero y emocionales, teme a enemigos ocultos o tiene pesadillas.", "No logra establecerse: cambia de casa o de lugar buscando dónde echar raíces.", "Está por alcanzar una posición importante y teme perderla después; el crecimiento puede ser lento pero seguro (relato de Àkèsán y el mercado).", "Desea formar familia o tener hijos (relato de Odidimadẹ).", "Se acerca un viaje con riesgos que se pueden superar (relato de Òrúnmìlà en el camino).", "Siente que la buena suerte ya llegó una vez y se le escapó, y espera que vuelva (relato de Onibode).", "Quiere ver hechas realidad sus ideas (relato de Itẹrẹ)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que las ideas se materialicen.", "Larga vida y buena fortuna, para hombre o mujer.", "Una posición alta en la vida; lo que crece despacio pero seguro.", "Fama, paz mental, riqueza y sosiego.", "Una hija para la mujer que la desea, aplacando a Ọ̀rúnmìlà.", "Un viaje seguro si se ofrece a Ògún.", "Protección como la de una muralla alrededor de la casa."]}, {"titulo": "Ibi y advertencias", "puntos": ["Enemigos ocultos, hechizos y pesadillas.", "Cambiar de casa en casa sin echar raíces; puede ser necesario volver al lugar de nacimiento.", "Trabajar duro y perderlo todo al final si no se ofrece a los ancestros.", "Muerte súbita si no se adora a Ifá.", "Detractores al subir de posición."]}, {"titulo": "Enseñanza principal", "texto": "Hay que ser veraces, honestos y rectos en el trato con los demás, y tener los pies en la tierra. La red de pesca se teje con pequeñas vueltas de la mano y termina siendo enorme: así crece lo que se hace con constancia."}, {"titulo": "Relatos reunidos", "puntos": ["Itẹrẹ y las ideas que se cumplen. Atẹlẹwọ́-abinutelu consultó para Itẹrẹ y le dijo que sus ideas siempre podrían hacerse realidad. Le marcaron clavos de cabeza, tres chivos y tres gallos, y medicina de Ifá para beber. Cumplió. Los clavos de cabeza significan que sus sueños e ideas llegarán a buen término.", "La cadena que la muerte no rompe. La muerte estaba matando a la gente de Ilé-Ifẹ̀. Opa-aro abidijegelege les marcó una cadena y un carnero. Ofrecieron, y el babaláwo dijo: 'El eslabón sencillo nunca se rompe; por eso las manos de la muerte ya no pueden tocarlos'. Así se detuvo la muerte fuera de tiempo.", "Odidimadẹ y su hijo. Odidi-afiditi le aconsejó a Odidimadẹ ofrecer dos cocos grandes, dos babosas y 3,200 cauríes. Se negó, y el babaláwo dijo: 'Tu hijo nunca hablará en esta vida'.", "La muralla que protege la ciudad. Durante una guerra entre pueblos, los adivinos consultaron para la muralla (Odi) y le dijeron que protegería la ciudad si ofrecía dos telas para abrigar. Cumplió. Esto vale para toda familia o persona que necesita protegerse de lo que amenaza su estabilidad.", "Àkèsán, el primer mercado. 'Con pequeñas vueltas de la mano se teje la red, y termina siendo tan ancha que se traga un mortero.' Así consultaron para Àkèsán, el primer mercado creado en la Tierra, gobernado por una mujer rey, para que tuviera mucha gente. Ofreció en cientos, y desde entonces el mundo entero acude a Àkèsán, el mercado que guió a todos los demás.", "Àjòjì gòdògbò en Benin. El caracol no hace la base del tinte, ni se espera que el pollo vuele. Así consultaron para Àjòjì gòdògbò, el extranjero que iba a ejercer la adivinación en Benin y preguntaba si le iría bien. Le dijeron que ahí encontraría su fortuna si ofrecía. Ofreció y se hizo riquísimo. Cantaban: 'Ayúdanos a reconstruir Benin, Àjòjì gòdògbò'.", "Onibode y la bondad dos veces al día. 'Las dos nalgas en que me siento me dan comodidad.' Así consultaron para Onibode Ejiejiemogun, que quería que la bondad lo recibiera dos veces al día. Ofreció, y desde ese día así fue. Esta persona cree que la buena fortuna ya pasó de largo y se le escapó entre los dedos; debe seguir optimista y rezar con constancia a su Òrìṣà para que sus sueños se cumplan.", "Ọ̀rúnmìlà y los tres lugares de la muerte. Ifá consultó para Ọ̀rúnmìlà el día que debía pasar, cargando al pato, por los tres lugares donde se reúne la muerte. Le pidieron ofrecer para que la muerte, la enfermedad y las piedras de los problemas no lo alcanzaran. Ofreció, y los dos pasaron sin daño."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Itẹrẹ: clavos de cabeza, tres chivos, tres gallos y medicina de Ifá para beber.", "Ilé-Ifẹ̀: una cadena y un carnero.", "Odidimadẹ (rechazado): dos cocos grandes, dos babosas y 3,200 cauríes.", "La muralla: dos telas para abrigar.", "Onibode: 4 palomas, comida variada, 4 ẹ̀kọ, aceite de palma, un plato blanco y dinero, a Èṣù.", "Contra la muerte y la enfermedad: 3 piedras duras, 3 palomas, ẹ̀kọ, un carnero, un plato blanco y dinero, a Èṣù. Prohibido comer el ñame que se rompa al sacarlo de su recipiente y cavar hoyos cerca de la entrada de la ciudad.", "Para la mujer que desea hijos: aplacar a Ọ̀rúnmìlà. Para viajar: ofrenda a Ògún. Ofrendas constantes a los ancestros."]}, {"titulo": "Relaciones espirituales", "texto": "Orí y Ẹlẹ́dá, la cabeza y el creador, devuelven la normalidad a la vida. Ọ̀rúnmìlà da hijos a la mujer. Ògún protege los viajes. Los ancestros sostienen la prosperidad. Èṣù recibe las ofrendas de protección."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Clavos, cocos grandes, babosas, cadena, telas, piedras duras, ẹ̀kọ."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 4.1 (yorùbá): Atẹlẹwó-abinutelu / li o difá fún Itẹrẹ / Wọ̀n ni: / \"Ero ti'oni orí li oun mi a maa pa\" / Nitorinaa ki ó rú: / iṣó, òbúkọ méta / ati akuko-adiyẹ mẹta. / Itẹrẹ gbó ó rú. / Wọ̀n ṣe ewé Ifá fún un kio maa muu.", "Verso 4.2 (yorùbá): Ọpa-aro abidijẹgẹlẹgẹ: / lo difá fún'wọn lode lfẹ, / wọ̀n ni bi ikú ti npa wọn nibẹ yi. / Ki wọ̀n rú: / ewọn kan ati agbo kan. / Wọ̀n gbọ̀ wọ̀n rú. / Babaláwo ni: / \"Okanṣoṣo ẹwọn kiikẹ, / bẹẹ ni ọwọ̀ ikú ko ka wọn mọ\". / \" Iṣó: clavo de metal. El significado más ancestral de Iṣó es: uña, pesuña, garra. / Para elaborar la medicina de este Odù valorar el uso de garras, que también / tienen la función mágica de \"fijar\" o \"agarrar\".", "Verso 4.3 (yorùbá): Odidi-afiditi: / li o difá f'Odidimadẹ. / Wọ̀n ni ki ó rú: / agbon olodu móji. / lgbin méjl / ati pgbörindilógün owó / Ô gbọ̀ ó rú. / Babalâwo ni: Ifá wipe: / \"Ọmọ rọ̀ ko nii sọrọ loju rẹ̀.\"", "Verso 4.4 (yorùbá): Emi eni-òdí, / Iwọ èni-òdí, / ẹ̀ni-òdí Méjì: / li o dífá f'Òdi nigba otẹ. / Wọ̀n ni: \"Qwọ̀ Òdí a Kalu\" / Nitorinaa ki ó rú: / Qja Idimo Méjì / Ó gbọ̀ ó rú.", "REZO: ODI MEYI ASHAMA ARUMA KODIMA IKU, KODIMA SHUKURU KURU KIELE BITI BITI KOGOBALE NI ABITI ADIFAFUN AYO OMO OÑI YEGAN AIKORDIE LEBO.", "REZO: ACHAMA AD IMA ICA CODINA A NO CODINA CHACURU CUNU ONI QUERAN LLOMA COMAMA LLORIMA ACHERAN LIME MA MA LOMIMA ABITI BITI COTOBALE BITI ADIFANFUN ALLEOMO ONI LLEGUN.", "REZO: OLERE OR IRE UN ARA ONILESE ACHEO HOLA OTABA OFUALLO ACIFA FA LA OLLE ODIFE TALDO LLEGUA DOGUE LOS ILE AIKORDIE MEYI AKUKO MEYI EKU EYA EPO OMI OWO.", "REZO: AGUDE ADAFA ELEGUINE A COBEHE UN RIRE A CODIE AGUN UN DE EKU EYA OWO ABATEROBI.", "REZO: A CHAMU ADIMA DIMA CODINA CHURUCU CURU QUE ELEN ABATI BITI COTABALE NI BITI ADIFAFUN ALLEOMO ONELLIGUN.", "REZO: OLDERE ARUMA ORUPA ONI ASECO ONIOCHA CHETIN POLAN GUORI PERO ERINLAN CHACANA ARUMA A DIMA DIMA ICU CODINA ARO CODIMA OCHACURA QUELE ONI QUE ERAN COLLIMAN COMAMA LLOMIMA CHEREN ALLIMA MAMALLO MAMALLO OMIMA ABATI ABITI COTO BALE BOTI ADIFAFUN ALLEOMO ONI LLEGAN.", "SUYERE: ODI MODI IYE. ODI MODI IRE. MAMA YE KIO. MAMA YE KIO. OSOBO MONDABALE MONDABALE ASHIRI BABA. MONDABALE MONDABALE ASHIRI BABA.", "REZO: ODIMA ODIMA ODO ODIMA DIMAO OKE ODIMADIMA KUKURA BUELE OKO NAKOIMA KOMAYELIME ORUNELESE EWE GUNGUN ODARA OLOFIN ODI MEYI KATA.", "SUYERE: OYAMESE OSUN AREYERA ERIRONA KONINIRON EUROMA KONINIRON ERIRONA KONINIRON.", "REZO: ODERE ORURE OMO ONI ADADONACE OBUTI PONLA GUERE PERE ORUNMILA ACHAMA ARUMA ODINA DIMA IKU DIMA KODIMA", "ARUN KODIMA SHAKURUWELE ENIKE ERAN KODIMA KOYIMA KOMANA YORIMA SHIRA KEYIMA MAMA YORIMA OMENA ABITI BIRI KOTO KOBALE BOTI ADIFAFUN AYE ANOYEGUN.", "REZO: IFA NIRE TELENEYI IKU OPERE KORU EYELE MEYI EGBAN MELLO EWA ORUN ARAE TODARA OTI BATA ADIFAFUN PAJOGUE GO, GBOGBO EYUTALE WOLO WERE MEYO TOWON KUNRO OBA BEME AJOGUN GB BOGBO SAWE RODE OBINI LODA MEYI EBETA AJOYA DARA FUN SHUGBON KORU AGBA ORUGBO TALOBA KARI SOMA EGBI MEWO WON BAYO OBA YORU NA OYA BEMI BATO ORIN AWO TOBOSI LEMU EMENIKAN AWO EN MI ODAFUN ORUNMILA KAFEREFUN EGGUN.", "SUYERE: AWO ONU MORI OMIE NIKAN NI MORE ARI BORE.", "REZO: KELEY OSHUNNIFORI OMO, KESE NAMBO EGO OJALUONA, INSHE ABIKA, OMO OKAN OKERE, JUN BALE KOKOFA ERUKE MOSARE KOSE FADES, AGADA SOWO AWO ADIFAFUN EYEUMA KENI IYAMA ORUBO OSIN ORUBE TANI ARABA KERESERE OWAIN AWON A MORE OÑI PABABASE KUEYANI NI AWADO AWOME, OJODERUNE OBORO FUN OSINUN EWAYI NI WIN SOMBE BABA OBONI LORDAFUN.", "SUYERE: INSHE AKUO KEKORI TALAUSME LOSENDIE SEYEKE SEYENKE.", "REZO: AGUDE ADEFA EL EKENI AUN KASHE UNISERE EIYE, ABATALOSI UGUI EYU, OMI, ADIFAFUN ORUNMILA, ADIFAFUN ESHU.", "REZO: ADIFAFUN YEMAYA OROKO OMOLI IKI ORO MODO ONILE ERINLO ATI SHAKUANO LOPA ERINLO SEREANARIN LODAFUN ORUNMILA KAFEREFUN OSHUN, YEMAYA, SHANGO."]}]$q$::jsonb),
(5,'4a7bf283602b6c31e4d1b4a30228713d',$q$[{"titulo": "Idea central", "texto": "Ìrosùn Méjì habla de una persona conocida y respetada, a la que saludan en la calle, pero que pasa por dificultades emocionales y de dinero. Las cosas avanzan despacio y piden más trabajo del normal. Ifá le pide cuidar su cabeza (Orí), honrar a sus ancestros, sobre todo al padre, tener paciencia y recordar que ninguna situación es para siempre. Trae la bendición de los hijos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Siente que su vida o su negocio está estancado y que avanzar le cuesta el doble.", "Hay un cargo, una herencia o un puesto en juego dentro de la familia, y no todos se prepararon igual para recibirlo (relato de Iná, Eyin e Iko).", "Le recomendaron una ofrenda o una precaución y todavía no la ha hecho (Iko fue el único que cumplió).", "Espera un hijo, o le preocupa el futuro de sus hijos y que tengan con qué salir adelante (verso de Ìrosù).", "Le afectan los chismes o las críticas de otros (relato de Apeni).", "Necesita paciencia: le toca esperar su turno sin desesperarse."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Hijos: la mujer que desea embarazarse lo logrará con la ofrenda; el niño puede ser babaláwo.", "Muchos hijos y las bendiciones que andaban rondando sin llegar.", "Regresar al lugar de origen y ahí encontrar la riqueza.", "Conservar por largo tiempo un cargo heredado.", "Protección contra lo que habla la gente."]}, {"titulo": "Ibi y advertencias", "puntos": ["Perder el interés por lo que acaba de empezar o por el trabajo de siempre.", "Negarse a la ofrenda y dejar a los hijos una vida difícil.", "Querer dos coronas a la vez: nadie quita una corona sin derramar sangre.", "Enemigos que hablan para dañar."]}, {"titulo": "Enseñanza principal", "texto": "El que sabe esperar su turno conserva lo que recibe. Iko, la rafia, fue el único de tres hermanos que hizo su ofrenda y fue paciente; por eso la lluvia no lo destruyó y gobernó mucho tiempo. Se pide hacer cada año un ritual para toda la familia y mantener el respeto al padre, vivo o muerto."}, {"titulo": "Relatos reunidos", "puntos": ["Iná, Eyin e Iko. Oliyẹbẹ consultó para tres hermanos: Iná (el fuego), Eyin (el fruto de la palma) e Iko (la rafia). A cada uno le marcó una estera y una tela amarilla, y solo Iko cumplió. Cuando murió el padre, que era jefe, pusieron a Iná en su lugar; vino la lluvia y lo apagó. Pusieron a Eyin y la lluvia también acabó con él. Al final le tocó a Iko: cuando llovía se cubría con su estera y cuando escampaba se la quitaba, y así sobrevivió y conservó el título de su padre por mucho tiempo.", "Ìrosùn y su hijo. Le dijeron a Ìrosùn, que estaba por dar a luz, que su hijo varón tendría una vida difícil y batallaría para conseguir dinero y mantener a los suyos. Para cambiarlo debía ofrecer dos caracoles babosa. Se negó, y por eso los hijos varones de este signo tienen que trabajar mucho y ofrendar para llegar a la abundancia.", "El gallo y su cresta. Al gallo le pidieron su cresta roja y 2,200 cauríes. Por orgullo no quiso dar la cresta, y el adivino respondió que entonces el propio gallo sería la ofrenda. El gallo aceptó: prefirió morir antes que perder su honor.", "La cabeza y la corona. Adeiṣi consultó para Ataparí, la cabeza, cuando iba a recibir su corona del Òrìṣà, y le advirtió que nadie le quitaría esa corona sin derramar sangre y que es imposible llevar dos coronas al mismo tiempo. Por eso los hijos de Ìrosùn Méjì suelen encontrar tropiezos.", "Òní, el que lloraba por hijos. Èjì Ìrosùn consultó para Òní, del clan de Kólójo, que lloraba porque no tenía hijos. Le prometieron muchos hijos y las demás bendiciones que lo rondaban sin llegar, y le pidieron muchos caracoles babosa. Ofreció, tuvo hijos en cantidad y la gente lo llamaba 'padre de Mòjèşín', el que trajo multitud de jóvenes al mundo.", "Ìgbà regresa a Òyó. Ìgbà fue a trabajar como sacerdote a Òyó y luego se fue a vivir a las granjas, donde probó de todo para hacer fortuna sin que nada le resultara. Corrió con sus babaláwos, que le marcaron quimbombó y berenjena en abundancia. Ofreció, y poco después unos paisanos lo encontraron y le dijeron: 'Todos somos de Òyó; el que se va al campo algún día vuelve a casa'. Regresó a Òyó y ahí empezó a tener riqueza.", "Apeni y la boca de la gente. Ifá consultó para Apeni cuando la boca de las personas lo amenazaba con muerte y destrucción. Hizo su ofrenda y quedó protegido. Cantaba: 'Su boca, su boca no puede matar a Apeni'.", "Okansusu Irosu y los niños. Cuando Okansusu Irosu iba a venir del hogar de los ancestros a la tierra, le dijeron que ofrendara para que, cada vez que moliera ñame o hiciera sopa, viera a un niño comérselo. Cumplió y vio a los niños comer todo lo que cocinaba. Cantaba: 'Padre, no me hagas comer solo'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Iko: una estera y una tela amarilla.", "Para los hijos: dos caracoles babosa; para Òní, muchos caracoles.", "Ìgbà: quimbombó y berenjena en abundancia.", "Apeni: cuatro palomas, cuatro gallinas, una botella de aceite de palma, akara, bolas de almidón y dinero, a Orí y a Egúngún.", "Okansusu Irosu: ñame molido, sopa, cosas dulces, una paloma, una gallina, un plato blanco, aceite de palma y dinero, a Orí y a Egúngún.", "Ofrendas ocasionales a Orí y a Osù, el báculo de Ifá; ritual anual para toda la familia.", "Tabú: víbora y trapos rojos."]}, {"titulo": "Relaciones espirituales", "texto": "Orí y Osù, el báculo de Ifá, piden atención frecuente. Egúngún y los ancestros, en especial el padre, reciben ofrendas y respeto. Èṣù pone en la boca del cliente el canto de agradecimiento."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Caracoles babosa, estera, tela amarilla, quimbombó (okra), berenjena, ñame molido, sopa, akara, bolas de almidón, aceite de palma, plato blanco. Iyẹ̀-ìrosùn, el polvo sagrado de Ifá."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 5.1 (yorùbá): Oliyẹbẹ li o dífá fún Iná, / Oliyẹbẹ li o difá fún Ṣyin, / Oliyẹbẹ li o dífá fún Iko. / A niki okookan wọ̀n wa rúbọ: / ẹni (agbafi) ifi ati aṣo ofeefee. / Iko nikan lio gbọ ebọ ti orú. / Nigbati baba wọn kú / (Oloye ni baba wọn) / Wọ̀n fi Iná le'ye / Ojo de o pa a / Wọ̀n fi Eyin le'ye / Ojo de o paa bakanna / Wọ̀n fi Iko le'ye / Nigbati ojo de / Iko fi eni rè bori / Ojo da O ka ẹni rẹ̀ kuro / Iko ko ku.", "Verso 5.2 (yorùbá): Qkakaraka-afowotikú, / Idaṣegbẹrẹgbẹrẹw'akọ: / li o difá fún Irosù, / nigbi Irosu mi la bimo. / Wọ̀n nỉ: / \"ako-omo li o ma bi yi, / nitori ko ni ri owó fi wo qmọ naa\". / \"Sùgbọ̀n bi o ba ni / ki oun (Ìrosù) ri owó, / fi wo ọmọ naa, / ki (Irosù) ó wa rúbo\": / igbin Méjì. / ò kọ, ko rubo.", "Verso 5.3 (yorùbá): Iṣeṣerẹfogbeṣe'yẹ: / li o difá f'Akuko-adiyẹ. / Wọ̀n ni ki o fi fila pupa / tiowa lorí rẹ̀ ṣẹbọ / ati ogbokànlá owó. / Ó kọ ko rú / I oun ko maa fi fila oun ṣẹbo. / Àwon Babaláwo ni: Ifá ni: / \"Pipa ni wọn maa paa\" / Akuko-adiyẹ ni: \"ko burú ṣa\".", "Verso 5.4 (yorùbá): Adeiṣi: / li o dífá f'Ataparí, / Ataparí mi la gba fila lọwọ Oriṣà. / Wọ̀n ni: / \"kosi ẹniti O maa le gbaa lową rẹ / ki ejẹ ko ma yii\" / ati \"pe ko maa ni fila Méjì\". / Nitorinaa Ojú a maa pón / eniti Ìrosùn Méjì ba bi.", "REZO: IROSO MEYI OYOROSO APANTARITA BEBE OYOROKO TO BEBE LOYEKUN. OLOKUN APANTARITA BEBE OYOROSO OYOROSO IROSO OLOKUNO OSHEBOGBO MO IYE TUTU ELEGURE NI MEYI KOKOLO LOSHE YEWI LOWA ORISA SHANGO DUPUE.", "REZO: ADIFAFUN OYU APON MASHASHA ADIFAFUN ARA ADIFAFUN EKO ADIFAFUN OLARA OKO IROSO MEYI KAFEREFUN OLOKUN KAFEREFUN OLOFIN.", "REZO: IROSO MEYI OYOROSO APANTARITA BEBE OYOROKO TO BEBE LOYEKUN. OLOKUN APANTARITA BEBE OYOROSO OYOROSO IROSO OLOKUNO OSHEBOGBO MO IYE TUTU ELEGURE NI MEYI KOKOLO LOSHE YEWI LOWA ORISA SHANGO DUPUE.", "REZO: APANTERILA TERI OBEBE QUINQUIN BABA AWO LASHE INA UNFO CUSIMORO OROMI CUSIMARA A BABA KORINI ANYO LODO ADIFAFUN INA ANYO LODO ADIFAFUN OLOKUN UNROKO TOALE AWO DIDA AWO DIDE KAFEREFUN YEGUA.", "REZO: APANDE AWO ASHA LUO DIDE APOSHE APAN MESARE ESPALO LA ADEA ADAPA ALEKODERE TIMPO OLORUN TALLE TALE TALO BOKAN LEBO IBAKO EYELE MEYI ONI LENO AWO APAN TARI TARIBU LEBEKUN GAN AGUA ANA AGUA LASHE INA UNFOKOMONO ARODIPADO KURI NADA BABA KORI INI UNYAR LOKO INA UNIYAN LODO ODAFUN ELERETONUN ROKO TALE AWO NINDAGUN NIDE KAFEREFUN YEGUA OLOKUN.", "REZO: IBORI SI TOSI ATAMATESI OSINI LASHA EUKU OFORISOLO OUNTO DEFISILE OUNTOYO IFA BEDE MAYI BAMEDE ATA EÑI ABA ABA TUTU LANU ASHEBA ADA OMA OLUN YO YOLO UN BELEWO OTUN IDELFUN BELEWO OSI.", "REZO: IROSO MEYI AKAUANTALOSHA ONDI ABBO QUE NIBE QUE UN GUALLO BAUN LAOSHE OSHE AGUANTALOSHE INLE AFOSHE AKUN AUN ASI KURUKA EPEA ARAÑA.", "REZO: AKUONDE AWO NIDEREA APOSHE AKUAN MESURE KAPOLE LENU ADAD AREKADERE TIMPO CLODAR TELE BA OU LEBO IKOKO EYELE ARO AUN SUN EYA ELENO AWO.", "REZO IYESA: IBORI SI TOSI ATAMATESI OSINI LASHA EUKU OFORISOLO OUNTODEFISILE OUNTOYO IF BEDE MAYI BAMEDE ATA EÑI ABA ASA TUTU LANU ASHEBA ADA OMA OLUN YO YOLO UN BELEWO OTUN IDELFUN BELEWO OSI. REZO: AWO KODERE ADAFUN OLODIRE PIOLORO TALE TELE ENU MUSURU KAFIKAFI KAPELENU. ADA ORO DOLE ALBOKO TALE TALE OBON AIKU OBON OTALA ALA DEBE MOFIERE OWO.", "REZO: ADIFAFUN OYU APON MASHASHA ADIFAFUN ARA ADIFAFUN EKO ADIFAFUN OLARA OKO IROSO MEYI KAFEREFUN OLOKUN KAFEREFUN OLOFIN.", "REZO: ADIFAFUN ORUNMILA, OKUNI ALAGBARA, LODAFUN GBOGBO ORISHA.", "REZO: ADIFAFUN SHANGO, OBAROSUN NILE AWO ODARA, LODAFUN OSHIN.", "REZO: ADIFAFUN OBATALA OBANILE MOWAYEN BELEGUN INLE OKEYABI OMO UNSORO ARAYE OBA ARUGBO SHONSHO UMBOWA ONIKA INLE SOKUN SOKUN LAYE BOGBO ARAYE AWOGBO ORUNMILA UMBOWA INLE OKEYABIANO UNSODE ADAFUN EBOTALONI EBOLASUDAYE TANIJUELEGO LOWA UMBOWA ONIKA KUMAROBO JORO JORO ENI AKASHO BELEGUN OBATALA BABA ABELELE UMBOWANI EBOADA OKEYABIANI INLE TALAKO MOFORIBALE OBATALA AMONA ORE ILUO FUN FUN LODAFUN ORUNLA, LODAFUN OBA ARUGBO.", "REZO: APUAN ALUOSHA ASHAWO APUANI ADIFA IRE SUN ILE OLOFIN."]}]$q$::jsonb),
(6,'61ef593b7ee7118a5faea716a46af4c9',$q$[{"titulo": "Idea central", "texto": "Ọ̀wọ́nrín Méjì pide moderación en todo y pensar con claridad para tener éxito. A quien está hundido en la pobreza le anuncia dos bendiciones juntas, dinero y pareja, si hace la ofrenda correcta. La ofrenda no es solo para alimentar a los Òrìṣà y a los ancestros: también debe dar de comer a mucha gente. Favorece la agricultura y el comercio."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está por tomar una decisión con prisa y debe pensarla bien antes de actuar.", "Vende y se esfuerza, pero no gana (relato de Sièjidé en el mercado).", "Le falta dinero y también pareja, y espera que ambas cosas mejoren.", "Un trabajo ligado a la tierra o al campo puede darle prosperidad (relato de Okewu).", "Va a viajar o teme un lugar hostil, y puede regresar bien si se prepara (relato del gato Ologbo).", "Le ofrecen un cargo o una responsabilidad y debe recordar ayudar a los suyos (relato de Owon).", "Desea tener hijos (relato de Opẹkẹtẹ)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Dinero y pareja al mismo tiempo para quien está en la pobreza.", "Buenas cosechas que mejoran las finanzas.", "Ganancias en el comercio y vencer a los enemigos.", "Viaje seguro y regreso a salvo.", "Muchos hijos.", "Un título o un cargo de responsabilidad en la familia."]}, {"titulo": "Ibi y advertencias", "puntos": ["Comerciar mucho y no ganar.", "Ataques de brujería durante un viaje.", "Enemigos alrededor que quieren frenar su crecimiento."]}, {"titulo": "Enseñanza principal", "texto": "Para tener éxito hay que atender a Orí de vez en cuando, escuchar a los padres, respetar a los mayores y honrar a los ancestros (egúngún). La ofrenda se acepta cuando alimenta también a la gente."}, {"titulo": "Relatos reunidos", "puntos": ["El gato en la ciudad de las brujas. Ifá consultó para Ologbo Ojigolo, el gato, cuando iba a trabajar como adivino a la ciudad de las àjẹ́, las brujas. Le dijeron que volvería a salvo si ofrecía una carnera, dos palomas y medicina de Ifá. Cumplió y le aplicaron la medicina.", "Los 165 animales y la tela negra. A 165 animales que salían de viaje les pidieron una tela negra. Ninguno la ofreció, solo el gato. Al llegar se toparon con las brujas, que se comieron a todos los que no habían ofrendado. El gato iba cubierto con la tela negra y tenía cuatro ojos como ellas, así que lo tomaron por uno de los suyos y lo dejaron. Fue el único que regresó a casa, sano y fortalecido.", "Ọpẹkẹtẹ y sus hijos. Ọpẹkẹtẹ fue a consultar porque no tenía hijos. Le pidieron doscientos alfileres, doscientas agujas, doscientas ratas y doscientos pescados. Ofreció y tuvo muchos hijos.", "Sièjidé, la princesa comerciante. Sièjidé, hija del rey de Òyó, vivía del comercio; vendía y vendía y no le quedaban ganancias. Juntó sus pocos cauríes y fue con Ọ̀rúnmìlà, que le pidió ofrendar. Lo hizo y empezó a ganar. 'Apóyate en mí para que yo me apoye en ti, como la ortiga se apoya en la hierba': así llegó la gente a comprarle a la hija del rey.", "Ìrókò Ògò rodeado de enemigos. Ìrókò Ògò preguntó si podría vencer a los enemigos que lo rodeaban donde vivía. Ofreció, creció por encima de todo el monte y los arbustos del bosque, y dominó a todos sus enemigos.", "Ọ̀wọ̀n y el poder del mar. Ifá consultó para Ọ̀wọ̀n, el follaje, que quería obtener el poder de un jefe del mar, y le pidió ofrendar para recibir fama. Ofreció, se hizo jefe y cantaba: 'Ọ̀wọ̀n baila, Ọ̀wọ̀n canta; ha traído el poder del jefe del mar'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["El gato: una carnera, dos palomas y medicina de Ifá.", "Para el viaje: una tela negra.", "Ọpẹkẹtẹ: doscientos alfileres, doscientas agujas, doscientas ratas y doscientos pescados.", "Para un cargo: seis palomas, seis gallinas, seis ratas, seis bagres, un plato blanco y dinero, a Ọbàtálá y a Èṣù.", "Para viajar protegido: diez ratas grandes, una botella de aceite de palma, un plato blanco y dinero, a Ọbàtálá y a Èṣù; luego hierbas para atraer lo bueno durante el viaje.", "Sacrificios a Ifá y al Elédá (el creador) para una vida larga."]}, {"titulo": "Relaciones espirituales", "texto": "Ọbàtálá y Èṣù reciben las ofrendas de este signo. Las àjẹ́ (brujas) respetan al que ofrenda. Egúngún y los padres deben honrarse."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Limaduras de bronce o latón y plomo molidas con semillas de wẹ́rẹ́njẹ́jẹ́ (Abrus precatorius), frotadas en una pequeña incisión bajo las cejas, como medicina del gato. Tela negra, alfileres, agujas, ratas, pescados, carnera, palomas, plato blanco."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 6.1 (yorùbá): Igi-nlá ni ngba agogo-idẹ l'enú, / Agbigbo-ñlă ni nfo ragajigi l'egan, / Ọpe-ihaha ko'ran iwosi, / I k'pnikoni ma sợ'gba / kẹrẹkẹrẹkerẹ lori oun: / a difá fún Ologbo Ojigolo / nṣawo re ilu àjẹ. / Wọ̀n ni: / A yọ bọ, bi o ba rúbọ: / agùtàn, ẹyẹlé Méjì ati ewé Ifá / Ó gbó ó rú. / Wọ̀n ṣe éwe Ifá fún un gẹgẹbi a ti wi / pe kioloo lẹhin ti o ti rúbọ.", "Verso 6.2 (yorùbá): Gogromaafiyun, / Gooromaafibo: / li o difá fún Arunlojẹ eranko, / nigbi wọn mi losájo. / A niki wọn rú: / aṣo dúdú. / Wọ̀n kọ wọ̀n ko rú. / Ologbo nikansosọ li ó rúbọ ninu wọn. / Nigbi wọ̀n d'ajo ti wọ̀n nre / Awọn Àjé ni wọn ba pade / Awọn omo eranko / ti wọn sọ pe àwọn ko jẹ fi aṣo-dúdú / wọn rúbọ li Ajẹ bẹrẹsiipa jẹ / Wọ̀n ri ologbo lokere / Ó f'aṣo-dúdú bòra bii ti won / Ojú rẹ̀ si jẹ mẹrin bii tiwon / Awọn Àjé ni àwọn ko niipa jẹ / nitoripe ara wọn niiṣẹ / Nigbati ologbo nbowa ilé o nkorin bayi: / Gooromaafiyun, / Gọoromaafibo...", "Verso 6.3 (yorùbá): Oloirẹkoirẹ, / Oloorunkoorun: / Ii o difá fün Ọpaketo, / nlç kan orile omobibi. / Wọ̀n ni ko rú: / Igba Ikotip\", igba abẹrẹ, igba èku ati igba ẹja. / Opekpte gbọ̀ ó rú. / Q rg, gegebi Ifá ti wi.", "REZO: OJUANI MEYI BABA OROGUN NI MOUN ORI YEKO ADIFAFUN AKITIFA, ADIFAFUN ARONI, MAMA FOROSILE AKITIFA, ADIE SINKENA ELEBO.", "REZO: FORORO FORORO SITE AQUITIPA. INFUAGUALICHE GUALEGUE OFI ONA A FACHE ADOS O ELLE AFI ERUNOCHO ARERE AIMBO FIO OFUN CHOMA NIBI SIGUA ELLE FUN OGO ACARERUM MALE EKU ELLAFUNI AGUA ARAGON NI MONI UN A GUON O OROG UA ALOCO ONI BABALAWO ADIFAFUN AQUITIPA AQUITIPA MAMA FIORORO MAMA FIORORO SILE AQUITIPA.", "REZO: OJUANI MEYI IOA FAFACHA NIE HELE QUELE EBE OMO ONA AFACHA DODE ALLE FORUN CHOSERE OIBO FORUN FUGAN ANI EBECUA ELLI AWO IBAOROGUN ENI MONI ALBA LLACA ADIFU A QUITIPA ADIFAFUN CHORINI AQUITIPA FORORO SILE AWO.", "REZO: IKU FABA NICHELEQUE LEBA MOUNA OFAN EHODODO ELLE PEREFUN OBERE IBO FOCUNOCHONA ONI ELEGUA ELLE FUN AGRIO IBA OROGUN NI MONI UN ABACHOCA ADIFAFUN AQUITIPA MAMA FOROSILE AQUITIPA.", "REZO: IFA CORI QUE ODAFUN OJUANI ADAFUN OSHOSI ODAFUN ECHA AGUAN ANCHA COTOCHE LLEONODOC HO ODOCHE ROCO INTIO CUON OCO NIMU OTOLE A OCUNA BO ORIBA RANI OCUANDIE CHUDE ANDALLE CANOLHUB ALA GUOMO ACU ADIE MELLI OLE ECHU GUOLEQUI FUN CACONI CANI CANI OCUN ELALLA CHETITU OPOLOPO OWO ECHU ENI LA ASHE AGUTAN UN BATON CHELITA ILLE OROTAN CALEL OTOLE.", "REZO: MOBORI EKU MOBORI EYA MOBORI COPI COCO TIMBELE AGUN OCONIEOCO LAPACHO CONILE UMPILESE ALLOLLI AWO LASOLLO COSA CO MEYI GRAGANDA LODAFUN GUALEO TIOCHEMO O OMI ORO A LESA OCO ALACAN MOBORI FAPA TA LLECUN POBA.", "REZO: ABA OROGUN MAMOUN LLOCO ADIFAFUN AQUITIPA ADIFAFUN ARONI MAMA FORO SILE AWO FORORO SILE AQUITIPA.", "REZO: EOUN ICUN FA BA NI SILE QUE LEBE OFO EHODO ADIFAFUN AGARARA TICHU ECNO OLODUMARE ONI LENO A OWO UMPABA NICHELE QUE LEBE OMUONA OPUCHODE ELLE RERE FUN CHARER IBO FOCUN ONI BEBE ELEDA ELLEFUN AWO IBI SILE OR PGUN NI MORO UN ABALLACO ADIFAFUN MAMA AQUITIPA MAMA PORO PORO SILE AQUITIPA MAMA FORO SILE AQUITIPA.", "REZO: IBA ORUGUN NIMORI A UN OBA LLAOA ADIFAFUN ARO ANI AQUITIPA MAMA ORO SILE AQUITIPA MAMA A QUITIPA ORUBO META ACODA IBARUTA.", "REZO: BABA OGGUN NIMONI OKO LABAYOKO ADIFAFUN AKITIKUA ARONI MAMA FOROSILE AWO FOROSILE ADUE AKITIKUN OTUFO TOLOSAMADO LOBO.", "REZO: OJUANI MEYI ODODO IGUI SOKUN SOKUN KARE LAWA SODENI LAYE OMO ABITA IGUI IYA LASHE EWE ABITA ODODO IGUGUN OMO LAYE ABITA LAWA KUAWO ADE LAYE IDA ABITA BABA OJUANI MEYI OMO ALASEN OMO ABITA IRE UMBO WUANI ENI SHANGO OZAIN OTOKUN ENI BAGURA AILA SHEKUE OBATALA IGUI IYA LASHE SOKUN SOKUN ISOLE UMBO NI AIYE IFA NI KAFEREFUN ORUNMILA OZAIN NI ABITA.", "REZO: BABA OJUANI MEYI AKUALI SHELI BEBLE OLOGBO KOLE SHELEBO OFI ONA OTA BURUKU BURUKU AFASHE ODDOEYO OFI", "EFUSHE MENYI ARERE OLOGBO AWO NI ORUN OLUWO OZAIN TOKU ABOFI OGU SHOMA BIBI SIWALE EYE FUN AWO KAFEREFUN EKU EKU EYE FUNI AWA ARA OGO MANANI AWO OLUWO OZAIN KORUKE AYOKO AWO BABALAWO ADIFAFUN AKITIFA MAMA FIORORO SILE AKITIFA IRUFARA EBA NI SHELI KELE BIBE OMO UN INSHE FORE AYE EGGUN OYIMBO OJU ARAKONISHE SEKE LABE ONA KOBELEFO OZAIN AWO OLOGBO FESHOKOSILE AYOYI AWO TIMBEBARAKUN OZAIN EGGUN BATUNDE OKONI KOKO LA FE SHOKO INLELEA KOYOOLUEKO MEYI BARADAN LODAFUN AWO LODEO EKOTI SHEMA KUNI EGUNGUN ORUN ALSA OKO ALKAN MOBOTI KUAKUATA YAFUN BOGBO IBA TI EGUNGUN ORUN ALSA OFOGUN OLOGBO NIMBUN YOKO IBA ARAWA OMO TINTUN OBADI MEYI EGUNGUN OZAIN NI MORIUN OBA YAKA ADIFAFUN ARON KOLEBA ADIFAFUN EGGUN AGARARA TINSHAWO BABA NI KUELE EKO OLODUMARE ONI LEMU AWO UMPABA NI SHILE KELEBE OMU AKUAN SHODO NILE ORUN UN ABAYOKO ADIFAFUN OZAIN ARONI KUIN ORUGBO AKUKO META ALO ASHE LODAFUN OZAIN Y ORUNMILA.", "REZO: OJUANI PAPEKUN IKU ELEGBA MATISHE IKU EGGUN ALAWANA MALOKUN ARUN IBASHE OLODUMARE OLOFIN MAFREN OFON APA OSI MAYERE EGGUN KAYIBI ORUN LAYE ME ERIN YEYE OLERI EGGUN MASAUN LELE BABA LODE LORUN ORUN LAYE OJUANI LAYE ASHE ORUN EGGUN OMO IKU SHAME LAYE ORUN KUAYERE OMO ODARA EGGUN AMEGO UNDEDE ORUN LELE EGGUN UNIEN OKO OTOKOMA NI OLORUN.", "SUYERE: BABA TERUN NILE EGGUN OBA YEKUN TONI MILE EGGUN OBA YEKUN.", "REZO: OJUANI KEREBE ESHUBA ESHUBA AUN FESHU LEKEDE AMARA GODO AWO AUN ORUGBO KEREKAN NAMELI AWO LASHE EDUN ESHEGONI AGUEMA EGONI IMBELE BABE KOTE KE IGBAN IGBA BARA KOTESU SHANGO KEKERE YIBE KEKERE YERI YERI KEKERE TEYULUN OSHI LOWA INITEN SHENI SHENI KEBAN NIBO IKUN MAGURE AGUEMA OKUA SHELE MOLE BERENE MENO EJUN SHUNDUDI EBE GUYANASHE RERE ADIFAFUN AUN BEE BATUN LESILE EYELIBE KAFEREFUN ORUNMILA.", "REZO: IBA OROGUN NI MARI YAKA AYAKO ADIFAFUN AROBO UMBATI ODI GAMU ADIFAFUN AKITIPA ORI ORUN SAYE FORUN", "SHOSHERE OBORE IBO KORIKO ADIFAFUN EGGUN OPA AYA LODAFUN ELEGBA.", "REZO: ARONI MAMAFOROSILE AWO FOROSILE AKITIFA DIFAFUN ORUNMILA KAFEREFUN OZAIN."]}]$q$::jsonb),
(7,'a6e33d71a0f70868cd93f6bffb555ff6',$q$[{"titulo": "Idea central", "texto": "Ọ̀bàrà Méjì habla de un estado de incertidumbre que paraliza a la persona para decidir y la llena de inseguridad; debe dominarlo con su fuerza interior y su voluntad. Sus hijos tienden a ser impulsivos y víctimas de su propio entusiasmo, y lamentan lo que deciden bajo presión o con los nervios alterados. Ifá le desea riqueza: su Orí está destinado a la prosperidad y su fortuna tiene raíz en Ọ̀ṣun."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Está bajo presión, con incertidumbre o problemas de dinero, y le cuesta decidir con calma; quizá se arrepiente de una reacción impulsiva.", "Su negocio necesita clientes o mejores condiciones.", "Siente oposición a su alrededor; antes de culpar a alguien debe ver la causa real.", "Quiere empezar un proyecto, mudarse o iniciar una relación (relato del árbol Odán).", "Busca prosperidad o hijos (relatos de Awòn y de Ifákáyòdé).", "Necesita apoyo mutuo: una mano lava a la otra (relato de Awùn y Ondero).", "No siguió un consejo y ahora paga las consecuencias (relato de Èji-Ọ̀bàrà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Un Orí próspero y la riqueza.", "Casa y negocio llenos de clientes y amigos si sigue a Ifá y ofrenda a Ọ̀rúnmìlà.", "Muchos hijos, más varones que mujeres.", "Vencer a los enemigos y descubrir quiénes son y qué causa sus problemas.", "Abundancia y buena relación de pareja al empezar algo nuevo."]}, {"titulo": "Ibi y advertencias", "puntos": ["Decisiones impulsivas o tomadas bajo presión.", "Problemas de dinero y enemigos que preparan un ataque sorpresa a su vida o a su casa.", "Enfermedad en el pecho o el abdomen, como la de Èjì Ọ̀bàrà.", "Comer carne de oveja (es tabú)."]}, {"titulo": "Enseñanza principal", "texto": "Una mano lava a la otra: la derecha lava la izquierda y la izquierda la derecha. Para prosperar hay que atender a Orí de vez en cuando, vestirse de blanco y no despreciar lo que Ifá prohíbe."}, {"titulo": "Relatos reunidos", "puntos": ["El árbol awùn lava la cabeza de Ondero. El adivino dijo al árbol awùn, que iba a lavar la cabeza de Ondero, que su Orí sería próspero si ofrecía una carnera, una paloma y cuentas de coral; después debía atar las cuentas a la esponja de su baño. A Ondero le pidieron tela blanca, suficiente para hacerse una ropa, y una paloma, para que una buena persona le lavara la cabeza. Por eso a quien le sale este signo se le aconseja vestir de blanco.", "La carnera de Ifẹ. Le dijeron a Èjì Ọ̀bàrà, que bajaba a Ifẹ, que ofreciera una carnera para no enfermar. No lo hizo. Al llegar lo agasajaron con carne de carnera; comió y le vino una enfermedad que le hizo crecer el pecho hasta el final de sus días. Desde entonces los hijos de este signo tienen el pecho grande y no deben comer carne de oveja.", "Atapẹrẹ y sus hijos. Ifá consultó para Atapẹrẹ, hija de Ọwá Ọlófin, y le pidió manteca de cacao, mucho algodón y una carnera. Ofreció y le aseguraron muchos hijos; después de comer la medicina de Ifá cocinada en una olla, tuvo hijos en gran cantidad.", "Awòn lava su Orí en el río. Ọ̀ṣọ́ló, el sacerdote de Awòn, consultó para él el día que iba al río a lavar su Orí de riqueza, y le dijo que le sería fácil, pero que ofrendara a Ọ̀ṣun. Ofreció, empezó a tener hijos y se los llevó a todos a Ọ̀ṣun para que la muerte no los tocara. Ọ̀ṣun cuidó de él y de sus hijos.", "Ifákáyọ̀dé. Ifá consultó para Ifákáyọ̀dé, hijo de Àgbọnnìrègún, y le pidió ofrendar. Si la persona tiene un hijo varón debe llamarlo Ifákáyọ̀dé, 'Ifá ha traído la alegría'; los devotos de Ifá no morirán jóvenes.", "Odán se establece. Abarere consultó para Odán, que quería establecerse, para que el lugar tuviera sombra. Ofreció, el lugar se llenó de sombra y Odán cantaba: 'Odán nació, Odán sobrevivió, Odán ya se estableció'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Awùn: una carnera, una paloma y cuentas de coral atadas a la esponja de baño.", "Ondero: tela blanca suficiente para una ropa y una paloma.", "Atapẹrẹ: manteca de cacao, mucho algodón y una carnera.", "Para lavar la cabeza: cuatro palomas, cuatro gallinas, aceite de palma, seis ñames blancos, ẹ̀kọ y dinero, a Èṣù.", "Odán: cuatro palomas, cuatro gallinas, aceite de palma, un plato blanco, cuatro ẹ̀kọ y dinero, a Èṣù; tabú: cazar pájaros pequeños.", "Ofrenda a Ọ̀ṣun en el río; ofrenda a Ọ̀rúnmìlà para llenar el negocio."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀ṣun es la raíz de la fortuna de este signo y cuida a los hijos. Ọ̀rúnmìlà llena la casa y el negocio. Èṣù recibe las ofrendas de limpieza de cabeza."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Awùn (Alstonia boonei), cuentas de coral, tela blanca, algodón, manteca de cacao. Medicina para tener hijos: manteca de cacao molida con hojas de biyẹnmẹ, clavo y semillas de iru (Parkia biglobosa), se puede añadir ajo, en sopa para comer. Tabú: carne de oveja. Ante dolores en el pecho o el abdomen, conviene ir al médico."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 7.1 (yorùbá): \"Ọ̀túnwẹsin, / Ösinwẹtún ni qwọ̀ ṣe nmọ\": / li o difá fún igi awùn, / nigbi awùn nlọ wẹ Ori Ondero. / Wọ̀n ni: / \"Orí rẹ a d'orí rere\" / nitorinaa ki ó rú: / àgùtàn, ẹyẹlé ati iyun. / Ó gbó ó rú. / Wọ̀n niki o so iyun na mọ kanrinkan / ti oun yo maa lo fún wiwe ara re.", "Verso 7.2 (yorùbá): \"Ọtúnwẹsin, / Ösinwẹtún ni owọ̀ ṣe nmọ\": / Il o difá fún Ondero, / nigbati igi awùn mbowa wẹ Orí rẹ. / Wọ̀n niki ó rúbọ, / kio baa le ri ẹnirere wa wẹ orí fún un / Ondero ni: kini ebo? / Babaláwo niki ó rú: / agp funfun ati eyẹlé kan. / Ô gbọ̀ ô rú. / Nitorinaa gnikçni ti Ifá yi ba bi / a o so fún un pe ki o maa la aṣo funfun.", "Verso 7.3 (yorùbá): Ojikutukutu / Baragendẹngenden-bi-igbá-elepo: / li o difá f'Èji-Ọ̀bàrà mi bowa, / S'alẹ lfẹ. / Wọ̀n niki ó rú: / àgùtàn ki o ma baa ṣaisan. / Ó gbọ̀ ko rúbọ. / Eji-Ọ̀bàrà lọ s'alẹ Ifẹ, / wọ̀n fi obẹ-ẹran àgùtàn ṣee ni àlejò. / O jẹẹ Ó bẹrẹsi ṣaisan titi o fipo si oke-aya, / lati ojẹ naa wa titi fi di òni-olóni yi. / Àwọn ti Ifá yi ba bi, / wọ̀n a maa po si oke aya.", "Verso 7.4 (yorùbá): Ogigif'ojú-iran-wọ'lẹ: / li o difá fún Atapẹrẹ, / tliṣe ọmọ Qwá-Ọlọ̀fin. / A niki ó rú: / ogi-òrí, ojo-òwú ati àgùtàn kan. / Ô gbọ̀ ó rú. / Wọ̀n ni a bimọ titi inú rẹ a bo / Egbẹta omọ ni oun maa nbi lojoojumo / Içhin ti wọn ti ṣe ewé Ifá fún un / tio si ti jẹẹ. / Beegẹgẹ niki a ṣe fún èniti a dá'fá / fún tio si ti rú ẹbọ ti Ifá yan.", "REZO: OBARA MEYI ONIBARA OLABARA EYEBARA KIKATE AWO KOMAKATO ARAYE KOMAKATE ARA ORUN ADAFUN BOGBE EYEOKO OROFO LORUBO BOGBO TENUYEN KOKORO.", "REZO: OBARA MEYI ONIBARA OLOBARA ELLEBARA QUICATE AWO ADIFAFUN OROPO TONCHE ILEOLALLA ESHU.", "REZO: ONIBARA ALA BARA ELLEBARA QUIOSTE ADIFAGO CANFU OROFO TINOCHE PROLLA ONIBARA ELLE AFIGLU OLLO QUIO ATE. OBARA MEYI IFA ONI LARA ALA BARA ELLE BARA QUICATE AWO FOLOFODE. TINCHE CHECHE LLELE ESHU ORUNLA LORUGO AGUERE AIKORDIE EYELE ELEGBA DE MEDILOGUN EKU EYA EPO. OBASA ONI GEGER ONI GEGER ONI CHACUALUMA LAPEROBE OBUDU LLALLA LA PEOTI.", "REZO: ONIBARA OLABARA ELLEBARA QUICATE ADAFORO TINSHE LOYA EYE ALONA PAFILLO EYE QUICATE ABEBOADIE MEYI LEBO SHILENO OWO.", "REZO: OBARA MEYI IFA ONI LARA EYE ARA QUICATE AWOFALOFODE TINSHE EYEYE ASHA ORUNLA LORUBO EURE AIKORDIE EYELE ELEWEDE MEDILOGUN AWO MEDILOGUN EKU ELLA EPO.", "SUYERE A OZAIN: OZAIN POWO MEYO TOWO DUN DUN OZAIN ATAWO ODE OZAIN MEWO FOWONIRE AWO", "LLAMADA DE EGGUN DE ESTE SIGNO: EGGUN MATARIN MAWA IKU. ORIN MATARIN AEA IKU EGGUN LODO EGGUN AWA OLUBEKAN MAWA BAÑIRE EGGUN MORAKUN AGUN MOYORE EGGUN.", "SUYERE: OROFOFUGO DE ESE EYE ORUNDARE AFE AYE OYA EQUICATA.", "REZO: TOYO TOYO TENU APALAPO OKANA MANI ADAFUNTETE LODAFUN OLOFIN KAFEREFUN ESHU LORDAFUN ORUNLA OBARA NIREGUN IFA LORDAFUN OLOKUN", "REZO: OBARA NI AWO OBARA BARA NI IFA ONI BARA NI REGUN AWO OBASHE ORIBAWE ORUNLA AKUALO IÑA AMAWADE DE ODUDUNA ONI BARA NIREGUN ORUNMALE ISOTA ERI NIBARI TRIBUTE ARIKATO ONI BABALAWO LODAFUN OLOFIN OBARA OBARA NI BARA ABAYE NI IFA ONI BABALAWO ONI BARA NIREGUN OBARA EYI ONI BARA KUNA LE OLOOZAIN OBARA ABA YINIFA ONI BABALAWO ORI OBA AWARE AWO AWO LARA ENI ORO OLOFIN OBARA NIREGUN EGGUN NANIRE AWO IFA KAFEREFUN SHANGO.", "REZO: OBARA MEYI ONI BARA OLOBARA OYEBARA KIKATE AWO ADIFAFUN OROPO TOSHE ILE FAYA ESHU ERIN OKE OMO OBA ARUN ESHINSHIN AWO ODARA IFA KAFEREFUN SHANGO.", "REZO: ONIBARA BABARA EYEBARA KIKATE ADIFAFUN KAFU ARO OFO TINSHE EROYA EYE AFINYU OBE KIKATE."]}]$q$::jsonb),
(8,'5f65b9b288db21c8bed93d22d76fe69f',$q$[{"titulo": "Idea central", "texto": "Ọ̀kànràn Méjì habla de sufrimiento, malas vibraciones, problemas y pleitos judiciales. Sus hijos dan en el clavo cuando hacen y dicen lo correcto en el momento justo; la gente los cree agresivos porque luchan contra todo pronóstico, y a veces se rebelan contra las costumbres y eso les trae problemas. Son propensos a infecciones y deben cuidar su salud. Es momento de ceder, arreglar y cerrar los problemas."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Atraviesa una disputa o contrariedades y necesita negociar o cerrar un asunto pendiente.", "Busca dinero o hijos que no llegan y se pregunta si podrá lograrlo con sus propias manos (relato de Jìngbìnní).", "Va a viajar esperando reconocimiento o recursos (relato de Ṣàkótó en Ọwá).", "Un cambio de casa o de entorno le cambia los planes de regreso (relato de Ilé Ètilè).", "Compite con otro por algo y solo uno se preparó (relato de Olú-igbó y Olú-òdan).", "Tiene un solo hijo y desea otro (relato de Oló).", "Debe elegir entre reaccionar con el enojo o dar un paso pensado."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que se resuelvan la falta de hijos, de dinero y de otras cosas buenas si cree en Ọ̀rúnmìlà.", "Llegar como extranjero y ser hecho rey.", "Un hijo adicional.", "Riqueza que llega a las manos.", "Fama y abundancia en un viaje."]}, {"titulo": "Ibi y advertencias", "puntos": ["Problemas judiciales y malas vibraciones.", "Rebelarse sin medida contra las normas.", "Infecciones y enfermedades que se vuelven crónicas.", "Reducir la ofrenda que pide Ifá."]}, {"titulo": "Enseñanza principal", "texto": "Para vencer a los enemigos y controlar las dificultades, se ofrenda a Ṣàngó y a Èṣù. No se recorta lo que Ifá pide: la ofrenda completa es la que abre la mano a la riqueza."}, {"titulo": "Relatos reunidos", "puntos": ["Ṣakótó, el extranjero empapado. Los babaláwo le dijeron a la gente de Ọwá que ofrendara para que un extranjero fuera nombrado rey, y anunciaron que el próximo rey llegaría empapado por la lluvia. A Ṣakótó, que iba de viaje a Ọwá, le pidieron una paloma, una carnera y tres tortas de frijol, y le dijeron que en el camino no les diera las tortas a Èṣù, sino que se las comiera frente a él. Al primer Èṣù le dijo: 'Si te doy esta torta, ¿detendrás la lluvia hasta que llegue a Ọwá?', y se la comió. Hizo lo mismo con el segundo y con el tercero. El tercer Èṣù, enojado, mandó un aguacero. Ṣakótó llegó a Ọwá completamente mojado, y el pueblo lo hizo su rey.", "Ṣakótó trae la lluvia. Ifá también cuenta que Ṣakótó, camino a Ọwá, sí le dio sus tortas a Èṣù, que se le apareció como mujer, como niño y como caminante. Èṣù le contó que en Ọwá llevaban mucho tiempo sin lluvia y le mostró un sembradío de calabacitas: debía escoger una de las que no hablaban, cortarle la tapa, alzarla sobre su cabeza en la entrada del pueblo y anunciar que traía la lluvia. Lo hizo y empezó a llover. El rey de Ọwá lo mandó llamar y le dio la mitad de todo lo que tenía. Cantaba: 'Ṣakótó es belleza; la buena adivinación es dulce de alabar'.", "El rey del bosque y el rey de la sabana. El rey del bosque y el rey de la sabana fueron a seducir a Ẹwu, esposa de Iná, el fuego. Les pidieron un manojo de escobas, medicina de Ifá, una gallina y una tela negra. El de la sabana se negó; el del bosque cumplió. Un día Ẹwu dejó a Iná y se fue con el rey de la sabana. Iná llegó gritando su nombre y quemó todo lo que tenía el rey de la sabana. Ẹwu corrió con el rey del bosque, e Iná no pudo con él. Así el bosque se quedó con Ẹwu, su vestido de hojas.", "Oló y su único hijo. Oló tenía un solo hijo. Le pidieron una carnera blanca sin manchas, una chiva joven y un chivo joven, y le dijeron que ese hijo se volvería dos. Ofreció y poco después tuvo dos. Desde entonces el signo se llama Ọ̀kànràn Méjì, y a quien le sale tendrá un hijo más.", "Jìngbìnní y la mano llena. Jìngbìnní preguntó si su mano llegaría a tocar la riqueza. Ofreció sin recortar nada, y su mano, que había estado vacía y fría, se llenó de fortuna.", "Èjì Ọ̀kànràn en Ètilè. Le pidieron a Èjì Ọ̀kànràn ofrendar para volver pronto a casa de su viaje a Ètilè. Allá le fue tan bien y comió tan bien que ya no quiso regresar."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ṣakótó: una paloma, una carnera y tres tortas de frijol (àkàrà); cuatro palomas, cuatro aves, aceite de palma, un plato blanco, cuatro ẹ̀kọ y dinero, a Ògún y a Èṣù.", "El rey del bosque: un manojo de escobas, medicina de Ifá, una gallina y una tela negra.", "Oló: una carnera blanca sin manchas, una chiva joven y un chivo joven.", "Para ver claro: dos palomas, tres aves, aceite de palma, màrìwò, un plato blanco y dinero, a Ògún y a Èṣù.", "Ofrendas a Ṣàngó y a Èṣù para vencer a los enemigos."]}, {"titulo": "Relaciones espirituales", "texto": "Ṣàngó y Èṣù vencen a los enemigos de este signo. Ògún recibe las ofrendas de viaje. Iná, el fuego, persigue a quien se lleva a su esposa."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Tortas de frijol, escobas, tela negra, hojas de rinrin (Peperomia pellucida) machacadas en agua, màrìwò, calabacitas. Si hay infecciones repetidas, conviene la atención médica."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 8.1 (yorùbá): Qṣunṣun-igbó-yi-koṣ'oje, / Oburokoṣ'ẹjẹ: / li o difá fún wọn l'aláde Qwá. / A niki wọ̀n rúbọ, / ki wọ̀n le ri àlejò wa le'ye. / Ohunkohun ti Babaláwo ba fẹ ni ebo. / Wọ̀n gbọ̀ wọ̀n rú.", "Verso 8.2 (yorùbá): Oṣunṣun-igbó-yi-koṣ'oje, / Oburokoṣ'ẹjẹ: / Il o difá fún Ṣàkótó / nigbi oun mi lo silu Qwá. / Wọ̀n niki ó rú / Ẹyẹlé, aṣọ-ala, àgùtàn / atl akara mẹta / Ô gbó ó rú.", "Verso 8.3 (yorùbá): Mo daa pẹrẹ o ṣẹ pẹrẹ: / li o dífá f'Olú-igbó. / Mo daa perẹ o ṣẹ pẹrẹ: / li o dífá f'Olú-odan, / nigbi wọn mi lọ gba Ewu tiiṣe Obirin Iná. / A niki wọn rú: / Iṣu-owo ati ewé Ifá, / abo-adiyẹ pẹlu aṣo dúdú. / Olú-ọ̀dàn kọ ko rú, / ó ni Loju Esusu oni'gba ofon, / loju Wariwa / oni'gba ida, loju lyọrẹ oni'gba itẹrẹ? / Olú-igbó nikinṣoṣo li o rúbo", "Verso 8.4 (yorùbá): u umo ro lp okangogo. / auilân kon ti ko ni dúdú rara, ti o jẹ fúnfün, / 1ewure / lan obükọ. / \"Omo rọ̀ kangogo yi a di mój\". / G ghọ̀ b rü. / Hẹ̀ ptợ raa đi Méjì / trọ DiĐ đi móii ni a ti npe. / Bẩu yt nE Okanrormeji / Apiva Ha yt nиpe / Hà naâ fun pmọ rọ̀ yoo di móji\".", "REZO: OKANA MEYI OÑI KANE OKANA NI OKUTE OKAPA MEYI NI ESHU BI EBOADA ESHU BI ADIE PAKIKO, ADIE ONADERE OKANA MEYI.", "REZO (DONDE BAJO OLOFIN): SE TOCA EL PECHO Y SE DICE: OLOFINA. SE TOCA EL SUELO Y SE DICE: NOFIN KABE MOFIN KABA GODO GODO DA IFA MOFIN KABA GODO IBAE ALAFI KISIEKO BEKE LORIE OÑA KAN ORI MI AFARE MAKO OWANI MOYUBA ABE IBA MI OMATUN OMO ASE ABA MISHE FUN NI OMO OMI NI MI.", "REZO (DILOGUN IYESA): OKANA SODE AYA LODE ARO GULE GUYE.", "REZO: OKANA MEYI OÑI KANE OKANA NI OKUTE OKAPA MEYI NI ESHU BI EBOADA ESHU BI ADIE PAKIKO, ADIE ONADERE OKANA MEYI.", "REZO: OKANA IRE IFA OKANA IRE AWO. OKANA IRE SHANGO. OKANA IRE ESHU BI OKAN NI OÑI KANA UNBATI OSODDE BOTALOKUN UNLO.", "REZO: OKANA MEYI SHAKUTE MAYAGUA GUARA AYETA AKUSE LODINE A SHULU ADA OSHURE ANI LADA BADUDU ONIFUNFAN ABAÑERE BEÑISO BARA TETICARUN.", "REZO: SHAKUTA MAYAWALA OLIAPA AWO AKIKO IRE DODI ASHUBI OIDA ASHURE LODAFUN AKUKO UMBATI LOSORDE OLUO IKUEYI DE OLOWA AKARA META LEBO AIKORDIE MEYI ONILEMO OWO.", "REZO: OKANA MEYI SHAKUTE MAYAWALA OYO PAKARO AWO DODI ENI ASHUMBI ADA SHURE ODUDUWA ONI FUN FUN OLA NIREBARA PETAN KARULO.", "REZO: SHACUTE MAYAWALA EYO PAKICO AWODA SHURE AWO KIKO DODI OSU ASHUBIDA SHURE ONI DUDU BABADU INI FUN FUN OU FUNFUN ALAÑIRI BARALAQUETU CARUNLO.", "REZO: SHACUTE MAYAWALA AYAPA KIO O AWO AKIKO DORI ENI ACHURI EBALESHELE ONIARAWO ORUBE AIKORDIE OSINCHE AWADO UNA RAJA DE LEÑA.", "REZO: SHAKUTE MAYAWALA EYO KUA KIO O AWO AWO AKIKO DODI ACHIBI ADA ACHUREONI ARA AWO.", "REZO: OKANA MEYI ESHAKUMAWALA OYO, AKIKO AREALERO DA ACHUBE ODA ADUIBO EBO AKUKO EKU EYA EPO AWADO OWO LA META.", "REZO: OLUFIRAN UMBOWAIYE AKUKO KIE OWUNKO KIO UMBOSA DENI- FAILE AFEKE AWO OLUFINA GODO GODO BAO KABI YESI OKANLE LOGURON OTA LEBO AKUKO LEBO OWUNKO EYELE OKAN APO LEBO OKAN GURO LEBO LODAFUN APA KAFEREFUN OLORUN", "SUYERE: OLOFIN MOFIN KARE OLOFINA MOFIKARE OKANA MEYI EDA IFA MEFIN KARE KAWO KABIYESILE.", "REZO: BABA OKANA MEYI ADA ASHUREO ELEGBA AWO AKUKO ADIE PAKUKO SHUKUTU MAYAKUALA ADIE ONADORE OKANA IRE BELELE OYOURO INLE MOGBA OKANA IRE ELEGBA SHEPE ELEGBA ISOKUN OSODE OLORE BO ASHE ELEGBA AWO AKUKO IBA FUNFUN LODAFUN ELEGBA IFA NI KAFEREFUN ORUNMILA."]}]$q$::jsonb),
(9,'295fc3c74740450eb32435e1f2924aa3',$q$[{"titulo": "Idea central", "texto": "Ògúndá Méjì advierte sobre peleas, disputas y una hostilidad cercana: la persona debe vigilar a su alrededor, cuidarse de traidores y amistades falsas, y no confiar sus secretos a quien no lo merece. Si enfrenta problemas de dinero y enemigos, debe ofrendar a Ògún y luego a su Orí para tener éxito. Está cargando demasiado trabajo y los problemas de otros. Es el signo de Ògún: sus hijos son fuertes, creativos, abren puertas para los demás y tienen muchos hijos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Carga demasiado trabajo y también los problemas de otros; debe ver qué le toca a él.", "Hay tensiones o desconfianza; conviene guardar confidencias y ver los hechos antes de acusar.", "Trabaja, pero no logra conservar lo que gana (relato del tigre).", "Necesita abrir camino en el trabajo, para sí y para otros (relato de Ògún y el machete).", "Espera una mejoría que parece cerca pero no termina de llegar (relato de Idena-Magbon).", "Pregunta por hijos o por el crecimiento de la familia (verso de Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Abrir caminos y conseguir trabajo y bendiciones para otros.", "Muchos hijos.", "Dinero, pareja, casa o un título nuevos con la ofrenda.", "Llegar a viejo, con el pelo blanco como la tiza.", "Vencer a los enemigos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Traiciones y amistades mentirosas.", "Confiar secretos a quien no debe.", "Cargar los problemas de todos.", "Enfermedad o muerte repentina si no ofrenda."]}, {"titulo": "Enseñanza principal", "texto": "El que reparte con justicia evita la pelea: Ògún partió el pescado en dos para que los hombres no se pelearan, y por eso abrió caminos y recibió riquezas. Un solo eslabón de la cadena nunca se rompe."}, {"titulo": "Relatos reunidos", "puntos": ["Ògún parte el pescado. Ifá le pidió a Ògún un machete, un gallo y ñame asado, y le dijo que el machete sería la llave de su éxito y que siempre lo llevara consigo. Comió el ñame asado y, cuando tuvo sed, fue a beber al río. Ahí vio a dos hombres peleando por un pescado que habían atrapado. Les pidió paciencia y que lo compartieran, pero ninguno cedió: uno decía que venía del este y el otro del oeste. Ògún sacó su machete y partió el pescado en dos. El primero le agradeció y le pidió que abriera un camino desde ahí hasta su pueblo, prometiendo enriquecerlo; el segundo le pidió lo mismo. Ògún aceptó. Desde entonces lo llaman 'el que partió el pescado en dos para que los hombres no pelearan'.", "Ògún, enviado a abrir el mundo. Ọlọ́fin Àjàlọ́run iba a enviar a su hijo Ògún a abrir el camino de la vida en el mundo. El adivino dijo que encontraría mucha oposición y no podría terminar solo el trabajo, y que ofreciera un carnero y un eslabón de cadena para tener salud y no morir de repente. Lo hizo. 'Un solo eslabón nunca se quiebra.'", "Ògún, el que arregla la vida de los demás. Le dijeron a Ògún que si ofrendaba nunca moriría, y que todos lo llamarían para que les arreglara la vida y les abriera el camino, aunque ninguno se detendría a ver sus propios problemas. Ofreció chivas y jícaras con tapa, que se pusieron en las cuatro esquinas del mundo.", "Los hijos de Ọ̀rúnmìlà. Le dijeron a Ọ̀rúnmìlà que su esposa le daría tantos hijos que no llegaría a conocerlos a todos. Ofreció una gallina de guinea y 2,000 cauríes. Alarẹ es el nombre del primogénito de Ọ̀rúnmìlà, y a los hijos de este signo se les llama 'hijos de Alarẹ'.", "Lo nuevo que llega fresco. 'Jala suavecito; está muy fresco. ¿Como qué? Como el dinero nuevo que vamos a tener.' Así sigue el verso con la esposa nueva, el hijo nuevo, la casa nueva y el título nuevo, cada uno con su ofrenda. 'El pẹrẹgún nunca usa la ropa del año pasado': cada año le crece corteza nueva. 'Mi cabeza se pondrá blanca como la tiza de Benin; vengan todos a alegrarse por mi cabeza.'", "Ọ̀rúnmìlà ante sus enemigos. 'Al azadón se le golpea plano, al machete de un modo y a la campana de bronce dando vueltas; si se juntan, se vuelven uno solo.' Ọ̀rúnmìlà iba a enfrentar a sus enemigos y le dijeron que los vencería si ofrecía tres gallos, 6,600 cauríes y una bolsa de tela ẹtù. Las bocas de los que usan iru y de los que usan sal quedarían cerradas.", "Ẹ̀là, el niño del elefante. Un día los tres cazadores de Ọlọ́fin hirieron a un elefante que no murió; llegó hasta la plaza del palacio y apoyó la trompa en la pared. Llamaron a los adivinos, abrieron al elefante y en sus entrañas hallaron un bulto envuelto en tela blanca; dentro había una jícara tapada y en ella un recién nacido con barba y cabello blanco, con ocho nueces de palma en cada puño. Ọlọ́fin mandó llamar a Ọ̀rúnmìlà, que cantó: '¿Cómo llamamos al recién nacido? Es Ẹ̀là, hijo de Origi'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ògún: un machete, un gallo y ñame asado; andar siempre con el machete.", "Ògún: un carnero y un eslabón de cadena.", "Ọ̀rúnmìlà: una gallina de guinea y 2,000 cauríes.", "Para dinero: dos palomas; para pareja: dos gallinas; para hijos: tres gallos; para casa: una chiva; para un título: una carnera, tela blanca y una jícara de ẹfun; cada uno con su cantidad de cauríes.", "Contra enemigos: tres gallos, 6,600 cauríes y una bolsa de tela ẹtù.", "Ofrenda a Ògún y luego a Orí; para conservar el fruto del trabajo: cuatro palomas, cuatro aves, un pedazo de cuero, aceite de palma, un plato blanco y dinero, a Ògún y a Ifá."]}, {"titulo": "Relaciones espirituales", "texto": "Ògún, dios del hierro y de la guerra, es el dueño de este signo. Orí recibe ofrenda después de Ògún. Ẹ̀là es hijo de Ọ̀rúnmìlà según este relato."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Machete, ñame asado, eslabón de cadena, ẹfun (tiza), tela blanca, pẹrẹgún (Dracaena), planta ṣẹ̀ṣẹ̀ki de muchas semillas. Para recibir buena fortuna: dos campanas de metal marcadas con iyẹ̀-ìrosùn, una para el babaláwo y otra para la persona."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 9.1 (yorùbá): Alagbára ni nsokun Ade: / li o difá fOgún. / A niki ó rú: / agbada, akuko-adiyẹ ati ẹsun-iṣu. / Ifá ni: / \"Agàdá yẹn ni Ògún maa fiṣe / Iṣẹ Ọrọ, ki o maa muu l'owọ̀ Kaakiri\". / A ni ki o jẹ ẹsun-iṣu naa, o jẹẹ. / Orungbẹ si ngbẹẹ, / o lọ si odó lọ mu omi. / Bi o ti mu omi tan, / O ri àwọn Méjì / Kan ti nja nitori ẹja kan ti wọ̀n pa. / aa тu suuru / in нi H6 / ni aun ti wa / 1uwa / 19 Tan un / I WOn % / a Hi qwọ rọ da pja / woh / gwo re. / à fiagádà qwọ rọ̀ / ld oun, o ni oun a / A MHR / Quoro, o ni pwo re yoo / te opolopo in kan ti ojú ko niifi / Bọ̀n gn kio too đe ọ̀dọ̀ oun. / Enikeji tun dupp, o bẹç ki o maṣai / ta qná wa de ilü oun bakanna / Ôgùn ni oun gbọ̀ / Niẹ̀ giọ ti Ôgún tí da gja si Méjì / Tun gwọn máji ti nja li a tin pee / 1t Ogündamejl:", "Verso 9.2 (yorùbá): Agogo-owó-koṣeif'apokosi: / li o dífá f'Ọlófin, / nigbi Ọlọ̀fin Àjàlọ̀run / mi a ran ọmọ rẹ̀ ti njẹ / Ögún wa s'ode Ayé / lati wa la ònà Iwa. / Wọ̀n ni: / Ogún konilaa tan ki ayé toṣe orí kogo / Sùgbọ̀n ki ó rúbọ / Nitori aralíle ati àitètèkú3o / Agbo kan ati ẹwọn koniko kan / Ó gbọ̀ ó rú. / Wọ̀n ni: \"Ewọn kan kiikẹ\".", "Verso 9.3 (yorùbá): as'Òfún-kilo: / rabý, a ko nigbọ ikú rè laelae. / a mlaman bpe pe: / a wọn tan iwa wọn pe\", / Leni kan / Hye B / tra ro\" / Hofin, sware morin ati igbá-ademu mérin ni ebọ. / We / y пaд. / Qiofin lọ rì qbọ na si igun mèrin ayé.", "Verso 9.4 (yorùbá): Ìdí-p'akun-bere: / fi o difá f'Ọ̀rúnmìlà. / Wọ̀n nì: / \"Obirin to ni yi a bimo titi / Ọ̀rúnmìlà koniimo iye qmọ rẹ̀\". / Nitorinaa ki ó rú: / oyẹ-awo ati ẹgbẹwa owó / Ọ̀rúnmìlà gbọ̀ ó rú / Alarẹ oruko ti ape Akobi Ọ̀rúnmìlà. / Ayani a ngbọ \"omọ Alarẹ\" (Olúwa rẹ, Olódùmarè). / Eniti a dá Ifá yi fún, / Obirin (aya) rẹ̀ a (bimọ pupọ) rẹ. / tún iwa wọn ṣe: (tún ... ṣe) arregiar o corregir el carácter de ellos.", "REZO: OGUNDA MEYI OGUNDA SIRO OWAYOLOKUN ASHANLA BIRINIWA OBATALA OBATAISA JEKUA OBA IGBO ODOBALENI OGGUN ORIRE YOLORUN. OCHOSI OGUNDA MEYI EYENI EYE ORARUMA OKUALORUN OBARALAYUNA TIWA ELEGBARA AWALAWA OLOWU SHIWOSI ORUNMILA KAYE WARIO ORUN MAFEREFUN ODUDUWA ORUGBO.", "SUYERE: OROSI BABA KERERE, BABA KERERE, BABA KERERE.", "REZO: OGUNDA EJI ERA TETEYI UNSHE EJA OGGUN KAFEREFUN OBATALA ATI ORUNMILA PIT Y GUIN ELEBBO. OGUNDA EJI TETEYI FARA LERI LOSUO EYO ALANIBAWA ADIFAFUN AYOROKE BI OPA OTORUN BOYE, ADIFAFUN IYAREWA OMONIWA ODUDUWA OKETE KEKE BI OMO ASHO KUENI ADIFAFUN AGBANI. OGUNDA EJI TETE SIRO OBINI ADIFAFUN ALAGUEDE, MAFEREFUN ASHANLA, IBORU, IBOYA, IBOSHESHE.", "REZO: OGUNDA EJI ABELONA FOLOYA IGI LEGAN ADIFAFUN TOLO INSHO OGUNDA TETEYI INLE IGBE AWELI OTOLOYO OTOLOYO FESE FESE MOSHOGUN ODO AWOLI NI EMIKE OKUA EURE MEYI IFA ODARA. OGUNDA EJI IYENI ODODO EKUNDAYO ILEKE OBINI AROKUNAYO.", "REZO: OGUNDA NI AYO OGUNDA BABERI IYA, OGUNDA KOKUN EYENI IYA OBUKUA MORA OMA SHEPE SHERO EKUN EKUE NIYIWE EYE IYA OPUERUN OBONI.", "REZO: OGGUN ORIBIAYE ORUN OGUNDA SIRO OMO WAYOKUN MANA DEDE OWO OMO ORUN MOYAYE WARILOYE ABONI KEFEREFUN BABA SHANGO.", "REZO: AMINGO ADIFAFUN AMELOGUN OMO OLUGBON ESE NOFANO A INI LODO BARABANI FEREFUN NO BATI UNLO SODE IFA OBINI ORISHA YEMAYA OKUTI OBI IYAESHU AKUGBO IGBO OMODE META BELEFUN ADE ALAMBO OMO LA MERIN TONTI MERIN SUTIRO SIRO AWO SUTIRO INLE ADIFAFUN OGGUN BOMALE OZAIN BELE BELE SOKUN LALE AWO ODARA, KEFEREFUN YEMAYA LODAFUN OGGUN.", "REZO: OGUNDA MEYI BABA SIRO SIROYE OWALOYOKUN OSHANLA JEKUA OBAIBO ADIFAFUN OMO BABA INU ORAYELUMA ODUDUWA OMOBONU INLE BABA FUN FUN OSHAYABI OGUNDA OSHANLA ADIFAFUN OLUWO SHIWOSHI IFA NI KEFEREFUN ORUNMILA Y OSHOSI LODAFUN OLOFIN.", "REZO: OGUNDA MEYI IDAWIRI ODO KIPODO IDAWIRI OLOKIPO ILE ADIFAFUNIYI ADIFAFUN ADIAUN UYI TINSHOMO AJALORUN OFO LORUBO KEFEREFUN OLOKUN AKARO.", "REZO: TOQUE DE LA PUERTA DE IGBODUN OGUNDA MEYI. —- OGUNDA MEYI BABA FARAYE OBATALA SHEWERE LOYE OGGUN TETE EJI EBORU, EBOYA, EBOSHESHE.", "REZO: OGUNDA TETEYI FARA LEYI LOSUO EYO ALANIBAWA ADIFAFUN AYAKORE BI OPA OTORUN BOYE, ADIFAFUN AYAREWA OMINIWA ADUDUWA OKETE KETE BI ORUN OMO ASHO KUENI KUENIA ADIFAFUN AGBANI.", "SUYERE: ORISI BABA KERERE, BABA KERERE, BABA KERERE. OGUEGUE OGUEGUE ORISHA ANANO OGUEGUE EWA ORISHA MANIEE. IBORU IBOYA IBOSHESHE ORISHA LANA IBORO IBOYA IBOSHESHE ORISHA LANA.", "OGUNDA TANI OSHA OKA IWONA AYAYA OKE IWOBA AYAYA TANI LOGUN AYAYA OKE IWONA TANO MALOWA", "AYAYA KUELEDE OKE IWONA TANI MALONOA AYAYA KOLENFU", "OROPALO OLOKUN OPA OKUN OLOHIPO ODE OROPALO OLOKUN OPA OKUN OLOHIPO ODE.", "IFA OUNKO ORUMILA LAKA LAKA LABOSI IFA OUNKO ORUMILA LAKA LAKA LABOSI AWO. OSHEMINIE.", "REZO: TETE AYE IYA OGGUN LORUN ARIBUN MOROBON ERU OKO, ERU OZAIN OKO ELEYA EJA OKAN NI OGUNDA NI OBATALA DENI OGGUN ONI OUN OBAYINU OBATALA ONI OUN OTUNSHE NI OGUNDA MEYI LODAFUN OBATALA KAFEREFUN ORUNMILA.", "REZO: AMIDIGO ADIFAFUN AMELEGUN OMO LUGBON ESE MORANO ADEI LODO BARANIREGUN NI BATI UNLO SODE IFA OBINI ORISHA YEMAYA OKUTE OBI IYA ESHU AKOKO IGBO OMODE BELEKUN ADE OLAMBO OMO LA MERIN TONTI MERIN SUTIRO SIRO AWO SUTIRO INLE ADIFAYOKO OGGUN BOMALE OZAIN BELE SOKUN LALE AWO ODARA MAFEREFUN YEMEYA LODAFUN OGGUN.", "REZO: ABENBOLA FOLAYA IGI LEGAN EIYENLA FOBAKE ABOGBO NIWALA FOLAKA IGI LEGAN IGI LEGAN ADIFAFUN TOLO INSWO OGUNDA TETEYI INLE IGBE AWELU OTOLOYO OYOLOYO OTOLO FESE FESE MOSHOGUN ODO AWOLI NI EMIKE FUN MEYI IFA ODARA.", "REZO: OGUNDA NI EYE OGUNDA BELERI IYA AGUEDA KEKUN EYENI IYE ABOKUE NORA OMA SHEPE ABORO ABORO EKUN EKUE NITIWE EYERI EYE IYA KAFEREFUN EBONI.", "REZO: BABA SIRO SIROYE OWALOYOKUN OSHANLA OBATAISA JEKUA OBAIBO ADIFAFU OMO BABA INU ORAYELUWA. ODUDUWA OMOBONU INLE. BABA FUN FUN OSHAYANI OGUNDA OSHANLA ADIFAFUN OLUWO SHIWOSHI. IFA NI KEFEREFUN ORUNMILA Y OSHOSI. LODAFUN OLOFIN.", "REZO: OGUNDA EYI AWAPARI AWA TEMATASHE AUN MOSHODE OLOFIN AGBANI BABALAWO ADIFA SHIGUN SHINLOKO IDI OBA OSUN UMBATI ILE OLOFIN LORUBO ORUNMILA META MOMO OKOYA EISE IRABO BENO OLOFIN EPO ORA ADIFA AGUSE TINSODA AWO NIDE OGUNDA MEYI ORUBO.", "REZO: IDAWIRI ODO KIPODO, IDAWIDI OLOKIPO ILE ADIFAFUN IYI ADIFAFUN UYI TINSHOMO AJALORUN OFO IYI LORUBO AKUKO ADIE MEYI EKU EJA MEYI EBO DILOGUN OWO IYI ROBO APA IROKO ARABA IRA OBARA MOFIJE SOFARERE OLODUMARE MOGUAYE EYO KOYO AYE OKAN AYILOWA OPEWE OPAN OKUN WUDA ORASI ERA ODA OFERESE IYE EJA SOPUN LODO KAFEREFUN OLOKUN KAFEREFUN OLOKUN AKARO.", "SUYERE: AROPALO OLOKUN OPA OKUN OLOHIPO ODE.", "REZO: ADIFAFUN OMOMIRIN ERU DOTA BERE ARAIKA LORDAFUN ESHU ARIBO ABANI ADE AIYEMI AGUTAN ODO ODONI ORUNMILA UMBO ORUN ATIENI IFE UMBO BASSYE GBOGBO ORISHA ADESHE IBORU IBOYA IBOSHISHE."]}]$q$::jsonb),
(10,'ad375544d517a2a3bcbdafefbbe0b45f',$q$[{"titulo": "Idea central", "texto": "Ọ̀sá Méjì habla de falta de valor y de confianza para enfrentar un conflicto, que se expresa huyendo o esquivando cualquier oposición. Sus hijos viajan mucho, por trabajo o por gusto, y son buenos administrando negocios ajenos; como se asustan fácil, rara vez arriesgan. Les cuesta concentrarse y se distraen con facilidad. Pide ayuda espiritual contra pesadillas y brujas que interfieren en el sueño, y ofrenda a Ṣàngó para vencer a los enemigos que planean hacerle daño."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le llega un cambio repentino en el trabajo o en una relación y lo rechaza por miedo a perder estabilidad.", "Enfrenta oposición o una pelea y necesita prevalecer (relato de Òlúkòso y Ṣàngó).", "Busca prosperidad material (relato de Òwú, hijo de Ògòdò).", "Va a viajar o trabajar con desconocidos que podrían querer perjudicarlo (relato de Ọ̀rúnmìlà).", "Un susto o un imprevisto puede frenar su proyecto (relato de los dos Òsá).", "Busca pareja, hijos o reconocimiento (relatos del matrimonio de Ọ̀rúnmìlà y de Ejipabileseigi).", "Está cansado o descuida una necesidad propia (relato de Ajá)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ganar fuerza hasta vencer a los enemigos con Ṣàngó.", "Encontrar pareja y tener muchos hijos.", "Gran riqueza si se casa con una sola mujer.", "Que los enemigos cambien de corazón.", "Fama por hacer el bien."]}, {"titulo": "Ibi y advertencias", "puntos": ["Huir de los problemas en lugar de enfrentarlos.", "Pesadillas y ataques de brujas.", "Debilidad, cansancio, boca seca y estreñimiento.", "Pelear y que la enfermedad caiga sobre la familia."]}, {"titulo": "Enseñanza principal", "texto": "El que no ofrenda huye: los dos Ọ̀sá corrieron ante el fuego de Ifẹ, y de ahí su nombre. Hay que seguir haciendo el bien aunque algunos no lo agradezcan; el buen trabajo trae la fortuna."}, {"titulo": "Relatos reunidos", "puntos": ["Los dos que huyeron. Kasá consultó para los dos Ọ̀sá que iban a Ifẹ a adivinar, y les dijo que algo podía asustarlos e impedir sus planes; debían ofrecer un carnero y una piedra de rayo. No quisieron. Al llegar a Ifẹ estalló un fuego, una pelea; trataron de combatirlo, no pudieron y salieron corriendo. Desde entonces a los dos que huyeron se les llama Ọ̀sá Méjì.", "La pata solitaria. Ọ̀sá andaba sola y errante por el mundo. Le dijeron que encontraría buena pareja si ofrecía dos palomas, dos caracoles y medicina de Ifá. Ofreció. A quien le sale este signo tendrá muchos hijos.", "Ọ̀rúnmìlà y Olúyemi. Ọ̀rúnmìlà quería casarse con Olúyemi, hija de Ọlọ́fin. Le dijeron que si se casaba solo con ella su riqueza sería muy grande, y le pidieron dos gallinas, dos chivas y 3,200 cauríes. A quien le sale este signo se le aconseja tener una sola esposa.", "El perro y la sed. Al perro le pidieron dos caracoles y medicina de Ifá para bañarse, porque una sed excesiva lo tenía débil y agotado. Se negó: dijo que la saliva de su boca bastaba para calmarle la sed.", "Ṣàngó y las cien balas. Ifá consultó para Olúkòso Làlú, Ṣàngó, el que encuentra cien balas para vencer, y le pidió ofrendar. Ofreció. '¿Con qué venció Àrìrà? Con cien balas.'", "El algodón. Ifá consultó para Òwú, el algodón, hijo de Ògòdò, y le pidió ofrendar. Ofreció, y frente al campesino dio su fruto y se abrió: así se hizo rico.", "Ọ̀rúnmìlà y la ginebra. Ọ̀rúnmìlà iba a viajar lejos con unos compañeros que querían hacerle daño. Ofrendó y les ofreció ginebra. Cuando terminaron de beber se miraron y dijeron: 'El hombre al que queríamos dañar nos dio de beber'. Desistieron, y nunca le hicieron daño.", "El Desdichado azota a sus vecinos. Al que llamaban 'el Desdichado' le dijeron que no azotara a Ìjẹgbẹ y a Ẹjẹgbo. Dijo que sí lo haría, y lo hizo. Al volver a casa encontró a toda su familia enferma en el suelo. Los adivinos le dijeron que sin ofrenda no podría con ellos; ofreció dos palomas, nueve kolas, una gallina y un gallo, y le rezaron: 'Echamos a la muerte del pueblo; echamos a la enfermedad'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Los dos Ọ̀sá: un carnero y una piedra de rayo.", "Para hallar pareja: dos palomas, dos caracoles y medicina de Ifá.", "Ọ̀rúnmìlà: dos gallinas, dos chivas y 3,200 cauríes.", "Contra la sed y la debilidad: dos caracoles y medicina de Ifá para baño.", "Contra los enemigos de viaje: cuatro palomas, cuatro aves, aceite de palma, cuatro bolsas de harina de maíz, un plato blanco, dos botellas de ginebra y dinero, a las Ìyàmi; antes de dar la ginebra a los enemigos, la persona bebe un trago frente a ellos.", "Para fama: cuatro palomas, cuatro aves, kola, orógbó, un plato blanco, aceite de palma y dinero; tabú: comer sopa directo de la olla.", "Contra la enfermedad en la familia: dos palomas, nueve kolas, una gallina y un gallo.", "Ofrenda a Ṣàngó y a las brujas (àjẹ́) para dormir tranquilo."]}, {"titulo": "Relaciones espirituales", "texto": "Ṣàngó (Olúkòso, Àrìrà) da la victoria. Las Ìyàmi o àjẹ́ reciben la ofrenda para no perturbar el sueño. Ọlọ́fin da a su hija a Ọ̀rúnmìlà."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas de biyẹnmẹ cocinadas con huevos, para que coma la mujer que busca pareja. Contra la sed y la debilidad: hojas de tẹ̀tẹ̀rẹ̀gún (Costus afer) machacadas en agua con el líquido de un caracol, para bañarse. Piedra de rayo, algodón, ginebra. Ante debilidad, sed excesiva o estreñimiento persistentes, conviene ir al médico."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 10.1 (yorùbá): Kasá kaja-katetesa: / li o dífá f'Èji-Ọ̀sá, / Eji-Ọ̀sá nsawo lọs'alẹ lfè / Wọ̀n ni: / \"Inkan kan a maa wa dèrùbaa / koni jẹki o duro ṣe iṣẹ awo rẹ̀\", / nitorinaa kio wa rú: / agbo ati ẹdùn-ààrá. / Ó kọ ko rú. / Nigbati wọ̀n de alẹ-Ifẹ, lja de wọ̀n / ja wọ̀n ko le ja, wón sá. / Nje ojọ ti eniméji sá, / kia maa pee ni Osáméji.", "Verso 10.2 (yorùbá): İgbín ko ya palaka ẹsẹ: / li o difá f'Ọ̀sá kan, / nigbi oun nikan rin kiri ayé. / Wọ̀n ni: / \"a pe Méjì, biobarúbo\": / ẹyẹlé Méjì, igbin Méjì ati ewé Ifá. / Ó gbọ̀ ó rú. / Eniti a dá'fá yi fún yio o bimo pupo.", "Verso 10.3 (yorùbá): Pkan-atogun-kose-irode'lẹ: / 1o difa fOrúnmilà, / Hgbi oun mi lọ fẹ Olúyemi, / Họn qmọ Ọlọ̀fin / Wọ̀n nì: / biobani oun nikansoso, glà rẹ̀ a ga\". / Abo-adiẹ Méjì, ewúré Méjì / atl egberindilógún owó li ebọ.", "Verso 10.4 (yorùbá): onvermeyenme / Ннeнa гA / Wọ̀n niki ô rú: / Igbin Méjì ati ewé Há, / kiofi wẹ nitori ohaha, / Ki ara baa le rọọ. / Ajá kọ ko rúbọ. / O ni: / \"ito enú oun ti to lati pa oungbẹ\". / Oliyẹnmẹyenmẹ:", "REZO: OSA MEYI ORUNMILA DIFAYOKO ORDOFUN OLGUEN DIROYUN KODE AKAFARA TOFIKO DIGUON KALE IFA (BURO, BARAYA ADIFAFUN OGUE).", "REZO: BABA BURU BURU BABA FOSHE EFAN ABRAGAN OMO ODE AMI INU ADIE OPACARA ENU ORUN COLLO MASILE ONI ADIFAFUN OQUE NIBA OFERO SOFO LOGUO ONIANA LOGUO ELEBO EYELE MENI ASHO TIMBELARA UCO EPO.", "REZO: BABA BURU BURU BABACOCHE CHOCO EFAN ABA ABRAGAN OMO AMI INU ARDIE OBAPA CACARA ORUN COLLIMA SILE ANIBANA ADIFAFUN OQUE NIBATE OLOFAROSOFA LOGUO ONIBANA.", "REZO: KOKO DE OJU OROKUN O PINONA DE ORI APATA PORURU YEWERE NOJOTI O MAWA IJEGBE ATI EJEGBO NWON NI KI O MAWA NWON ONI ON YIO NAWON OSI NAWON.", "REZO: ADA OSHE ADIFAFUN ORUNMILA, LORDAFUN TALABI OMODE OSHAYAN ASHEGUN AYE UMBO WASIYE ORUNMILA PINADO IYASI MIMO KAFEREFUN OGGUN.", "SUYERE: “IFA ODARA, EMI ODARA MOYUKAYO MAMA WANKEREPO, MODUKAY MANNEREPO”.", "REZO: OSA BERE LERI OSA BERE LERI BAYEKUN IKU EWA NI SHANGO ERAN ABO MAMARA UNYEN EUKU IKU KI ABEREMI WARA LA LELI ABEYI LODA OLU BERU BERUN OLOKUN UNYEN OWUNKO WARA WARA YENI OSA BERE OSA OSA EGUEDE OBI EWE BABA EGGUN, EYA TUTO YEYE YEKUN IKU BABA ORISHA ORUNMILA EYENI LAYE, OSHA UNYEN EYA TUTO DE AGUA WAYE IKU FUMI ABEREMI LAYE, EYA ORUN SHANGO KEREKE LE ABEYE OSA BIOSA, OSA MEYI OSA EYA."]}]$q$::jsonb),
(11,'98f5b656d4e61ef34cd74f9ae9c00003',$q$[{"titulo": "Idea central", "texto": "Ìká Méjì es el Odù de las preocupaciones, las inquietudes y la gente que goza con el dolor ajeno. Pide vivir con moderación, cuidar la cabeza (Orí) para decidir bien y no confiar a ciegas ni en parientes ni en amigos. Quien cumple con Ifá y con Ògún vence la muerte, la enfermedad y la pérdida; es además un buen momento para el embarazo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Junta preocupaciones de dinero, familia o salud y necesita decidir sin prisa.", "Desea un embarazo o hijos (relato de Bara Àgbọnnìrègún y el maíz).", "Teme que la envidia o los celos de otros le quiten una oportunidad.", "Hay un viaje o un trabajo con extranjeros que puede traer abundancia (relato de Erelu del Océano).", "Debe cuidar lo que dice y cómo habla de los demás: la palabra construye o destruye.", "Se confía demasiado en su posición y desoye un aviso (relato de Eyin), o actúa con fuerza sin prepararse (relato de Ògún).", "Hay una disputa de pareja (relato de Ọ̀rúnmìlà)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ser librado de las garras de la muerte, de la enfermedad y de la pérdida.", "Vida larga y firme, como la montaña que no muere.", "Muchos hijos y fecundidad en el mundo.", "Abrirse camino propio, como el fuego que avanza quemando lo que tiene delante.", "Protección de la esposa y del hogar frente a quienes quieren quitarlos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Problemas grandes que aparecen de golpe, sin aviso.", "Enemigos que por envidia bloquean las buenas oportunidades.", "Hijos poco confiables y apuros de dinero.", "Dejarse llevar a un lugar con promesas de grandeza y caer en una trampa.", "Despreciar la ofrenda por creerse ya coronado."]}, {"titulo": "Enseñanza principal", "texto": "Cada quien recoge lo que siembra. La corona que uno lleva encima no lo exime de ofrendar: el que se cree demasiado grande para pedir consejo es el primero en caer en el foso. Quien da a tiempo recibe las armas para defenderse, como el gato recibió sus garras."}, {"titulo": "Relatos reunidos", "puntos": ["Oníkàámògún y el pangolín. Oníkàámògún, hijo del pueblo que aparta la mano de la muerte, fue a consultar porque la enfermedad y la muerte rondaban su casa. Le pidieron ofrendar y le advirtieron que debía añadir un pangolín (àkàká) a la ofrenda. Lo hizo tal como le dijeron. Desde entonces no volvió a enfermar ni a ver la muerte de cerca. Por eso se canta que el pangolín, que se enrolla dentro de sus escamas, hace rodar lejos todas las desgracias.", "Òràmolè, la montaña que no muere. Òràmolè, la montaña, preguntó cómo podría pasar por la tierra sin morir. Le pidieron ofrendar completo, sin dejar nada a medias, y lo hizo. Pasaron veinte años y la montaña seguía allí; pasaron treinta y seguía en pie, firme y pesada en su sitio. Por eso quien recibe este Odù pide que lo encuentren fuerte, vivo y sin muerte, como la montaña.", "Eyin y la corona. Eyin fue advertido de que un gran problema iba a caerle de repente, y que debía ofrecer un gallo y lo que el sacerdote escogiera. Respondió que con la corona tan hermosa que tenía sobre la cabeza no necesitaba ir a ningún adivino. No ofreció, y el problema llegó de golpe, cargado de angustia.", "Bara Àgbọ̀nnìrègún y las dos mazorcas. Ọ̀rúnmìlà iba a Ifẹ̀ a buscar la bendición de los partos. Le mandaron sembrar dos granos de maíz y ofrecer dos gallinas. Sembró, cuidó la siembra y, cuando el maíz dio espigas, cortó dos mazorcas para agasajar su cabeza. Entonces se dijo que quien corta dos mazorcas para su Orí se llama Ìká Méjì, y que tendrá muchos hijos en el mundo.", "La esposa de Ọ̀rúnmìlà y los vientos secos. Ọ̀pẹ̀, la esposa de Ọ̀rúnmìlà, estaba a punto de ser seducida. Ọyẹ, el viento seco y polvoriento, y Ọwọrẹ, la temporada más seca del año, querían treparse a ella y arrebatársela. A Ọ̀rúnmìlà le pidieron ofrecer dos cabezas de cobra y una soga de las que se usan para subir a las palmas. Cumplió, y ni Ọyẹ ni Ọwọrẹ pudieron trepar a la palma: se quedaron sin fuerza ante ella.", "Ògún y el ñame asado. Ògún salía a atacar la ciudad de sus enemigos. Le pidieron ofrecer una calabaza de vino de palma, un ñame asado y aceite de palma, y no quiso. Peleó y ganó la batalla, pero de regreso uno de sus hombres le dio un pedazo de ñame asado; se le pegó en la garganta, no pudo tragarlo y se quedó sin habla. Desde ese día, cuando le hablan, Ògún responde con la cabeza y con las manos.", "La tortuga, el elefante y el foso de Ilabẹsan. La gente de Ilabẹsan necesitaba un elefante para un sacrificio, y la tortuga se ofreció a traerlo. Fue a buscarlo y le dijo que lo querían hacer rey. El elefante, halagado, la siguió. Antes de llegar habían cavado un foso grande y lo habían tapado con hojas y tierra. La tortuga entró delante, ligera; el elefante pisó detrás, la tierra cedió y cayó al fondo. Allí lo mataron para la ofrenda. Quien se deja llevar por promesas de grandeza sin consultar termina en el pozo.", "El gato y las seis agujas. El gato no lograba atrapar lo que perseguía: todo se le escapaba. Le pidieron ofrecer seis agujas. Las ofreció, y las agujas se le volvieron garras. Desde entonces lo que el gato agarra ya no se le escapa.", "El fuego que abre su camino. El fuego preguntó cómo abrirse paso por el monte. Le pidieron tres gallos y aceite de palma. Ofreció, y desde entonces el fuego avanza consumiendo lo que tiene delante y se hace el camino solo.", "Erelu del Océano y el bote. Erelu del Océano, hija del bote y del lugar santo que está sobre el mar, buscaba abundancia. Le pidieron ofrendar y cumplió. Desde ese día recibió todas las bendiciones que pidió, y cuando se puso a bailar en alabanza, Èṣù le puso una canción en la boca: ven, bote mío, tiembla, bote mío; es buen mar por donde navega mi bote. Este Odù protege a quien sale de viaje, a quien vive del agua y a quien se hace rico trabajando con un extranjero.", "Agbadu, la víbora que espantaba a todos. Agbadu, la víbora de panza suave, iba a ser nombrada jefa. Le pidieron ofrendar y se negó. Desde ese día, todo el que ve a Agbadu sale corriendo. Así le pasa a quien, por ansiedad y desconfianza, ahuyenta a la gente que quiere ayudarlo; necesita valor para dejarse ayudar. El hijo de Ìká Méjì no come mono gris."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Contra la enfermedad y la muerte: la ofrenda marcada más un pangolín (àkàká).", "Para la vida larga: la ofrenda completa, sin dejar nada a medias.", "Contra el problema repentino: un gallo y lo que escoja el sacerdote.", "Para hijos: dos granos de maíz y dos gallinas; sembrar el maíz y ofrecer dos mazorcas a la cabeza (Orí).", "Para cuidar a la esposa: dos cabezas de cobra y una soga de subir palmas.", "Para Ògún: una calabaza de vino de palma, ñame asado y aceite de palma.", "Para que nada se escape: seis agujas.", "Para abrir camino: tres gallos y aceite de palma.", "Para el viaje y el trabajo en el agua: un bote pequeño de madera sobre un plato blanco, plátanos, huevos, una botella de aceite de palma, un ave y dinero para Èṣù.", "Para los problemas de pareja y el miedo: una cabeza de víbora, una paloma, un ave, aceite de palma y dinero para Èṣù."]}, {"titulo": "Relaciones espirituales", "texto": "Ògún pide su parte antes de cualquier pelea. Orí debe ser atendido a menudo para elegir bien. Ọ̀rúnmìlà protege a la esposa del consultante. Tabú: no comer mono gris."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Maíz (dos mazorcas), ñame asado, vino de palma, aceite de palma, cabezas de cobra, soga de palmero, agujas, pangolín. Bote pequeño de madera, plátano, huevos, cabeza de víbora."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 11.1 (yorùbá): Qdan-gejẹ awo Ata-nde: / li o dífá f'Eyin. / Wón ni: / \"ki ó ṣẹbọ nitori oran igbonagbooru\". / Akuką kan ati ohunkohun / ti babaláwo ba fẹ ni ebọ. / \"Ẹyin I t'oun ti Ade Orí oun yẹpẹtẹ yi / lio maa losódą Babaláwo kan lati ṣẹbọ?\" / O kọ ko rú.", "Verso 11.2 (yorùbá): Etuṣeṣefi'nu-igboṣe'le, / Qniwakawakafi'nu-isaṣe'budo: / wọ̀n difá fün Bara Àgbọnnìrègún, / nlos'ode Ifẹ lọ ṣe ire omobibi. / Qkà Méjì / ati abo-adiyẹ Méjì ni ebọ. / Ó gbọ̀ ó rú. / O gbin okà, qkà gbo tan, o ṣẹ Méjì / Ninu rẹ, / O fi bọ Oluṣupẹn rè. / Wọ̀n ni: / \"Eyiti o ṣẹ okà Méjì / ti ofi bọ Oluṣupen rẹ̀, / Kiamaapee ni İkáméji\". / Eniti a dá Ifá yi fún yoo bimo pupo / tabi oun yoo rẹ pupo ninu ayé. / 39 Eyin: fruto de la palma, se usa para obtener el aceite de palma mediante su / cocción al fuego.", "Verso 11.3 (yorùbá): Ojojoṣe-idibẹrg: / li o difá f'Ọ̀rúnmìlà, / nigbi Obirin rọ̀ maa ṣ'àgbéré. / Wọ̀n niki ó rù: / Ori ejó oká móji ati igba opẹ, / ki wọn ma le gba obirin naa li qwọ̀ rẹ / Ở gbọ̀ ô rù. / Pypio ati Oworẹ / Il o nba Ọ̀rúnmìlà du obirin wọ̀n ko le gba obirin naa / nigbati Ọ̀rúnmìlà ti rúbọ. / Obirin Prúnmilà orukọ ti aipe pẹ̀.", "Verso 11.4 (yorùbá): Omipenṣen-akodun-koro: / li o difá fOgún / mi a gbe ogun lọ ja ilu ọ̀tá rẹ̀. / Wọ̀n niki ó rú: / Agbe-ẹmu, ẹsun iṣu ati epo. / Ôgún kó ko rú. / Awọn Babaláwo ni: Ifá wipe: / \"Lati ghun bowale ni wọn ti maagbe / inkan burúkú fún un jẹ / nitori airubo re\".", "REZO: IKA MEYI IGUE IYIOKOOWO ENÑONGO OCUAGUO EDE MEYI OBEDE MEYI OKUNKE YEBRE ELBE EYE AFEKU SHUORERE ADA FUN GUALAMI ALAFUN AROKOKO ARAGUAMERICORUGO ELEGUTE ORUBE O. VEKU SHUGUI AFIYERE SHOUNARO.", "REZO: IKA MEYI IGUE IYIOKOOWO ENÑONGO OCUAGUO EDE MEYI OBEDE MEYI OKUNKE YEBRE ELBE EYE AFEKU SHUORERE ADDIFAFUN GUALAMI ALAFUN AROKOKO ARAGUAMERICORUGO ELEGUTE ORUBE O. VEKU SHUGUI AFIYERE SHOUNARO.", "REZO: EGUAYOKO OWO OÑI OKUO AWO ODE MEYI OBEBE MEYI OKUNI QUELLI AFUFU SHORERE ADAFUN GUALAMI ALAFUN OROKO ORUO GUANAMI CORUE ELEBI ORUE ORUNMILA OWUNKO EYELE MEYI AUE LA MENI IGUAYU KAFEREFUN BUTAE.", "REZO: IKA MEYI IGUO ILLIOCO AGUAGUO EDE MEYI OBEDE MEYI OKUNI QUE ILEBRE EBBO ELLE AFUCU CHERERE ADAFUN GUADAMI ADAFUN ALACOCO ORUBO GUADAMI MEYI CORUBO ELEBUTE ORUBO ORUNMILA. FECU CHUGUI AFILLIERE CHOAN ARUN.", "REZO: IKA MEYI ARO IKA IJOJA OLOFIN IKA KIJAGBO EJENU IKA KI JURUKU ELERI IKA MEYI EGBEDE LERI AJA NIGBAKINO OWALE ENI KAMOGUN OKAWO OFA OFI OMI EBANLE IWA IKU DENDE KINWOKA KERIN DILOGUN NOWA BA ONI KAMOGUN OKAWO EFA OFI LERI OFASHO AYA BARA POKA META LEJEKO ONI KIMOGUN MO AKA META OSA NIRITA OSORDE IGBA AKA META MO IDI AKA META KAFEREFUN ORUNMILA.", "SUYERE: ATORI ATORE ATOWAO AFARINA LERI O (2 VECES) ADEDERE MONI ADEDERE MONI ADEDERE ELEGBA ELEGBA FUMI LERI OUNKO ADEDERE MONI ADEDERE.", "SUYERE: TENTE LERI OBA FOBAO, TENTE LERI OBA FUMI."]}]$q$::jsonb),
(12,'eab420656fa43112a71b65e19eb9c6f8',$q$[{"titulo": "Idea central", "texto": "Òtúrúpọ̀n Méjì, también llamado Ọlọgbọ́n Méjì, simboliza la maternidad y el parto. Sus hijos son resistentes, firmes y tercos: aguantan el trato duro y no se rinden, pero se confunden fácilmente si no tienen buena orientación. Para tener hijos sanos y bien formados pide ofrendar a los antepasados (Egúngún) y a Òrìṣànlá, escuchar a los padres y a los mayores, y atender la cabeza (Orí) con frecuencia."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Pregunta por hijos, un embarazo o el bienestar de su familia.", "Es firme y resistente, pero puede volverse terco si no escucha a los mayores.", "Se va a casar o quiere saber el futuro de una unión (relato de Ọlọ́fin y Pupayẹmi).", "Busca una casa estable o va a cambiarse de vivienda (relato de Yaya y Yayá).", "Le preocupa la salud de un niño o su propia vulnerabilidad (relato de Ikusigbade).", "Llegó a un lugar nuevo y quiere hacerse un sitio (relato de los dos Ogẹ).", "Su valentía puede ponerlo en peligro (relato de Odo, el mortero)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Hijos sanos, bien formados y que crecen.", "Éxito al llegar a un lugar nuevo.", "Vida larga; que la muerte se olvide de uno.", "Una casa propia que dura toda la vida.", "Estar cómodo y asentado dondequiera que vaya."]}, {"titulo": "Ibi y advertencias", "puntos": ["Que el bebé se vaya pronto, el niño que promete regresar (àbíkú).", "Que la audacia lo lleve a la muerte.", "Construir sin ofrendar y ver caer la casa.", "Falta de prudencia y vigilancia."]}, {"titulo": "Enseñanza principal", "texto": "La fuerza sin orientación se vuelve contra uno. El que escucha a sus padres decide bien. Como la raíz del gbégi, que es profunda, quien aparta la maldad se asienta feliz en cualquier lugar."}, {"titulo": "Relatos reunidos", "puntos": ["Ikúsìgbàdé, a quien la muerte olvidó. La muerte andaba buscando a Ikúsìgbàdé, cuyo nombre quiere decir que la muerte se olvide de mí. Le pidieron ofrendar con la cabeza tierna de la palma, cumplió, y recibió la bendición de una vida larga. Si hay un bebé en camino, este Odù pide ofrecer a los Ìbejì para que el niño cambie su promesa de volver pronto con los antepasados y se quede a crecer. Durante el embarazo conviene llevar el control médico.", "Yaya y Yayá construyen su casa. Yaya y Yayá querían construir cada uno su casa. A los dos les pidieron ofrendar. Yaya no quiso, y su casa se cayó. Yayá ofreció, y su casa duró el resto de su vida; vivió cómodo desde ese día. Quien busca un lugar nuevo para vivir debe ofrendar para encontrarlo confortable.", "Los dos Ògẹ̀ en Ifẹ̀. Ọlọ́fin iba a casarse con Pupayẹmi, una joven del Este, y le pidieron dos chivas. Cumplió, y le dijeron que de ese matrimonio tendría solo dos hijos, pero que los dos serían mimados porque llegarían a ser grandes. A esos dos los llamaron Ògẹ̀ Méjì. Antes de bajar a Ifẹ̀ consultaron, y les dijeron que los dos triunfarían allí si ofrecían caracoles, tortugas, piedras de rayo y medicina de Ifá. Así fue.", "El mortero y la raíz del gbégi. Al mortero (odó) le dijeron que apartara la maldad para estar siempre cómodo donde fuera, y que su audacia no lo llevara a la muerte. Le marcaron un caracol, una vaina de pimienta de caimán, dinero y medicina de Ifá. Escuchó y ofreció. Le cocinaron la medicina, y como la raíz del gbégi es profunda, el mortero siempre se sienta feliz en cualquier lugar.", "Ògẹ̀, el mortero que no quiso vigilar. A Ògẹ̀, que es otro nombre del mortero, le pidieron manteca de cacao y aceite de palma para ser prudente y precavido. No quiso. Si lo hubiera hecho, le habrían preparado la medicina, porque a mediodía el aceite de palma está alerta y eso da vida larga, y a mediodía la manteca de cacao está vigilante y eso lleva a la vejez."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Contra la partida del bebé: una fronda de palma (màrìwò), una paloma, un ave, aceite de palma, un plato blanco y dinero para los Ìbejì.", "Para la casa: ofrenda de comida (àdìmú) a los antepasados, a Egúngún y a los Ìbejì.", "Para el éxito: caracoles, tortugas, piedras de rayo (dos de cada uno bastan) y medicina de Ifá; luego poner las piedras de rayo junto al Ifá del consultante.", "Medicina de prosperidad: hojas de okunpale y abo-igbo o agbosáwa molidas y cocidas en sopa.", "Para el matrimonio: dos chivas.", "Para asentarse: un caracol, pimienta de caimán, dinero; hojas de gbégi molidas con la pimienta y cocidas con el caracol para comer.", "Para la vigilancia: manteca de cacao y aceite de palma mezclados con iyẹ̀ ìròsùn del Odù para frotar el cuerpo."]}, {"titulo": "Relaciones espirituales", "texto": "Egúngún (los antepasados) y Òrìṣànlá dan hijos sanos. Los Ìbejì retienen al bebé. Orí debe ser atendido con regularidad. Tabú: la nuez de kola de tres gajos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Fronda de palma (màrìwò), gbégi (Eleusine indica), pimienta de caimán, manteca de cacao, aceite de palma, okunpale, abo-igbo, agbosáwa, tortugas, caracoles, piedra de rayo."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 12.1 (yorùbá): Qkaragba: / li o dífá f'Èji Ọgẹ, / nlọ s'ọlẹ n'lfẹ. / Wọ̀n nì: / Awon Méjì naa ni o maa han n'lfẹ. / A niki wọ̀n rú: / igbin mérindilógún, ijapá mérindilógún / ẹdùn-ààrá mẹrindilógún (méjiméji ti too lo) ati ewé Ifá. / Bio bajẹẹ tan ki ẹniti o jẹẹ naa fi / edùn-àirá le orí Ifá rè.", "Verso 12.2 (yorùbá): Ṣluluṣe'dibẹrẹ: / li o dífá f'Ọlófin, / nlọ fẹ Pupayẹmi, tii ṣe pmọ wọn ni Wonran. / Wọ̀n niki ó rú: ewúrẹ Méjì. / Ó gbọ̀ ó rú. / Wọ̀n ni: / Ọmo Méjì saa li a maa bi / sùgbọ̀n gigẹ niki o ma gẹ wọn / nitoripe àwọn Méjì naa a dijidaira. / Njẹ àwọn Méjì ti a ngẹ n'lfẹ ki / o maa pe wọ̀n ni: \"Ọgẹ-Méjì\".", "Verso 12.3 (yorùbá): Agba igbín-f'idijẹlú: / Il o dífá f'Odo. / Wọ̀n nì: / \"kosi ibi ti o naa wa ti ko niini ibujoko, / gugbọ̀n aya nini li o maa paa\" / lgbin kan, odimdi ataare kan, / ogbokànlá owó ati ewé Ifá. / Ó gbọ̀ ó rú. / A ṣe ewé Ifá fún jẹ gegẹbi / ati wi loke yi nitoripe / Kiobaa le ni ibujoko. / Ajatirinmole niti Gbọ̀gi, / nitorinaa kosi ibiti Odo yoo de / ti ko niini abujoko.", "Verso 12.4 (yorùbá): Kasakaja Katetesa: / li o'dífa f'Ogẹ. / A niki o wa rúbẹ, / ki aya rẹ le maa ja diẹdiẹ. / Orí ati epo ni ẹbọ. / Ko rú bọ. / Biobarúbo a base ewé Ifá fún. / Nitoripe: / \"Bi osan ba pon ominu a kọ epo, / oun lo maa m'epo pẹ. / Bi osan ba pọn aya a pa òrí, / oun lo maa m'ori dagba.\" / Pgẹ oruko Odo.", "REZO: OBORO NI SHORO OLOGUON NIFEDERE NISHORO OWO ONI FEDERE AUN BABALAWO LODIFAFUN TOCUTU KUTU NISHORO OGGUN.", "REZO: OLORO TOROSHE ENI LAY SHORO", "REZO: ODI OLEKERU KURU ODI ELEKURE KURU EÑI EÑI LAWO ADENI LAWO EÑI EÑI LAWO ADONI LAWO, EKU MENI KI EKUN MAPAREWE", "REZO: OTRUPO MEYI OGORO NICHORO LEGUON NIFADERE NI CHODO OCU ONI FADERE BABALAWO TEDINFUNTECUTUTO CUTU ACHORO EKU.", "REZO: OLORO TOROCHE ADIFAFUN EKUO. OTORO TOROCHE EÑI LAY CHORO ISI OLOLAN NINCHORO OLOBAN IFA DERE NINCHORO EGGUN AQUILIPIDE AWO EÑI BANA LOTE IFA DERE NI IFA OLUWO GUAMI OYUGBONA GUAMI.", "REZO: OLDOGAN NICHORO ALOGUAN IFA DIRE CHOCHOLOGUO ONI BABALAWO ADAFUN TECUTU CUTU DIGUE LACHORO SECUN IGUILA ABERE MOCAN DUDUN TUNTUN AIKORDIE OCU EYA EBETA AWO.", "REZO: OLORO TOROCHE EÑI LAICHERO ISIA LOBAN NINCHORO ECUN OGUILIPELE OWO EÑI LONA IFA DERE NIFA OLUO BAMI OLLUBONA BANI.", "REZO: QUERECHETE OWO LADAFUN NIPA PO ADIFAFUN INLE NIPAPO KERE KERE NIPAPO KERE KERE NIPAO KITILLO ARO.", "REZO: BABA OTRUPON MEYI OLOROTO ROCHE EÑI LACHORO RIOLEBAN NICHORO OLOBAN IFA DEREGUN CHORO OCUN OQUI LIPELE AWO EBANA LOTE IFA DERENIFA LON OLUE BAMI OYUGBONA BAMI ORUNMILA ONI OSADIO MACHABA LOGUO OKU LOGUO OKU LOGUO ERIN", "IBABA LODAFUN AGUN GUN OCOCO LODAFUN ORU CHAORDE BAMBA LODAFUN BARA LOMIREGUN ONI BAMBA LODAFUN BARA LODAFUN BARA LOMIREGUN ONI BAMBA LODAFUN BATRA LOMIREGUN ONI BAMBA LOGUEREGUEN CHAGUE BAMBA LEGUEREGUEN CHAGUO.", "SUYERE: OÑIÑI LAISHORO OÑIO OÑIÑI LAISHORO OÑIO OÑI FEKUN LAISHORO EKUN OÑIÑI LAISHORO OÑIO.", "REZO: BABA ADIFAFUN EGGUN, ONIQUE EGGUN ORUBO ABOLERO AJERE ABAKO NILE ADIFAFUN IDADERE BATINLOBA IKU SHORE ABERE MESAN AWO EFUN EURE ADIE MERI OKITI KUELE AWO EBANLA LOTE IGADERE ILE OBATALA NIFA OIN NI OLORO TOROSEINALE AKUKO EYELE AYAPA LEBO.", "REZO: META AGBA OLOFIN ORUNMILA OBATE IYA KAYE OMO ELEGBA ORI OBAIN KOKO INA KALETE SIYA ADIFANFUN OLOGBO IYAFA ELEGBA TUNWA ARAMISHE ADIFAFUN OTRUPON MEYI NANA AGBA ORI ADIFAFUN OKEEY OMO SHOWO EGGUN OSHA KALE AYE EGGUN MODUN NAINA OMO TUTO LORDAFUN IYAFA KAFEREFUN OLOFIN."]}]$q$::jsonb),
(13,'c18937aefb4ae18c0835918bbc561d35',$q$[{"titulo": "Idea central", "texto": "Òtúrá Méjì es paz mental y libertad de la ansiedad. Sus hijos son apacibles, moderados y de carácter suave, y tienen mucho éxito en el comercio, sobre todo comprando y vendiendo. Deben aprender a descansar para no agotarse en cuerpo y mente, y atender a Èṣù con frecuencia para que nadie revele sus secretos ni los separe de su familia. Con ofrendas a Ògún, a Yemọja y a Ifá superan a los enemigos, ganan dinero y tienen pareja e hijos."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene una oportunidad de comprar, vender o empezar una relación, pero necesita organizarse para sostenerla.", "Trabaja sin descanso y está a punto de agotarse.", "Tendrá que viajar o estar lejos más tiempo del planeado (relato de Òtú en Ifẹ).", "Quiere vender algo y busca el mejor lugar para hacerlo (relato de Òtú y las tortugas).", "Le toca fundar, dirigir o poner orden en un grupo, con justicia (relatos de Ọ̀rúnmìlà).", "Pierde dinero o armonía en casa y culpa a alguien cercano; antes debe revisar los hechos.", "Busca calma y sentido espiritual."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Paz mental y tranquilidad.", "Éxito en los negocios y en las relaciones.", "Riqueza vendiendo al mejor precio.", "Fundar un lugar que se vuelve mercado.", "Gente de todas partes que viene a honrarlo.", "Que las cosas salgan con calma, por una vida de devoción."]}, {"titulo": "Ibi y advertencias", "puntos": ["Desgaste físico y mental por no descansar.", "Traición: alguien que revela sus confidencias y planes.", "Parientes o cercanos que lo vuelven atolondrado hasta dejarlo pobre y solo.", "Antepasados o colegas envidiosos que roban la abundancia."]}, {"titulo": "Enseñanza principal", "texto": "El agua corre por el camino y el camino cruza el río: cada cosa sigue su curso con calma. No se vende al primer precio; Èṣù avisa cuándo aceptar. Quien ofrenda a tiempo recibe honra sobre la estera."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀tú y las dos tortugas. A Ọ̀tú le pidieron ofrecer dos tortugas para volverse muy rico, pero le advirtieron que no las matara sino que las vendiera, y que él decidiría dónde venderlas al mejor precio. Llegó a un pueblo y le ofrecieron ochenta sacos de dinero por ellas. Èṣù, que siempre está del lado de quien ofrenda, le avisó que no aceptara. La oferta fue subiendo, y cuando llegó a cientos de sacos de dinero, Èṣù le dijo que aceptara. Así Ọ̀tú se hizo muy rico, y los sacerdotes dijeron: el día que Ọ̀tú compró dos tortugas debe llamarse Òtúrá Méjì.", "Ọ̀rúnmìlà funda un pueblo con el odán. Ọ̀rúnmìlà salía a descubrir y fundar un pueblo. Le pidieron un grupo de hormigas guerreras, jabón negro, cuarenta caracoles ensartados en una cuerda en la oscuridad, tela blanca y un retoño de odán. Cumplió. Le dijeron que sembrara el odán en una arboleda y le atara la sarta de caracoles, que se bañara con el jabón negro mezclado con las hormigas y hojas de odán, y que se cubriera con la tela blanca. Y le aseguraron: el lugar donde se sembró el odán se convertirá en mercado.", "La estera de Ọ̀rúnmìlà. A Ọ̀rúnmìlà le pidieron seis esteras, seis plumas de loro, seis chivas y dinero para gobernar con justicia a su pueblo, y le dijeron que gente de todo el mundo vendría a honrarlo sobre su estera. Ofreció lo más rápido que pudo, y la gente vino de todas partes a honrarlo como se había dicho. Desde ese día los sacerdotes de Ifá se sientan sobre una estera para adivinar.", "Ọ̀tú en Ifẹ̀. Ọ̀tú iba a Ifẹ̀ a hacer su trabajo de adivinación. Le pidieron dos bastones de caminante y dos carneras, y le dijeron que no volvería pronto. Ofreció y se quedó mucho tiempo en Ifẹ̀.", "El devoto de túnica larga. Como el agua corre por el camino y el camino cruza el río, así adivinaron para el musulmán de túnica larga que quería seguir el camino de los inmortales. Le pidieron ofrendar, cumplió, y desde ese día las cosas le salieron con tranquilidad. A quien recibe este Odù le corresponde una vida devota, y así le llegan las bendiciones.", "La Tierra en el mercado. La Tierra quería vender en el mercado y le pidieron ofrendar para que los poderes destructivos que viven en ella no la dañaran. Ofreció, y desde ese día todas las ganancias se quedaron con la Tierra. Este Odù pide ofrendar para que los antepasados destructivos de la familia no roben la abundancia, y ser amable con los colegas para que no se vuelvan envidiosos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la riqueza: dos tortugas que no se matan sino que se venden.", "Para fundar: hormigas guerreras, jabón negro, cuarenta caracoles ensartados, tela blanca y un retoño de odán; sembrar el odán con los caracoles atados y bañarse con el jabón.", "Para gobernar con justicia: seis esteras, seis plumas de loro, seis chivas y dinero.", "Para el viaje largo: dos bastones de caminante y dos carneras.", "Para la devoción: cuatro palomas, cuatro aves, dos sartas de cuentas de rezo, aceite de palma, un plato blanco y dinero para Ọbàtálá.", "Contra los poderes destructivos: una paloma, un ave, un plato blanco, aceite de palma y dinero para Ọbàtálá."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù debe ser atendido con frecuencia y aconseja el buen precio. Ògún, Yemọja e Ifá reciben ofrendas para vencer a los enemigos. Ọbàtálá. Tabú: aceite de palma crudo, sin cocinar."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Odán (Ficus), jabón negro, hormigas guerreras, tela blanca, plumas de loro (ìkóóde), esteras, tortugas, bastones."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 13.1 (yorùbá): Arugbó-ńlá niiṣe ori fegunfegun: / a dífá fÒtú, / mi s'awo lọ salẹ lfẹ. / Wọ̀n niki ó rú: / Opa Méjì ati àgùtàn Méjì / Wọ̀n ni: / ko nii tètè bọ / Ôtú gbọ̀ ó rúbọ. / Ò pẹ.", "Verso 13.2 (yorùbá): Arugbó-Oba ni-nsọ'gbodi'le, / Ìdí-agbani-nṣe jẹkujẹkẹ: / li o dífá f'Ọ̀rúnmìlà, / niọ te ilu do. / Wọ̀n niki ó rú: / Qwo ljamja, Ọ̀ṣẹ́, / Ogoji owo ẹyọ ti a sin li òkùnkùn, / aṣo funfun ati igi-odán. / Ọ̀rúnmìlà gbọ̀ ó rú. / Awon Babaláwo ni / ki Ọ̀rúnmìlà mu igi-odán / yi lọ sinu igbó kan, / kiogbin in sibẹ, / kioso ogóji-owó-ẹyọ ti a sin / li okunkun naa mọg / Kiomaa fi Ọ̀ṣẹ́ naa tia ti gun ewé odánso / ati owo-ijamja ma we. / Kiomaa fi aṣg funfun yen bora. / Bi Ifá yi ba bi èniyàn, / ao sọ fún un pe kioṣe bẹẹgegẹ. / Babaláwo naa yoo sọ fún un / pẹlu idaniloju pe: / \"Ibiti o lọ gbin odán si yẹn, / wọ̀n yoo n'ọjá nibẹ\". / pdán: Ficus sp. L., Moraceae; o Ficus THoNNINGII Blume, Moraceae.", "Verso 13.3 (yorùbá): Okiti-ogán-af'idij'ago / li o difá fOtú. / Wọ̀n niki ó rú: Awun Méjì, / wọ̀n ni a di olórò. / Ôtú gbọ̀ ó rú. / Awon babaláwo niki Òtú / maṣe pa àwọn Awun naa, / tita niki ó ta wọn. / Wọ̀n le Ibo lati mọ ibiti oun iba lọ ta wọn / O losi ilu naa, / wọ̀n yợ wo Awun titi de Ogoji okẹ. / Eṣú sọ fún un pe kioma gba. / Eniti ó ba rúbọ ni Èṣú ngbe. / Nigbi wọ̀n yọ' wo Awun titi ni ilu naa / de Qkẹ-aimoye owó / ni Èṣú sọ fún un pe kio gba. / Bẹẹ ni Ờtú di Ọlórọ̀ si. / Awon Babaláwo ni: / \"ljọ ti Ötú ra Awun Méjì, ki ama pee ni: Otúráméji\".", "Verso 13.4 (yorùbá): Oluṣeṣẹ àwon ni Awo inú-igbó, / Flu-ọ̀dàn-afidij'Odù: / a dífá f'Ọ̀rúnmìlà. / Wọ̀n ni ki ó rúbọ / ki qwọ̀ rẹ̀ le ka ilú rẹ̀. / Ọ̀rúnmìlà ni: / kini ebo? / Àwọn Babaláwo ni: / eni mẹfà, ikoodẹ méfà, / ewurẹ mẹfà / ati ẹgbèfà owó ni ebọ. / Wọ̀n ni: / gbogbo ayé lio maama wọ tọọ / wa sori eni naa. / Ọ̀rúnmìlà yara rúbẹ, / gbogbo ayé si nwọ tọọ, / lori eni naa. / Lati ojo naa ni Babaláwo / ti njoko lori eni difá.", "REZO: QUERENCHELE AGUA NIPAPE LODAFUN GUERE NIPAPE ONDAFUN INLA NIPAPE, GUERE NIPAPE LERUBE GUERE NIPAPE QUITE LLEURE LODAFUN ESUCUN ADIFA NIBATI UN CAGUELERIN.", "REZO: PARENCHELE AGUE NIPARO LODAFUN QUE QUERE LAPE PAPE LERUBE QUE QUERE ORUMILA LEFE UN TERI BEBETONILLE LEBE. ASE CUNDIFA IMALE ADIFAFUN BENI SUCU. ALAFIA ADAFUN MALE ADAFUN ORUMILA UN CHERUNLA LEFE ACODE ETI LLARECE ASABEBE UNTE OCU EYA EBETA EWE.", "REZO: CIRIYAN CIRIJAN ARIFA YOKO KANFUN OWERE OLODAFUN OKETE.", "REZO: ADIFAFUN OKUNRIN OKOLORI LODAFUN AKAN.", "REZO: ADIFAFUN ORUNMILA, OGGUN BORO BORO, ALEYO OKO ITA ILEGGUN, LODAFUN ELEGBA.", "REZO: OSHAGRINIYAN BABA NI ORISHA FUN FUN, UMBOWA AIYE OGBORI OSODE OLORI MEYI LARE NI AIYE ASHE OLOFIN ANIWA ORUN OSIYANI ATIWA ORUN ATIWA OLUO KAFEREFUN ORUNMILA, LODAFUN GBOGBO KALENU ORISHA.", "SUYERE: BABA ALAYEO BABA ALAYEO LEKUA UMBO OMINIYO LAYEYEO OKUNI BABA.", "REZO: ALAFIA BORUKU OLORUN KOKOIBERE ABAYIKI SUMAJANA SALAMALEKUN MALEKUN SALA ANGMO SEDA ITANA MEDINA AKANA IBODUNOSATU OMI INA KUPA BELEYO MODUN MODUN LODAFUN SAHNGO KAFEREFUN MALE. REZO: ASOKUN NIFA ADIFAFUN SALE MALE MALE AU SALE AWONSI ABONIRAYE IFA ONIRE OLOFIN OMO IFA ABABANIREGGUN EGGUN OTOLA MAYERE NI AWO OMONIFA SALE MALE MALE OU MALE", "MAYIRE ABONIKUN ORUN ALWARODE EGGUN YEYEKUN ORUN SALE MALE MALE OU SALE AWO ORONIFA IFA KAFEREFUN EGGUN ORUNMILA SHANGO Y OLOFIN.", "REZO: ORUNMILA ASOKUN DIFA IMALE NI AWO ORUNMILA NI INLE NI IBO BAYEKUN AUN LOSILE OMO BABANIREGGUN ORUNMILA AWO OBA BARA NIFE ADIFAFUN OLOFIN ADIFAFUN SHANGO ADIFAFUN ORUNMILA."]}]$q$::jsonb),
(14,'3e40a9510792b0d8e362941e4702da66',$q$[{"titulo": "Idea central", "texto": "Ìrẹtẹ̀ Méjì enseña que lograr las cosas por caminos indirectos tiene su recompensa y que la humildad es una gran virtud. Advierte contra las intrigas de enemigos que trabajan para reducir las oportunidades del consultante, que además se ha vuelto conformista. Llama a dedicarse por completo a Ifá: los varones de este Odù deben iniciarse. A quien cree, Ọ̀rúnmìlà le da dinero, pareja, hijos, vida larga y felicidad. Si hay un enfermo, pide ofrendas a Ọbalúayé (Ṣànpọ̀nná) y a las àjẹ́, y también atención médica."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se está conformando con algo que ya no le sirve y eso lo lleva a un problema.", "Desea tener hijos o sufre por no lograrlos (relatos de Òdonràdà e Imò omi).", "Recibe burlas o le preocupa el qué dirán (la misma boca que alaba también ofende).", "Tiene una meta importante, pero su firmeza se volvió terquedad.", "Está cansado o presionado y necesita descansar y atender su cabeza (Orí) antes de decidir.", "Su forma de ser le complica la convivencia con otros (relato del cangrejo Akon en el mercado).", "Va a asumir una responsabilidad espiritual o a iniciar a otros."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Que ninguno de los que se inician muera joven.", "Muchos hijos de buen carácter.", "Que las bocas que se burlan se cierren.", "Un compañero fiel que nunca abandona.", "Dinero, pareja, hijos, vida larga y felicidad por la devoción a Ifá."]}, {"titulo": "Ibi y advertencias", "puntos": ["Intrigas de enemigos.", "Conformismo que lleva a la dificultad.", "Estrés, depresión o humillación por fuerzas malévolas.", "Cansancio e impaciencia bajo presión.", "Burla de la gente."]}, {"titulo": "Enseñanza principal", "texto": "La boca que hoy alaba puede mañana insultar: al rico le dicen 'buenos días, señor', al pobre 'buenos días, pobre'. Lo que el ser humano ha perfeccionado es la burla. Quien se cubre con lo que no debe, se mancha."}, {"titulo": "Relatos reunidos", "puntos": ["Ìrẹ̀n y los dos iniciados. Ìrẹ̀n iba a iniciar en Ifá a dos hijos de Ọlọ́fin y le pidieron ofrendar para que ninguno de los que él iniciara muriera joven. Ofreció, y el día en que Ìrẹ̀n inició a dos personas que no murieron se llamó Ìrẹtẹ̀ Méjì. Ọ̀rúnmìlà también, de camino a Ifẹ̀, ofreció dos palomas y lo demás que marcó Ifá, y le lavaron la cabeza con hojas de tẹ̀tẹ̀ trituradas en agua: ninguno de los que él inicia muere joven.", "El cangrejo y el mantón. Al cangrejo (akàn) le dijeron que su conducta no encajaba con la gente del mercado y que, si quería corregirse, ofreciera un recipiente de aceite de palma y un mantón. Se negó. Un día de mercado llevaba un recipiente de aceite en equilibrio sobre la cabeza; al intentar envolverlo con su mantón, se le cayó encima y el aceite le manchó la ropa. Desde entonces el aceite de palma le tiñó el cuerpo, y así lo lleva en la espalda hasta hoy. Al hijo de este Odù se le advierte que nunca se cubra con un mantón.", "Olúwẹri y el cangrejo fiel. Olúwẹri, espíritu del río, iba a comprar al cangrejo como sirviente. Le dijeron que si lo adquiría nunca más necesitaría de nadie, y le pidieron una palangana nueva, una chiva y ẹfun. Ofreció, puso el ẹfun en la palangana nueva y entregó la chiva. Antes había tenido sirvientes humanos que lo maltrataron y lo abandonaron; solo el cangrejo se quedó con él, y tuvo muchos hijos.", "El cerdo de camadas incontables. Pètèpétè adivinó para Òdonràdà, la cerda, que lloraba por hijos. Le pidieron ofrendar, ofreció, y se volvió la cerda distinguida de camadas que no se pueden contar.", "La boca que alaba y la que insulta. Ajílósòó, el sacerdote de la orilla del camino, adivinó para la boca de los seres humanos, que tiene dos caras. Le pidieron ofrendar para que la misma boca que lo alababa no se usara para insultarlo; ofreció. Si uno tiene dinero, le dicen: buenos días, rico; si es pobre, le dicen: buenos días, pobre. Un saludo vale más que el otro. ¿Qué es lo que el hombre ha perfeccionado en el mundo? La burla. Ifá promete cerrar las bocas que se burlan de esta persona.", "Los niños de Ìpéré Àmúyọ̀. La gente de Ìpéré Àmúyọ̀ iba a criar a sus hijos con aguardiente. Les pidieron ofrendar, cumplieron, y desde ese día sus hijos desarrollaron buen carácter.", "Imọ̀ Omi y las cuentas. La cuenta de abajo a la izquierda y la de abajo a la derecha nunca discuten entre ellas: así adivinaron para Imọ̀ Omi, que quería tener hijos en la tierra. Ofreció y recibió la bendición de los hijos, y Èṣù le puso en la boca este canto: no hay hijos en venta; quiero más a los hijos que a las cuentas. La mujer que quiere hijos ofrece de sus joyas y pide a los antepasados la bendición."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para los iniciados: dos palomas y lo que marque Ifá; lavar la cabeza con hojas de tẹ̀tẹ̀ en agua.", "Para el carácter: un recipiente de aceite de palma y un mantón.", "Para el compañero fiel: una palangana nueva, una chiva y ẹfun.", "Para hijos de buen carácter: un ave, una paloma, aceite de palma, un plato blanco, ẹ̀kọ (pastel de maíz) y dinero para Ọ̀ṣun y para Ifá.", "Para tener hijos: una paloma, un ave, cuentas, ẹ̀kọ, aceite de palma, un plato blanco y dinero para Ọ̀ṣun y para Ifá.", "Contra la enfermedad: ofrendas a Ọbalúayé y a las àjẹ́."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà pide devoción total; los varones deben iniciarse. Ọ̀ṣun da hijos. Ọbalúayé y las àjẹ́ en caso de enfermedad. Olúwẹri, espíritu del río. Tabúes: el gallo, la espinaca y cubrirse con mantón."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Tẹ̀tẹ̀ (Amaranthus hybridus), ẹfun, aceite de palma, ẹ̀kọ (pastel de maíz), cuentas, palangana nueva."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 14.1 (yorùbá): Qkan awo Olúigbó: / li o difá f'Ọ̀rúnmìlà, / nigbi Ọ̀rúnmìlà mi lọ si lfẹ̀ / Wọ̀n ni: / \"iye ẹniti Ọ̀rúnmìlà ba tẹ̀ ko ni ikú\". / Ewé tẹ̀tẹ̀, ẹyẹlé Méjì / ati bẹẹbẹẹ ni ẹbọ / Ó gbọ ó rú. / Wọ̀n gbo ewé tẹ̀tẹ̀ sinu omi / kio fi fọ orí.", "Verso 14.2 (yorùbá): Adá-ilé-o-mukankan: / Il o difá fún lrẹn / niọ tọ̀ âwon Méjì ninu ọmọ Ọlófin. / Wọ̀n niki ó rúbo, / awọn ti o nlọ tẹ̀ ko ni ikú. / Ô gbọ̀ ó rú. / Wọ̀n ni: / \"Vọ ti lrẹn tẹ̀ Méjì ti wọ̀n ko kú / ki a ma pee ni: İrẹ-tè-Méjì\".", "Verso 14.3 (yorùbá): Odan-ab'orípẹgunpẹgun: / li o difá f'Akon. / Wọ̀n ni: / Iwá Akọn koniiba ti ọjà mu, / nitorinaa bi Akọn ba fẹ ki iwà oun / ba ti qjà mu kiowa rú: / Ata-epo ati aṣo olokoleti / Akọn kọ ko rú. / O wa di ojọ qjà, / Akon gbe ata epo rè ru, / o fi pantete, / bi o ti nfe lati da aṣo Olokoleti re bora, / bẹẹ ni ata (ikoko) epo rẹ yi tiosi si oju de, / o fo sii laṣo, / Epo ti o fo si Akon lara ni ojo naa / liosi wa ni ẹhin rẹ̀ titi di ònì yi. / Bi Ifa yi ba bi èniyan, / ki a kilą fun ẹni naa pe: / ko gbodẹ maafi aṣo-olokoleti bo'ra.", "Verso 14.4 (yorùbá): Adilu-abidiṣumuṣumu: / li o dífá f'Olúwẹri5s, / nigbi Olúwẹri mi lo ra Akon l'erú. / Wọ̀n n: / \"erú ti o nlọ rayi konjii / jẹki èniyàn tan ni qwọ̀ rè\". / Awo-titun, ewúrẹ / ati ẹfún li ebọ. / Olúweri gbọ̀ ó rú. / Akọn (bimọ) rẹ pupo. / Ọmo-èniyàn ni Olúwẹri ko ra l'erú. / Wón nbuu ni ibukubu wón si nló. / Akọn nikan ni ko lọ. / Ko çfún sinu awo titun / naa kiopa ewürẹ fún un.", "REZO: EYELEMERE AKORE AYARE EYELEMERE LAFIDAYA EYELEMERE AWAREI FENISHE KIA IFA AYE ADIFAFUN ORUNMILA, ADIFAFUN OSHUN, ADIFAFUN POROYE, PAÑUELOS MARUN ELEBO.", "REZO: EYELEMERE AKOLEMERE POROYE OMO NI OSHUN ONIBARABANIREGUN ORUNMILA MO IFA ONI AWO AKOLEMERE. ORUNMILA LORUBO.", "REZO: INSO RO EBO EI ASHE WADIPOLA ASHE WADIPOLA ODO LOFUN ALABEO ASHE WADIPOLA."]}]$q$::jsonb),
(15,'1ce699dc6c59d6e00b47df3ecb656c79',$q$[{"titulo": "Idea central", "texto": "Ọ̀ṣẹ́ Méjì es victoria sobre los enemigos y dominio de las dificultades. Es un tiempo de condiciones cambiantes en los negocios y en las relaciones, pero bueno para el amor y el dinero. Sus hijos llegan a viejos si ofrendan y cuidan su salud; deben fortalecer su fe en Ifá y confiar en su propia inteligencia, porque la falta de fe y de seguridad en sí mismos es su mayor tragedia. Para el amor y la prosperidad ofrecen a Ọ̀ṣun; para vencer a los adversarios, a Ṣàngó y a Ọ̀rúnmìlà."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Su negocio o su relación pasa por altibajos y busca estabilidad.", "El dinero le llega y se le va (relatos de Ajé, la riqueza).", "Busca amor, matrimonio o hijos.", "Necesita recuperar la confianza y no dejar que el miedo lo domine.", "Va a viajar o quiere ser reconocido (relato de Òtú camino a Ijebu).", "Desea llegar a viejo con bienestar (relato de Arugbó).", "Hizo una ofrenda a medias y eso le afecta (relato de Èjì-Ọ̀ṣẹ́)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Vejez larga con el cabello blanco.", "Que el mundo entero lo busque, como busca la riqueza.", "Ser una persona importante.", "Que los malos espíritus no puedan llevárselo.", "Recibir las bendiciones del mundo espiritual en la tierra."]}, {"titulo": "Ibi y advertencias", "puntos": ["Dudar de todo y de todos, aun de la verdad.", "Una riqueza que no se asienta en ningún lugar.", "Ofrendar solo una parte.", "Brujas que quieren llevarse a la persona."]}, {"titulo": "Enseñanza principal", "texto": "Solo la ofrenda salva al ser humano; la vida se vuelve amarga para quien no ofrenda. La cabeza de la tortuga no duele, el hígado del caracol no le duele, la piedra del fondo del río no siente frío."}, {"titulo": "Relatos reunidos", "puntos": ["Los dos ancianos. A los ancianos les pidieron una gallina, dieciséis pedazos de ẹfun y una canasta colmada de algodón para llegar a viejos entre los Odù. Ofrecieron y vivieron hasta tener el cabello blanco. Al que envejeció mostrando sus canas entre los Odù se le llamó Àgbà Méjì, los dos ancianos.", "Èjì Ọ̀ṣẹ́ y los bastones rotos. Èjì Ọ̀ṣẹ́ iba a Ifẹ̀ y le pidieron ciento sesenta rollos de algodón y dieciséis bastones. Ofreció solo dos de cada cosa. En el camino se le rompieron los dos bastones, pero no murió, y se dijo: entre todos los Odù, el que rompe dos bastones y no muere se llama Ọ̀ṣẹ́ Méjì. Por haber ofrecido a medias, al hijo de este Odù le flaquea la fe: siempre cuestiona a los sacerdotes y le cuesta creer la verdad.", "La riqueza que todos buscan. La alegría adivinó para Ajé, la riqueza, y le dijo que el mundo entero andaría siempre buscándola. Le pidieron todo lo que la boca puede comer. Ofreció, y el mundo entero es feliz buscando a Ajé.", "La riqueza que no se asienta. Al gallo que usa la cresta como fuego adivinó para Ajé y le pidió, para que tuviera una vida asentada, la pata de un animal muerto sin cuchillo. Ajé se negó, y por eso hasta hoy la riqueza no se queda quieta en ningún lugar.", "Ọ̀rúnmìlà y los malos espíritus. Todos los malos espíritus del mundo querían llevarse a Ọ̀rúnmìlà. Él dijo que también tenía un dueño, su espíritu guardián, que lo libraría de sus manos. Fue con los pájaros blancos del termitero: unos le pidieron kola blanca, otros kola roja, y los que bajaron volando del termitero, pimienta de Guinea. Con eso le prepararon medicina contra la muerte, diciendo: la cabeza de la tortuga no duele, el hígado del caracol no duele, la piedra del fondo del río no siente frío; los malos espíritus no podrán llevárselo.", "La kola y sus hermanitos. La kola venía del cielo a la tierra y le pidieron ofrendar para que los seres humanos no la mataran. Los hermanos menores, los gajitos pequeños, ofrecieron; los mayores no. Por eso la gente parte la kola y se come los gajos grandes, y deja aparte los pequeños. Se mastica kola y se sopla después de marcar el Odù en la pared, para que las brujas no puedan llevarse a la persona.", "Ọ̀tú en Ìjẹ̀bú. Pórómisolé adivinó para Ọ̀tú, que iba de viaje a Ìjẹ̀bú. Ofreció, y desde ese día fue una persona importante.", "Túwàṣe y la bondad del cielo. Cuando llega la noche, las hojas del monte se transforman, y las hojas de gbódógi se vuelven persona: así adivinaron para Túwàṣe Ihùlóko, que quería traer a este mundo el bien del país de los inmortales. Ofreció, y desde ese día ese bien viajó hasta aquí. La fortuna de esta persona está repartida entre el mundo de los espíritus y el de los humanos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la vejez: una gallina, una canasta de algodón y dieciséis pedazos de ẹfun.", "Para el viaje: ciento sesenta rollos de algodón y dieciséis bastones, completos.", "Para atraer la riqueza: todo lo que la boca puede comer.", "Para que la riqueza se asiente: la pata delantera de un animal muerto sin cuchillo.", "Contra la muerte: kola blanca, kola roja y pimienta de Guinea; el Odù se marca en iyẹ̀ ìròsùn y se echa en un guiso de tortuguita y caracol pequeño con sal, pimienta y aceite de palma, y se come.", "Contra las brujas: marcar Ọ̀ṣẹ́ Méjì en la pared con ẹfun y osùn; tres gallos y dinero.", "Para ser importante: una paloma, un ave, buñuelos de frijol, aceite de palma, ẹ̀kọ y dinero para Orí.", "Para las bendiciones del cielo: cuatro palomas, cuatro aves, aceite de palma, un plato blanco y dinero para Orí."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀ṣun da amor, matrimonio y dinero. Ṣàngó y Ọ̀rúnmìlà vencen a los adversarios. Orí recibe las ofrendas. Ajé, la riqueza."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Algodón, ẹfun, osùn (polvo rojo), obì (kola blanca y roja), pimienta de Guinea, tortuga, caracol, bastones."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 15.1 (yorùbá): Titọni-nkun'le ti-nmuk'awotọ: / li o dífá f'Arugbó. / A niki ó rú: / abo-adiyẹ, ago-òwú / ati ẹfun mẹrindilógún, / ki oun le pa ewú s'ẹhin / ninu àwọn Odù. / Ó gbọ̀ ó rú. / Ó pa ewú s'ẹhin / Njẹ eyiti o pa ewú s'ẹhin ninu àwọn / Odù ki a maa pee ni: \"Àgbàméji.\"", "Verso 15.2 (yorùbá): Oṣekẹṣekẹ: / li o dífá f'Ajé, / wọ̀n ni: / \"tirẹ ṣa ni gbogbo ayé / yoo maafi ṣe nà iṣẹ\". / Ó ni: \"kini ẹbọ?\" / A niki o ba le ri bẹẹ, / Ohungbogbo ti enu i jẹ ni ebo. / Ajé gbọ̀ ó rú. / Gbogbo ayé si ńyğ le Ajé ṣẹkẹṣẹkẹ.", "Verso 15.3 (yorùbá): Akuko fi Ogbè orí rẹ̀ ṣe iná: / li o difá f'Ajé. / A niki Ajé / baa le ni ibujoko ki ó rú / Ekiri Apadafa / (Ekiri tiapa laifi obe kan an). / Odimdi kan. / Ajé kọ ko rú. / Nitorinaa titi o fi di ònì olóni yi, / Ajé kii joko s'ibi kan.", "Verso 15.4 (yorùbá): Oluwẹwẹgbe'nú-igbó-tẹfá: / li o difá f'Èji-Ọ̀ṣẹ́ / nhọ s'alẹ lfẹ̀. / Wọ̀n ni ki ó rú: / ati Opa mẹrindilögún. / Opa Méjì ati Qjo-òwú li ó rú. / Ó mura nlọ s'alẹ Ifẹ̀, / bi o ti niọ laipẹ loju ona, / opa Méjì tiorú ṣẹ tan, / ṣùgbọ̀n oun ko kú. / Njẹ Babaláwo ni: / \"Eyiti o ṣẹ opa Méjì / ninu awọn Odu ti ko ku, / ki a maa pee ni: Oséméji\" / Nitorinaa, bi Ifá yi ba bi èniyàn, / gni naa a maa déjà, eyini mipe, / oun yoo ma mu awon awo li eke / Eniti o ṣoro fün lati gba ótitọ̀ gbọ / ni eniti i maa d'gjá.", "REZO: OSHE ALADASHE ONIBARA BANIREGUN IFA MOLOKU FISHE, SHENSHE MOLOKU ADIFAFUN OSHUN.", "REZO: KULU KULOSHE MULUKO UN BABALAWO, LODIFAFUN KANTAPO NIBATI UNLO SIFE LLAMA ODESE ORUNRE OMO OROCO OMO ERAN NIBATI ATAPA OWO LODE ALLO LLIGOBO BOTON LOSI- LLE ONIBIRI. ILE LA POLEDI A UN BABALAWO LODIFAFUN BANLE QUERE ADEFUN.", "REZO: KULU KULUCHE OCHE MOLOCHA MONUKO BABA LODIFAFUN AKATAPON NIBATI INLO SILU LLAMA ADERE ORI ERE OMO AROCO INDE NIBATI OTABA UN ODERE ADIFAFUN ALLOLLI OGODO OTONOULO SILLELE ONI BINI ORUMILA ELBICAN ADIFAFUN YOKO OKANFUN ORUMILA ELBICAN LOLE CHIERE ELESE LELE OIGUA BOBO EBBO KURU ESHU OBINI ORULA OCHUBITANI LOLABE OMODE CEFE ECHUBI LENE AFOFO IGUA- GUO ORUBE.", "REZO: BABA ELLI MEYI KULU KULUCHE KOLLO TIBALOCUCHE OPECHE MULUKU MULUKU ADIFAFUN KAKATAMPO LLAMAGUO ODDUN IRE DEFUNGUO.", "REZO: KULU KULUCHE EYO KOBANI OCHE MULICU A UN BABALAWO LODIFAFUN ACANTAPO NIBATI INLOS ILE LLAMA EDERE ERUNLE OMO A ROCO OMO OCU OLEDE LA NO LA FUN ALLO IGO IGO DOBOTONLE SILE OMI BINI.", "REZO: CHUBU CHERE CHERE ABARE CHERE ACHOLLUA A UN MELLILI ADIFAFUN ARUROYO TICHOMO QUIYA ECHUBU SHERE SHERE ASHE UN EYO AUN MEYIYI SHERE SHERE ADIFAFUN ELLEROLLETON CHOME Y CANA OGUN.", "REZO: OSHE MEYI ORULA EBACUNLO BOBEOMODI OCHUBU CHU OBINI ORUMILA NISISI EBOCORALOLA COCHUBU TENUTIA ORUNLA OCHUBU IRE OWO IRE OMO IRE ARICU BABAGUA.", "SUYERE: IKU IWA KALERO ARUN ILE KALERO EGGUN IWA ILE KALERO. OSHUN WERE WERE ODO OLUN OSHUN KANI SHENSHE LEBO AWO APETEVI NI MALE ILE BANAKUESI OWO IYE LODAFUN OWUNKO FI SI EBBO. SHENSHE OLOWO OSHUN SHENSHE OLOWO OSHUN SHENSHE OLOWO IYA KUENI MOWO OYE SHENSHE OLOWO OSHUN. SHENSHE OLOWO YALORDE MAYEO.", "REZO: KULU KUKUSHE OSHE MULUKU MULUKU LODIFAFUN KANTAPONI- BATI UNLO SILE YAMA ODERE ORUNRE OMO ROCO ERAN NIBATI ATABA AWO LODE LODAFUN AYO YIGODO BUTON LOSILE YALORDE OBINI ORULA ESHUBA TANI ESHUBA LOLA IRE OWO IRE OMO IRE ARIKU BABAGUA.", "REZO: ADDO BUELEGE ADDO BUELEGE AYA, ADIFAFUN AKATAPULTA, KAFEREFUN YALORDE."]}]$q$::jsonb),
(16,'be16d6217bae289a045e517851e7e5f5',$q$[{"titulo": "Idea central", "texto": "Òfún Méjì, también llamado Ọ̀ràngún Méjì, es buena fortuna de dinero y una vida de dar y recibir con paciencia y compromiso: con las ofrendas correctas el éxito está asegurado. Las cosas están floreciendo. Sus hijos son generosos y, aunque no siempre tengan riquezas, son ricos en sabiduría. No deben vivir donde el viento sopla fuerte porque se sofocan con facilidad. Para prosperar ofrecen a Ajé y a Olókun, y lo más importante es ser bondadosos con los extraños, con la familia y sobre todo con los pobres. Para una mujer joven anuncia embarazo; para quien viaja, un buen viaje si ofrenda."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Algo empieza a florecer y necesita sostenerlo con paciencia y compromiso.", "Busca dinero, aunque ya tiene otros bienes: conocimiento, amigos o capacidad de ayudar.", "Va a viajar y quiere que le vaya bien.", "Pregunta por hijos o por el futuro de la familia (relato de Ọlọ́fin y los dieciséis Odù).", "Tiene una deuda u obligación pendiente, quizá heredada (relato de la deuda de las madres de los Odù).", "Siente oposición y busca apoyo (relato de Eléjiórangún).", "Espera respuesta a una petición, una obra o un proyecto (relato de Òrìṣànlá)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Fortuna de dinero.", "Autoridad que nadie puede cuestionar.", "Abundancia y todas las bendiciones que se necesitan.", "Vencer a los enemigos.", "Un viaje que sale bien.", "Ser cabeza de la familia por haber pagado por todos."]}, {"titulo": "Ibi y advertencias", "puntos": ["Contentarse con tener hijos sin ofrecer por su prosperidad.", "Dificultades para respirar en lugares de mucho viento.", "Deudas de ofrenda que dejaron los mayores."]}, {"titulo": "Enseñanza principal", "texto": "Ningún Ifá es mayor que Èjì Ogbè y ningún signo es mayor que Òfún Méjì. Los sacerdotes no deben estar ansiosos por el dinero, sino por la sabiduría. El que paga por todos llega a ser cabeza de todos."}, {"titulo": "Relatos reunidos", "puntos": ["Odù crea el carácter de todo. Odù iba a crear el carácter de todas las cosas que venían al mundo. Le pidieron cuatro postes, una calabaza grande con tapa y una cadena, y le aseguraron que nadie cuestionaría su autoridad si clavaba los cuatro postes juntos en la tierra, ponía encima la calabaza y se ataba los postes a las manos con la cadena. Así lo hizo, y el día en que Odù creó el carácter de las personas, los animales y todas las cosas se llamó Odùduwà. Creó todo lo que existe dentro de esa calabaza con tapa, y los seres humanos vivimos todos dentro de ella.", "Ọlọ́fin y los dieciséis hijos. Ọlọ́fin iba a dar a luz a los dieciséis Odù principales. Le dijeron que sus hijos serían pobres, y que si quería que fueran ricos debía ofrecer dieciséis calabazas de ñame machacado, dieciséis de ẹ̀kuru, dieciséis de ọ̀lẹ̀lẹ̀ y dieciséis carneras. Se negó: dijo que le bastaba con darlos a luz. Ofreció solo por sí mismo. Por eso los sacerdotes no deben ansiar el dinero sino la sabiduría y el poder. Además, a Èjì Ogbè y a los otros quince les pidieron ofrecer para pagar la deuda de ofrenda que dejaron sus madres, y se negaron: por eso los sacerdotes rara vez tienen riquezas, aunque son ricos en sabiduría.", "Ọ̀ràngún paga en la frontera. A Ọ̀ràngún Méjì le pidieron una carnera, dieciséis palomas y dinero. El sacerdote dividió la ofrenda y le dio la mitad para que, al volver a casa, rogara a su cabeza. Pero al llegar le avisaron que su madre lo esperaba en el campo junto con sus hermanos mayores, y se fue con ellos llevando los materiales. En la frontera el portero les cobró el paso. Èjì Ogbè, el mayor, no tenía el dinero, ni ninguno de los otros catorce; solo Ọ̀ràngún, el decimosexto, lo tenía, y pagó por todos. Al llegar al campo, los catorce decidieron hacer cabezas de la familia a Èjì Ogbè y a Ọ̀ràngún. Desde entonces se dice que ningún Ifá es mayor que Èjì Ogbè y ningún signo es mayor que Òfún Méjì, y por eso en el ìbò se decide a favor del que salga de los dos.", "Òrìṣàálá y la abundancia. Ogbè el forastero adivinó para Òrìṣàálá cuando buscaba abundancia y le pidió ofrendar para que todo lo que hiciera fuera aprobado. Ofreció y ese día recibió todas las bendiciones que necesitaba. Quien adora a Ọbàtálá debe ofrecerle comida con el rezo de este Odù.", "Eléjì Ọ̀ràngún entre enemigos. Todas las cosas aparecen como espinas que lastiman los pies: así adivinaron para Eléjì Ọ̀ràngún cuando estaba rodeado de enemigos. Ofreció, y desde ese día los derrotó. Este Odù pide ofrenda a Orò, que sostiene el esfuerzo contra los enemigos.", "El ojo que llegó a rey. Corremos a cortar caimitos, caminamos despacio a cortar caimitos, pero como no tenemos a nadie que cuide el árbol siempre los comemos verdes: así adivinaron para el Ojo cuando lo iban a hacer rey. Le pidieron dos palomas, dos huevos, dinero y un trozo de manteca de karité. Ofreció, y por eso nadie ve sin los ojos: el Ojo ve por todos. El Rey del Cielo creará un gran mercado de destino para alguien que afecte a toda su familia, y pondrá a un niño en una posición importante.", "Ifá, el que todos ridiculizaban. No se debe defecar en la finca del que no tiene tiempo de cuidarla, ni andar por su lindero, ni comer sus ñames: así adivinaron para Oníwọ̀nránólé, que es un nombre de Ifá, cuando la gente se burlaba de él una y otra vez. Le dijeron que en su vejez el mundo entero se reuniría a servirle. Ofreció una chiva, una rata, un pescado, una gallina y kola. Ifá dice que alguien a quien en su casa llaman perezoso será dueño de toda la casa.", "Ọ̀rúnmìlà y los cuatrocientos Òrìṣà ante la muerte. Cuando el Rey del Cielo mandaba a la muerte a llamar a los cuatrocientos Òrìṣà, Ọ̀rúnmìlà los reunió, cocinó una olla de caracoles, una de pescado y una de ratas, compró una canasta de papilla de maíz y sacó una tinaja de agua. Después de comer les dijo que fueran juntos y unidos al cielo, no de uno en uno. Pero ante Olódùmarè, los cuatrocientos acusaron a un hombre negro con cuentas ide al cuello de trastornar el mundo, y pidieron que no volviera a la tierra. Olódùmarè preguntó a Èṣù, que los vigilaba, y Èṣù dijo que mentían: ese hombre curaba a los enfermos, comía solo las ratas y pescados que le correspondían, y antes de venir les había dado de comer y beber a todos. Entonces Olódùmarè ató a los cuatrocientos en el cielo y mandó a Ọ̀rúnmìlà y a Èṣù de vuelta a la tierra. Por eso caracoles, pescado, ratas, papilla de maíz y agua se usan en las ofrendas, y por eso Ifá y Èṣù son tan importantes en la tierra. No se rompe un juramento con un amigo.", "El hijo enfermo de Ọ̀rúnmìlà. Ọ̀rúnmìlà y Èṣù encendieron un fuego de leña de munrun: así adivinaron para Ọ̀rúnmìlà cuando la salud de su hijo no era buena. Le pidieron un gallo, seis nueces de kola y dinero para que el niño no muriera. Ofreció y su hijo vivió. Ante un hijo enfermo, además de ofrendar, hay que llevarlo al médico.", "El viaje a Agege. Aṣinṣinrin, adivino del pueblo del Vengador; Ikandu, adivino del pueblo del Malhechor; y la hormiga que barre el suelo con la cola adivinaron para Ọ̀ṣun me da alegría, que es como una pelea repentina, cuando iba a Agege. Le pidieron siete ratas, siete pescados y dinero. Ofreció. Quien va a hacer un viaje a pie debe ofrecer para volver a casa contento."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Para la autoridad: cuatro postes, una calabaza grande con tapa y una cadena.", "Para hijos prósperos: dieciséis calabazas de ñame machacado, de ẹ̀kuru y de ọ̀lẹ̀lẹ̀, y dieciséis carneras.", "Para la cabeza: una carnera, dieciséis palomas y dinero.", "Para Ọbàtálá: ofrenda de comida (àdìmú) con el rezo del Odù.", "Contra los enemigos: cuatro palomas, cuatro aves, aceite de palma, un plato blanco, ẹ̀kọ y dinero para Orò.", "Para el destino: dos palomas, dos huevos, dinero y manteca de karité; molerla con hojas de 'déjame sentarme', la sangre de una paloma y un huevo, y frotarse el cuerpo.", "Para ser servido en la vejez: una chiva, una rata, un pescado, una gallina y kola.", "Contra la muerte: caracoles, pescado, ratas, papilla de maíz y agua compartidos.", "Protección: marcar Òfún Méjì en la pared con ẹfun y osùn, mascar kola, soplarla y decir que todo mal que venga sobre uno perezca.", "Por el hijo enfermo: un gallo, seis nueces de kola y dinero.", "Para el viaje: siete ratas, siete pescados y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Odùduwà, creador del carácter de todo. Ọlọ́fin, padre de los dieciséis Odù. Ajé y Olókun dan prosperidad. Ọbàtálá. Orò. Olódùmarè y Èṣù defienden a Ọ̀rúnmìlà."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Calabaza grande con tapa, ẹ̀kuru, ọ̀lẹ̀lẹ̀, ñame machacado, manteca de karité, caimito (ọsàn àgbàlùmọ̀), ẹfun, osùn, obì."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 16.1 (yorùbá): Ọgbaragada: / li o dífá f'Odù / mi a da dede Uwa / (Iwa-tabi gbogbo ohun ti o wa li ayé). / Wọ̀n niki ó rú: / Opo merin, / igbá ademu / ati ẹwọn. / Ó gbọ̀ ó rú. / Wọ̀n ni: / \"kosi eniti yoo maa yeẹ lowo wo / nitorinaa kiolo ri opo mẹrin na, / kio gbe igbá yen lee lori, / kiofi ewọn yen / Soo mọ owọ̀ ara rẹ̀\". / Ô gbọ̀ ó ṣe gbọ / naa si Ojude ara re / bi wọ̀n ti sọ fún un. / Ni ljọ ti Odù da gbogbo iwa / [Ohun ti o wa l'ayé) / li a tinpee ni Odùduà / (Odu ti o da gbogbo lwa, / Ooduà, Odùduwà, Olódùmarè) / Ninu igbá naa ni Oun da gbogbo / Uwa si, ninu igbá naa ni gbogbo / (eda-alaayé) wa wa yio.", "Verso 16.2 (yorùbá): Arugbo-ilé-fi-ire-sa-kẹjẹkẹjẹ: / wọ̀n dífá f'Ọlọ̀fin / nlọ bi Irúnmale mẹrindilógún. / Wọ̀n ni: / \"àwọn omọ na ko nii n'owó lọwọ\". / Nitori ki wọ̀n baa le ni owó lọwọ / ki wọ̀n rú: / İgba ewo mérindilógún, / igbá ekuru mẹrindilógún, / igbá olẹlẹ mẹrindilógún, / ati àgùtàn mẹrindilógún. / Ọlọ̀fin kọ ko rú. / Ó ni: bi oun ba ti bimo ṣa, o to, / ebọ ti ara rè lo rú. / Nitorinaa ni àwọn Babaláwo koṣe / nilati ma sare lati ko owó / jẹ bikoṣe lati ko Ọgbọ̀n ati Agbára / jọ ni gbogbo igba wọ̀n li ayé.", "Verso 16.3 (yorùbá): Bi a ba ni ki abu ilẹ̀, / llẹ̀ a mọ ilẹ̀pa: / li o difá f'Èjìogbè / ati àwon Odù Mẹṣdogun / tiiṣe Olódü yokun. / A ni ki wọ̀n rúbọ / ti Ìyá wọn kọsilẹ. / Wọ́n kọ wọ́n ko rú / Nitorinaa ni Babaláwo koṣe jẹ / Ọlọ̀rọ̀ ninu owó bikoṣe ninu Ọgbón.", "Verso 16.4 (yorùbá): Àgbàgbà-ilúf'idikodi, / a difá fOràngúnméji. / A ni ki ó rú: / àgùtàn kan, / ẹyẹlé mẹrindílógún / ati egberindílógún owó. / Ó gbọ̀ ó rú. / Babaláwo pin ohun ẹbọ si Méjì. / O ko apa kan fún ara rẹ̀, / o si ko apakeji fún Çràngúnméji / pe ki o lọ fi bọ Orí ara rè / nigbati o ba delé. / Bi Ọ̀ràngúnméji ti delé ni wọ̀n jiṣẹ / fún un pe lyá re / ti ranse de ilé pe ki oun / ati àwọn gbọ̀n rẹ̀ maa bo ni oko. / Nitorinaa oun ko duro bọ orí ara rè / mọ ni ilé. / O di àwọn ohun-ẹbo naa ru. / O lọ ba àwọn gbọ̀n rẹ̀ lati jüjọ lọ soko / lọ ba lyá wọ̀n gegẹ bi ati jiṣẹ fún un. / Nigbati wọ̀n de enu'bode, / Oni bode bere owó ibode lowo wọn. / Èjìogbè ti iṣe aṣiwaju / gbogbo àwọn Odù / ko ri igbio san fún Onibode, / bẹẹ ni àwọn Odù merinla ti o telee / ko ri owó san, / ayaafi Oràngúnméji, / tiiṣe Odù Ekerindílógún li o ri owó / ibode san ki gbogbo wọ̀n / to le koja los'oko. / Nitorinaa nigbati wọ̀n de oko tan / ni àwọn Odù iyokun wa fi / Ogbèméji ati Ọràngúnméji se olorí. / Lati ojo naa ni a ti npe / Ọ̀ràngúnméji ni \"Òfúnméji.\" / Lati ojọ naa ni a si ti nwipe: / \"A kii d'Ifá bori Èjìogbè, / A kii d'Ifá bori Öfúnméji\" / Nitorinaa biaba dibo tiada Èjìogbè / tabi Öfúnméji / àwọn li a o gba Ibo fun.", "/ OFUN MEYI", "REZO: ORAGUN MEYI ORUNMILA ADIFALLOCO LODAFUN OBATALA KUA SHANGO SHA OBATALA DICE EBICAN LOLO OGGUN SHURE SHANGO SHURE OYURE OBATALA IGUA OMO IGUA OSA OMO IGUA OSA OMO OBATALA ASHE OBATALA ASHE OLUO SHORERE SHANGO OGGUN GUALI GUAYU ENITI KUITICOLA OLORDUMARE.", "REZO: BABA ELLEGUN SIGUN JECUA BABA ORAGUN CAWO CAWOSILE ENI BABA ALA BABALUCHE BABA OMO LORUN ANIMU AUN NICU LODAFUN OBI AFANTICHE OMO ICU EBBO TETE EYELE MEYI AIKORDIE ITANA OBI EKU EYA EPO ABECA OWO.", "REZO: BABA ORAFUN CAIOSILE ONI LACHE BABA OMO REUN OMO ORUBO COLLAMORO ACHE QUINCHE OMI IKU.", "REZO: ORUNMILA ADIFALLOCO ADIFAFUN OBATALA IGUA OMO ERUN OMO ORUBO COLLAMORO ASHE OBATALA ACHOMO TARA OQUE OGUALI GUALLU KUITE KOLA MORCO KAFEQUE.", "REZO: BABA ELLEFUN LLEGUN JEKUA BABA JEKUA BABA ORAGUN KABIOSILE ONI BACHE OMO OLORUN MIOMIO OLORUN ABIMO AUN ICU LODAFUN OBI AFANTICHE OMO IKU OCHE LLEGUN ODAFIN DODO UMBATI LOCHORUN ORISHA IBA OCUNLE EBICAN LONLO COMA DEREU (HABLA YEWA, JEKUA, BABA ).", "REZO: OROFUN MAFUN YEWEDE OFUN LARA OBIRI EFURURU LAKOKU EFURU RU LAKOKE OKERE ORISHADI ARAYE KOWEDO BI BABA OROLU AWA NI", "KOMIO.", "REZO: ASHE OLUZO OLUZO LOBOKA OLUZOLE LOBERE OLUZOLE LOBI OPOLO IGBIN LABOKA LOKA YOGUN ORO BI LAÑERE ESE YOGUN ORUN IBI OPOLO YOGUN EGUI AYALI POPOLO DAFE EKO EBE EKO BOFENU LOLE AYARUN AKUKO, ADIE, ABERE, INIABA, OMI IFA NI EGGUN BABA.", "REZO IYESA: HABA AWA EYEGUN JERI JEKUA BABA AROWO ONIBOSHE BABA EMI OMO OLORUN OUN OMA ABIMO OLOKU LODA OBI EFAN UMBATI OBI EFAN OUN ARUGBO EBBO NURU OMO ABOKUN. ORAGUN MINIKUN ORIWAL LA ONA GURU GURU MOBA KPUI MINU MOBA KPUI YEYE MOBA KPUI NIKABO KUAN TARA TARA MIWAFUN ASHO HOWORUBO.", "REZO: IRE NISHE IYA ELEGBA IRE NISHE IYA OGGUN, IRE NISHE IYA OSHOSI, IRE NISHE IYA OSUN, IRE NISHE IYA GBOGBO ORUNMALE AYOKOTUN GBOGBO ORUMALE YOKOSI BARABA NIGERUN ADIFAFUN ORUNMILA.", "SUYERES: PEREGUN ALAWA LO TUN TUN. PEREGUN ALAWA LO TUN TUN BABA DE MALO AFIBO MINI. PEREGUN ALAWA LO TUN TUN.", "ORUN JUN JUN AWA MI MOKIO. ORUN JUN JUN AWA MI MOKIO. ORUN JUN JUN ORUN JUN JUN.", "ORAYE YEYEO ORAYE NITOWORO NITA NITA WORO AY IL GOGO AYAI GOGO AYAI AGOGORE.", "KAYE REREO OLOWAO KOBALOKUN OTA OBA YAREO OMO SHANGO OLABAO EGUSHE ARERE RIPIN OLALEKUN OBA YAREO.", "REZO: BABA ORAGUN AWA AYEWA BABA AIKA BABA AREWO ONI BASHE BABA AIKA OMI OMOLORUN AUN ABIMI ABEKE LEDA OBI EFUN OUN ABATI OBI EFUN OUN OZAIN ARUGBO EBBO KURU OMO ABOKU EBBO ABOKU EYELE EKO EKU AYAPA AWADO ORI.", "REZO: IREMI YABO IREMI YAYA ADIFAFUN ORUNMILA ADIFAFUN OGGUN ADIFAFUN SHANGO OGGUN OSHOSI ADIFAFUN OSUN ADIFAFUN OLOKUN OBA ARUGBO OKORO AYARE ADIFAFUN ELA."]}]$q$::jsonb),
(17,'ca86bfb460eddbbd180de2d76e208858',$q$[{"titulo": "Idea central", "texto": "Ogbè Ọ̀yẹ̀kú pide usar la inteligencia, la ofrenda y el consejo de Ifá en lugar de la fuerza o el pleito. Por grande que sea la persona —en poder, dinero o autoridad— necesita escuchar al babaláwo. Lo que se hace con fe en Ifá deja obras que no se destruyen."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Gasta mucha energía en ganancias rápidas que no duran.", "Se le abre una oportunidad, pero trabajar sin descanso o pelear sin necesidad puede cortarla.", "Tiene autoridad o dinero y cree que ya no necesita consejo.", "Le cuesta equilibrar trabajo, descanso y disfrute.", "Tiene una competencia o un obstáculo en un viaje y busca regresar bien (relato del camaleón Alàgemo y Olókun).", "No duerme bien o arrastra un conflicto que pasa de una persona a otra (relato de Olúkotún, Ọlọ́fin y el rey).", "Se pregunta por la muerte y el sentido de estar en la tierra (verso de la tierra como mercado y el cielo como hogar)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ifá favorece a la persona durante el año.", "Superar obstáculos y regresar bien de un viaje o de una competencia.", "Las obras que ha construido no serán destruidas y quedarán como testimonio.", "Una vida placentera para quien cumple su ofrenda."]}, {"titulo": "Ibi y advertencias", "puntos": ["Gastar mucha energía en ganancias que duran poco.", "Pelear con alguien más poderoso sin preparación.", "Insomnio y riesgo de muerte repentina por no atender lo espiritual.", "Que otros le arrebaten lo que Ifá le había dado."]}, {"titulo": "Enseñanza principal", "texto": "La autoridad no exime de consultar. El rey que no podía dormir tuvo que entregar lo que se le pidió, y quien quiso quedarse con lo ajeno terminó pagando lo mismo. Con astucia y ofrenda, el pequeño camaleón le ganó a Olókun."}, {"titulo": "Relatos reunidos", "puntos": ["Olúkọ̀tún y la hija de Ọlọ́fin. A Olúkọ̀tún Ajamlolo le dijeron que ese año Ifá lo iba a favorecer mucho. Ọlọ́fin lo mandó llamar dos veces para que le consultara, y las dos veces respondió que no podía ir porque estaba adorando a su Ifá. Cuando por fin llegó, Ifá dijo que a Ọlọ́fin no le pasaba nada grave: solo que no podía dormir de noche. Como ofrenda debía entregar a Olúkọ̀tún a su hija mayor adornada con cuentas en muñecas y tobillos, dos chivas grandes y 4,400 cauríes. Ọlọ́fin cumplió. Pero la gente se burló de que una muchacha tan bella se fuera con un adivino pobre, se la quitaron en el camino y se la dieron a un rey. Entonces el rey tampoco pudo dormir, mandó llamar a Olúkọ̀tún, y Ifá le marcó lo mismo: entregar a su joven reina, dos chivas y 4,400 cauríes para evitar una muerte repentina. El rey cumplió, y Olúkọ̀tún se fue a su casa cantando: 'Así es como Ifá me favorece, así y siempre'.", "El camaleón y Olókun. Alàgemo, el camaleón, iba a la fiesta anual de Olókun y quería competir con él vistiendo la misma ropa. Le marcaron 20,000 cauríes, doscientas palomas y telas de muchos colores, y cumplió. En la fiesta, cada vez que Olókun cambiaba de ropa, Alàgemo cambiaba de color y lo igualaba. Olókun se enfureció y buscó a sabios y hechiceros para cerrarle el camino de regreso. Alàgemo volvió a consultar: le marcaron una estera de rafia, una jícara de ñame machacado y cosas variadas, y le enseñaron un canto: 'Que los hechiceros me dejen en paz, que las brujas me dejen en paz; cuando el buitre se coma la ofrenda, dejará la jícara aquí'. Le dijeron que tendiera la estera sobre el río y se sentara en ella. Lo hizo así, venció todos los obstáculos y llegó bien a su casa.", "El hombre blanco que viaja por el mar. Ogbèyèkú, el padre de todos los Àmùlú, consultó para el hombre blanco, hijo del clan que usa el océano como camino y la laguna para lavarse los pies. Le pidieron ofrecer, ofreció e hizo regalos a Èṣù, y le dijeron que las obras que construyera no serían destruidas y se recordarían por siempre.", "La Tierra y el Ẹ̀dan. El mismo Odù consultó para la Madre Tierra y para el Ẹ̀dan, el distintivo del babaláwo. Los dos preguntaron si la vida les sería placentera; los dos ofrendaron, y la vida les fue buena a ambos, igual que al hombre blanco."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọlọ́fin y el rey: la hija mayor con cuentas en muñecas y tobillos (después, la joven reina), dos chivas grandes y 4,400 cauríes.", "Alàgemo (primera consulta): 20,000 cauríes, doscientas palomas y telas de varios colores.", "Alàgemo (para el regreso): una estera de rafia, una jícara de ñame machacado y cosas variadas; tender la estera sobre el río y sentarse en ella.", "El hombre blanco, la Tierra y el Ẹ̀dan: ofrenda y regalos libres a Èṣù."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá favorece al que lo adora antes que a la autoridad. Olókun, dueño del mar, aparece como rival del camaleón. Èṣù recibe los regalos libres. El babaláwo y su Ẹ̀dan son protagonistas de uno de los versos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Ñame machacado, estera de rafia, telas de colores, cuentas y cauríes."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 17.1 (yorùbá): Ekumini, / Ekumini: / li o dífá f'Olúkptún Ajamlolą / ti ise baba Oitolú. / Wọ̀n ni: / \"nínú Qdún yi ni Ikin (Ifá) rè yoo gbee\" / O pẹ diẹ ṣa, / Ọlọ̀fin ranṣẹ si pe kiowa difá fún òun. / Ó niki wọ̀n lọ sọ fún Ọlọ̀fin / pe òun ṣi nbọ Ifá òun / ni lowọlową yi na o Ọlofin tun ranṣẹ / tọọ ni erinkeji pe kiomaa bọ / Òun si tun ranṣẹ pada si Ọlófin / gẹgẹbii ti iṣaaju pe òun ṣi nbọ / Ifá òun na. / Ọlọ̀fin dahun Ó ni: / Ifá kini Olúkotún Ajamlolọ mbọ to bayi, / Ifá naa gbee ndan? / Nigboose Olúkòtún Ajamlolo de o wó / Ifá fún Ọlọ̀fin / Ó ni: / Ọlofin, kosi ohun ti nṣé ọ̀, / o ni sisùn li o sùn ti o ko lee sün're l'oru / Nitorinaa ki ó rú: / Arẹmo rẹ, / kiofi ilẹkẹ owọ̀ ati ti ẹsẹ̀ rẹ sii l'ara, / ake-ewúrẹ Méjì / ati Eejilélógún owó. / Ó gbọ̀ ó rú. / Bi o ti nko àwọn ohun ebọ / ti a npe Eru re ilé, / àwọn èniyàn berẹ sii p'egan rẹ / ati Ọlófin pe: / Alaṣo kan yi ni Ọlófin fa pmọ fún? / Wọ̀n gba omobirin naa li qwọ̀ rẹ. / Wọ̀n muu lọ fún Ọba kan pe / ki o maa fẹẹ, / nitoripe ayába ni omobirin naa bamu. / Ọba tii wọ̀n fa omobirin naa lọ fún tun / sùn ko le sùn're l'oru / Ó ranṣẹ lọ pe Olükotún Ajamlçlo / pe ki owa wò Ifá fún oun. / Ó de, ó ni Ọba, / kosi ohun Méjì ti nṣe q, / sisùn li o sùn ti o ko lee sün're l'oru ni. / Nitorinaa bioba wipe ki o ma kú, / ki o yara mu Olorí (aya'ba) kan wa / àti ẹni-ajoji kan tio wa ni ilé rẹ / Kiofa wọ̀n fún Babaláwo / tiowa ni Orí-ite Ifá, / Ake-ewúrẹ Méjì / ati eejielógún owó. / Ọba gbọ ó rú. / Olúkọ̀tún Ajamlolo / ko inkan wọnyi losi ilé rè. / O de ilé tan o korin bayi: / Ekumini, / Ekumini, / bayi n'Ifá sẹ ngbéni ati bẹẹbẹẹ. / Ekumini, / Ekumini:", "Verso 17.2 (yorùbá): Awod'oro-awo-omodé, / Ìká-o-tan-boro-awo-àgbàlagbà / Eerẹtikekerepakẹsẹ-ijam'ẹsẹ: / a difa f'Alàgemo / nlọ b'Olókun pesi Odún / Wọ̀n niki ó rú: / Egbàáwa owó, igba eyẹlé / ati oniruuru aṣo. / Ó gbọ̀ ó rú. / Awon awo si ṣe ewé Ifá fún un. / Alágemo wa ranṣẹ si Olókun pe / Kiakii f'oun sẹ o, / Oun bowa baa pẹsi Odún, / kosi aṣọ ti Olókun maa lo ti / òun kò niilo iru rẹ gegẹ o. / Olókun ni: / Hẹn! Alágemo nilẹ-ẹlẹ? / Ó nì: / o di igbati o ba de ihin wa ba oun na. / Qjg ko, Alágemo de. / Olókun bẹrẹsii lo aṣo / Iru aṣo ti Olókun ba lo, Alágemo a loo / Wọ̀n jüjọ lo aṣo titi / Nigbooṣe Olókun wa binu. / Ó ni òun yoo di ona / ti Alágemo yoo gba pada si ilé rẹ̀. / Ó lọ bẹ àwọn Oṣó ati Ajé lowẹ tii, / kỉ wọ̀n ba òun ṣe idiwọ / fún un li ònà ajo si ilé rẹ̀. / Alágemo tun tọ Babaláwo lọ pe: / Kini òun iba ṣe / ki ọ̀nà-ajo òun silé le dára? / Wọ̀n niki ó rúbọ / Eni-agbafi, / igbá-ewo / ati oniruuru inkan miran. / Ó gbọ̀ ó rú. / Wọn ṣe ewé Ifá fún un wọ̀n si kọo / li orin ti oun yoo maa kọ bayi: / Oṣó ibe ẹ jowo mi. / Ajẹ ibe ẹ jowọ mi. / Bi Igún ba j'ẹbọ a jọọ'gbá. / Ati pe ki o na ẹni rẹ̀ si ojú omi / Kiogun le orí eni naa. / Alágemo ṣe gegẹbi imoran / àwọn Babaláwo rè. / O si bowalé.", "REZO: OGBE YEKU BABA OMOLU ABAKAKA BABA O AN ADIFAFUN AWANO IKIBE AKORA KEKE AWANO TIO PITO BIYE LEKE ERANKO ANDOBELASHI GBOGBO ERANKO LORUBO KEKE MEDILOGUN ERAN MALU, EKU, EYA, AWADO, OÑI, OPOLOPO OWO.", "SUYERE: EDAFON SHURO MI ORE, EDA EWE EDA EFUN AGAYU RAUN OSOMOBO MOBO SODOROMI YARE IYA LODE ABA.", "REZO: OGBE YEKUN NI BABA OMILU AGBA OLOYA NIRO DEMU, AGOGO NLA SHENU GBAGBA LONI NI PARIKOKO OTENU DUNDUN NI PARASIDI OTENU BATA JAD YEKUN ADIFAFUN OZAIN LODAFUN ORUNMILA KAFEREFUN OJUANI MEYI.", "REZO: AKUENO OLORI ASHUBO AWO KAKA ADO ADIFAFUN ORI KAFEREFUN ORUNMILA.", "REZO: OGBE YEKUN KUKUTU ADIFAFUN GUONITI AFITI BIYE LOGBU ORUNGAN.", "REZO: OGBE YEKUN BABA OMOLU ABAKAKA BARA ADAN ADIFAFUN KENE UN TIO PIO BIYE LOKE ERANKO ALUBODE LANSHI LORUBO.", "REZO: OGBE YEKUN BABA OMOLU BABA ADIFAFUN SHORO KOKO EPASIDA IKIBO OKARA KOKO ROKO OKO KOBERU OGBE.", "REZO: OGBE YEKUN OMOLU OBA KAKA EDAN ADIFAFUN YEBEKA OKA APEINDA IKIBO OSHOSI KAKARAKA OKO KOBORUN OGBE LOLA OGBE TEKE OUN KOYE KOBIN ADIFAFUN KENKUN TIO PIO EYELE LOWO ERANKO OLUBEBE GBOGBO ERANKO ETU LORUBO.", "REZO: OGBE YEKUN BABA OMOLU BABA ADIFAFUN SHERE KEKE EPISANDA IKIBO SHERU KEKE OKO KOBORU OGBE YEKU LO TOKE OUN KOSHE KOTIN ADIFAFUN OWUNKO ITA FIRE IYE REWE OLUBAMBA TOLI LEBO ETU KORUBO MEDILOGUN ERAN MALU, OÑI MEDILOGUN OWO ELEBO.", "REZO: OGBE YEKUN NI BABA OMULO AGBA OLOYA NIRO DEMU, AGOGO NLA SHENU GBAGBA LONI NI PARIKOKO OTENU DUN DUN NA LORI NI PARA OTENU BATA JAD OGBA YEKUN ADIFAFUN OZAIN, LODAFUN ORUNMILA. OJUANI MEYI.", "REZO: KUKUTO KUKO ADIFAFUN GUONITI AFITI BIYE LOUGBU ORUNGO."]}]$q$::jsonb),
(18,'c10914a2ab5fff0ccfba425667b58bc3',$q$[{"titulo": "Idea central", "texto": "Ogbè Ìwòrì habla de confusión emocional y de relaciones que se empiezan o se terminan, pero asegura un buen final cuando se aprende de lo vivido. Pide no contar los planes antes de tiempo, porque el que los deshace está cerca."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Duda entre empezar o terminar una relación y debe separar la emoción del momento de lo que ya aprendió.", "Quiere que un proyecto llegue a buen fin sin perder lo ganado (relato de Ogbè visitando a Ìwòrì).", "Va a salir a un lugar nuevo y debe cuidar el camino y elegir bien dónde llegar (relato del cazador y el agricultor).", "Contó sus planes antes de tiempo y alguien cercano se los echó abajo (relato de Èbù Èyìn y Ògún).", "Una amistad se está enfriando por tacañería, enojo o desconfianza.", "Pregunta por un embarazo o por la responsabilidad de criar hijos.", "Se siente desordenado por dentro o teme quedarse sin apoyo (relato de la corneja Alukunrin)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Un final exitoso para lo que se emprendió.", "Riqueza que regresa a la persona y no se le escapa.", "Encontrar buen lugar en un camino o en una tierra nueva, si se ofrenda antes de salir."]}, {"titulo": "Ibi y advertencias", "puntos": ["Contar los planes y que alguien cercano los deshaga.", "Tacañería que desacredita a la persona frente a sus amigos.", "Riesgo de perder el juicio por no cumplir la ofrenda.", "Enojarse al descubrir quién es el enemigo."]}, {"titulo": "Enseñanza principal", "texto": "Lo que se planea se cuida en silencio. Èbù Èyìn deshacía todo lo que Ògún hacía hasta que Ògún dejó de contar sus planes. Y la corneja que no quiso desprenderse de sus dos únicas ropas acabó perdiendo la cabeza."}, {"titulo": "Relatos reunidos", "puntos": ["Ogbè visita a Ìwòrì. Antes de ir a ver a Ìwòrì, a Ogbè le marcaron tres chivos, tres gallos, la ropa que llevaba puesta y una rata de monte que debía quedarse siempre detrás de Èṣù, porque ese viaje le traería riquezas y había que asegurarse de que no se le escaparan. Cumplió. A quien le sale este Odù debe ofrecer para garantizar un final feliz.", "La corneja y sus dos ropas. Ogbèhofaafaa consultó para Alukunrin, la corneja, y le aconsejó ofrecer las dos únicas ropas que tenía, una negra y una blanca, con un chivo y un carnero, para no volverse loca, y dejarse atender con medicina de Ifá: un baño preparado con hojas contra la locura (masínwín), ọgbó y esùsù y la sangre del chivo. La corneja no quiso ofrecer.", "El cazador y el granjero. Ogbè miró hacia atrás para ver si su perro había matado a la rata. Así se consultó para el cazador que iba a siete bosques famosos y para el granjero que iba a escoger tierra nueva para su cosecha. A los dos les advirtieron que tuvieran cuidado en esos lugares y que ofrendaran antes de salir. Los dos cumplieron.", "Èbù Èyìn, el hermano de Ògún. Ògún era enérgico y siempre estaba planeando algo, pero todo lo que hacía amanecía deshecho al día siguiente. Fue a Ifá y le dijeron que ofrendara y que dejara de contar sus planes y sus viajes: que decidiera en el momento y no le avisara a nadie. El que lo deshacía todo era su propio hermano, Èbù Èyìn. Desde que Ògún dejó de contar, Èbù Èyìn ya no pudo arruinarle nada."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ogbè: tres chivos, tres gallos, la ropa que llevaba puesta y una rata de monte que se deja detrás de Èṣù.", "Alukunrin (rechazado): sus dos ropas, negra y blanca, un chivo y un carnero; baño de masínwín, ọgbó y esùsù.", "El cazador y el granjero: ofrenda antes de salir.", "Ògún: ofrenda y no contar los planes."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù guarda la riqueza que regresa. Ògún es protagonista del relato de los planes deshechos. Ifá y los babaláwo preparan la medicina."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Masínwín, ọgbó y esùsù (baño contra la locura); rata de monte."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 18.1 (yorùbá): Ogbèwẹ̀hin-fuu-àlejò-mbọ, / Ogbàrà-ejimaketoto: / a dífá f'Ogbè / nlọ s'ode lwòri. / Wọ̀n niki ò wa rùbọ: / Òbúkọ mẹta, / akuko-adiẹ mẹta, / aṣọ tiowa ni orùn rè / ati oridan eku kan / (kiamu eku naa si iduro lehin Èṣú). / Nitoripe o maa b'ọ̀rọ̀ de / ati pe ki prọ̀ naa ma baa foo. / Ó gbọ̀ ó rú.", "Verso 18.2 (yorùbá): Ogbèhofaafaa: / a difá fún Alukunrin (Kanna-Kanna) / Wọ̀n niki / ó wa ti aṣo Méjì kan bayi / (òkan dúdú, ekeji funfun) / tiowa lowọ rẹ rúbo / pẹlu Öbúko ati agbo / kioma baa sínwin / ati biobafẹ ki àwọn Awo / ṣe ewé Ifá fún oun. / Alukunrin kọ̀ kò rú.", "REZO: OGBE WEÑE MAFEREFUN OBATALA, OBATALA ALEYO UMBO INEDI IRE UMBO OMOFA EBE BODA KIMI IDERELE ADIFAFUN ASHEGUIDA ORUNMILA ADSHEKUE KII EYELE, AIKORDIE, EKU, EYA, EPO, AWADO, OPOLOPO OWO.", "SUYERE: MOÑU EKUE, MOÑU EKUE MOSARAO, OPOLO YAMI OPOLO YUMI MOÑU EKUE MOSARAO.", "REZO: LERIKAN ADIFAFUN AWO SARAKO BABA WELE AWO ABANITA AYE OBA ORUNMILA KOLADE OBE KAILEBO LEBO OGBE WEÑE SARAKO LAYE.", "REZO: OGBE WEÑE DOGUO ADAFA OMI BABALAWO ERA OLONA EWE AYA AYALORUN EWE EBOKARA OMI SIBA AKORDIE, EYELE, ETU.", "REZO: OGBE WEÑE KAFEREFUN SHANGO, OBATALA ALEYO UMBO IRE UMBO OMOFA UMBO, ALAFIA MANI LELU TOFE ORUNMILA AYE ORUNMILA FOMBO INTORI EURE ASHO ARA OJIBARA OMI OLE LUAYU OLUO ENCO UMBO LEÑO KOKOTO NILARA KOFEREBO EKU EYA, OPOLOPO OWO.", "REZO: OGBE IWERI IFANI GUENI GUENI GUATO ORUNMILA LODAFUN ALEYO LODAFUN SHANGO SHAQUITI NERBO OLUO ORA ADIFAFUN ORUNMILA ILE OLOKUN EURE LEBO SHAQUITI LEBO OLUO ARUN ADIFAFUN OSHORI QUINSHO LORO LORO LERI ORDA AKUKO LEBO KAREFUN OLOKUN, YALODE OBINI ORUNMILA QUINSHE ELEBO ADIFAFUN ABA LO OLEBO EKU, EYA, AYA, KONO ELEDE IKON KONI AYA OGRIAN TANKATE IYALE LO DRIAN OLO DE OGRION EBITIPAN Y AWO EMBEPAYA GRIO OBINI BORIO.", "REZO: OGBE WEÑE SILEDEO AWO SHOGOIKO AWO BABA SHERE.", "SUYERE PARA DAR CANDELA A ELEGBA: MALANGE IKU INAFE MALANGE IKU MALANGE IKU INAFE MALANGE IKU.", "SUYERE PARA OBATALA: ORISHA OBATALA BABAE PRISHA OSHANIA BABA EE.", "REZO: LERIKAN ADIFAFUN AWO SARAKO BABA WELE AWO ABANIA AYE BABA ORUNMILA KOLADE OGBE KAILEBO LEBO OGBE WEÑE SARAKO LAYE.", "REZO: ADIFAFUN OLOFIN OLOTORUN OMO AYE EGUGUN ORUN OKUARIBO", "ADAKE DAYE BABARIWO AWO OMITUNTUN AYEKALE ARUN SHE A BANI OFINTO OMO KEKE OBINI AYE LODAFUN ORUNMILA ABEBA-DAWINO IDELE OMO OLOFIN."]}]$q$::jsonb),
(19,'3c90ee6e27cb4f8f7c5de3ef3236ee26',$q$[{"titulo": "Idea central", "texto": "Ogbè Ìdí habla de hacer la ofrenda completa y a tiempo para no quedar atrapado, endeudado o en ridículo. Las presiones emocionales, muchas veces de pareja, frenan lo práctico mientras no se alivian. También anuncia hijos y amistades que vuelven de lejos con fortuna."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Hay presión en lo afectivo y, mientras no la atienda, le cuesta sacar adelante un proyecto.", "Va a una salida o expedición y debe medir el obstáculo antes de meterse (relato de Ogbè atrapado en el elefante).", "Quiere salir de una deuda, pero otros lo distraen con encargos (relato de Èṣù pescador).", "Alguien querido que está lejos puede volver con buenas noticias (relato de Baáyannì y Ṣàngó).", "Desea tener hijos (relato de Àjàgbé).", "Trabaja para ganar más y ampliar su círculo.", "Siente celos o interrupciones en su avance."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Una persona querida que está lejos regresa con buenas cosas.", "Muchos hijos, tantos que se encuentran en todas partes.", "Fortuna compartida con el mejor amigo.", "Salir de una deuda o de un aprieto."]}, {"titulo": "Ibi y advertencias", "puntos": ["Quedar encerrado o atorado en un lugar por no ofrecer antes de salir.", "Deudas que esclavizan.", "Que otros se aprovechen de lo que uno trabaja.", "Beber vino en exceso."]}, {"titulo": "Enseñanza principal", "texto": "El que se niega a ofrecer termina en aprietos y el que cumple queda libre. Èṣù se volvió servidor de Ọ̀rúnmìlà por no hacer su ofrenda; Ogbè quedó atrapado dentro de un elefante hasta que su gente ofreció por él."}, {"titulo": "Relatos reunidos", "puntos": ["Ogbè dentro del elefante. Ogbè iba de cacería y le marcaron tres chivos, tres gallos y 6,000 cauríes para no quedar encerrado en el monte. Se negó. En el bosque empezó a llover; corrió a meterse en un hueco que creyó era un tronco hueco o un hormiguero, y era el ano de un elefante. El elefante lo cerró y Ogbè no pudo salir. Su gente lo buscó sin encontrarlo, y al final decidió hacer la ofrenda que él había dejado. Entonces el elefante lo expulsó. Por eso dijeron: 'al Ogbè que salió de un ano lo llamaremos Ogbèdi'.", "Cómo Èṣù quedó viviendo afuera de la casa de Ọ̀rúnmìlà. Èṣù debía mucho a Ọ̀rúnmìlà, a Òrìṣà-ńlá, a Òrìṣà-oko y a Ògún, y en ese tiempo era pescador. Le marcaron cáscaras de nuez de palma, nueve palomas y 18,000 cauríes para pagar sus deudas, y no quiso. Como su trampa sacaba mucho pescado, los irúnmọlẹ̀ temieron que pagara y se liberara, y el mismo día lo mandaron a lugares lejanos: Ọ̀rúnmìlà por su bolso y su batea a Oke-Biṣi, Òrìṣà-ńlá por su bastón a Ìrànjé, Òrìṣà-oko a Ode Irawẹ, Ògún por su machete largo a Ode-Ire. Ọ̀rúnmìlà consultó antes y le marcaron seis conejos, seis palomas y 12,000 cauríes; metió los conejos en su bolso y le dijeron que no lo soltara. Èṣù, en vez de viajar, conjuró todo desde el arbusto más cercano y regresó de inmediato: encontró a todos repartiéndose sus pescados, y ellos los escondieron en sus bolsas. En Ifẹ̀ estaba prohibido robar, así que los demás le perdonaron las deudas a cambio de que callara. Ọ̀rúnmìlà negó haber robado, y Èṣù lo acusó porque juraba ver narices de pescado saliendo de su bolso. En la corte de Ifẹ̀ abrieron el bolso y salieron los seis conejos. Avergonzado, Èṣù pidió perdón, ofreció empeñar su casa y sus bienes, y Ọ̀rúnmìlà no aceptó; entonces dijo que lo serviría para siempre. Ọ̀rúnmìlà no lo dejó entrar: le dijo que él comería adentro y le compartiría afuera. Desde ese día Èṣù vive fuera de la casa de Ọ̀rúnmìlà.", "Baáyannì regresa del bosque. Ifá consultó para Baáyannì cuando iba al bosque de Ìsèlè y le deseó mucha fortuna si ofrecía. Su compañero, el que se quedó en casa, era Ṣàngó. Baáyannì volvió con tanto dinero que le dio una parte a Ṣàngó, y Ṣàngó la ató a su ropa. Ifá le pide a quien saca este Odù que cuide mucho a su mejor amigo.", "Àjàgbé, la mosca. Àjàgbé lloraba porque no tenía hijos. Le pidieron ofrecer y lo hizo. A Àjàgbé lo conocemos como la mosca, y no hay ciudad en el mundo donde no se encuentren sus hijos. La gente se preguntaba cómo alguien podía tener tantos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ogbè en la cacería (rechazado): tres chivos, tres gallos y 6,000 cauríes.", "Èṣù (rechazado): cáscaras de nuez de palma, nueve palomas y 18,000 cauríes.", "Ọ̀rúnmìlà: seis conejos (guardados en su bolso), seis palomas y 12,000 cauríes.", "Baáyannì y Àjàgbé: ofrenda antes de salir y para tener hijos."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù vive afuera de la casa de Ọ̀rúnmìlà y se le comparte afuera. Ọ̀rúnmìlà, Òrìṣà-ńlá, Òrìṣà-oko y Ògún aparecen como acreedores en el relato de la deuda. Ṣàngó es el amigo de Baáyannì."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Cáscaras de nuez de palma, pescado, conejos, palomas y cauríes."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 19.1 (yorùbá): Kukute-agbọn Korojiji: / li o difá fOgbè, / Ogbè nlọ soko odẹ. / Wọ̀n niki ó wa ṣebọ / kioma ribi akamọ lohun: / Obúko méta, / akukọ mẹta / ati egbàá méta owó / Ogbè kọ̀ ko ru. / Ó de oko-odẹ tan, Ojo de, / bioti nsure lọ. / O ri iho kan ti o gboro. / O ṣebi iho-igi / tabi okiti kan ni, / O bosinu rẹ, / ko mọ pe Erin liofẹ Ìdí silẹ. / Erin pa Ìdí de mọọ / Bẹẹ ni oun kori ibiri yoo gba jade mọ. / Àwọn èniyàn rẹ̀ bẹrẹsii waa, / lẹhin igba-pipẹ ti wọ̀n ko rii, / wọn lọ ṣe ebọ ti oun Kosilẹ. / Erin wa yaa mọ igbẹ. / Njẹ wọ̀n ni: / \"Ogbè ti o ti Ìdí bọ, / ki a maa pee ni Ogbèdi\". / \"i ribi akamo: ver o vivir el mal de verse rodeado, cercado, sitiado.", "Verso 19.2 (yorùbá): Ogbèdikaka, / Ogbèdilele: / a dífá f'Èṣú / nigbi òun f'ara sọfa lọwọ Ọ̀rúnmìlà, / Oriṣà-ńlá, Oriṣà-oko ati Ògún. / Wọ̀n niki Èṣú rúbọ: / Eesan, / ẹyẹlé mẹsàn / ati egbàásan owó, / kiaṣe ewé Ifá fún un / kiobaa le san'gbese. / Èṣú kò rúbọ.", "REZO: OGBE DI KAKA OGBE DI LELE IYA LAMU BOROTITI OLITON OMO ABAN SHARAELA ADIFAFUN UNBATI ORUNMILA.", "SUYERE: OGBE DI KAKA, OGE DI LELE, OGBE DI LELE, OGBE DI KAKA.", "REZO: OGBE DI KAKA OGBE DI LELE OGBE DI ASUSE AFEFE AYERI OTA EYYE IYA LOMI BOROTITI IYA LAMEBERE TITI ADIFAFUN SHENIBUE BA UNLO EGUNGUN LANSHE.", "REZO: OGBE DI KAKA OGBE DI LELE ADIFAFUN BOROTITI IYA LOMI OLI OTORONSHELA WARA ELEBO.", "REZO: OGBE DI KAKA OGBE DI LELE ADA SHASHA OSIKO OBANA ADIFAFUN OSHUN ATI OGGUN TINSHE KOMADIE EYELE MARUN ELEBO.", "REZO: OGBE DI IFA NI ORISHA ADIFAFUN MOKOLU AWO BAROSIA BOROKATON JORO JORO EGGUN NILE LODAFUN ORUNMILA KAFEREFUN ORISHA ELEGBA.", "REZO: ORISHAOKO ABURE NI SHANGO ARO LESE KAN ATI OLOFIN UNLO SHON SHON OGGUN ORISHAOKO AFEFE IKU AROKO UNYEN SHANGO ARA UMBO NI SHANGO TIYA ONI YEMEYA OKU OKO KAFEREFUN OSHUN OMI DUN DUN SHIRI LODAFUN ORUNMILA.", "REZO: OGBE DI KAKA OGBE DI LELE, DEDELA BORU, DEDELA BOYE, DEDELA BORU.", "REZO: OGBE DI KAKA DI ADIFAYOKO BARABANIREGUN ADIFAFUN OSHUN ADIFAFUN OGGUN OBINI OGBE SA YEYE MATERO AFEFE LO SALU OBOLODE AWOLODA LO IKIN.ESTE ES EL REZO PARA DESPERTAR A ORUNMILA.", "SUYERE: OGBE DI KAKA, OGBE DI LELE. OGBE DI LELE OGBE DI KAKA.", "SUYERE: OMO IFA ODARA OMO ORISHAOKO OMO ODARA.", "REZO: OGBE DI KAKA OGBE DI LELE ADIFAYOKE BARABANIREGUN ADIFAFUN OSHUN, ADIFAFUN OGGUN OBINI OGBE SA YEYE MATEO AFEFE LO SALU OBOLODE AWALODA LO IKIN.", "REZO: OGBE DI OZAIN LEDO IBO IGBE AWO OGBE DI KAKA KUKU", "DIGAGA YAYEMUGAGA EYA AWO IYA IGAGAON IKUYA ELE ADAWO OGBE DI KAKA OGBE DI LELE OBORI ATAYE IYA GOBAMIABOROTITI ADIFAFUN ELUTENSHA MILA UOMA ABAN SHORUTAN UNKO WARANLA LODAFUN OSHUN LODAFUN IYA ADIFAFUN ORUNMILA.", "REZO: IFA NI ORISHA ADIFAFUN MOKELU AWO BOROKOTON KUTUN EGGUN NILE LODAFUN ORUNMILA KAFEREFUN ORISHA ELEGBA.", "REZO: ORISHAOKO ABURE NI SHANGO ARE LESE KAN ATI OLUFINA UNLO SHONSHON OGGUN ORISHAOKO AFEFE IKU UNRYN SHANGO ARA UMBO NI SHANGO TIYA TIYA ONI YEMAYA OKU KEFEREFUN OSHUN OMI DUN DUN ASHIRI LODAFUN ORUNMILA.", "SUYERE: OMO IFA ODARA OMO ORISHAOKO OMO ODARA."]}]$q$::jsonb),
(20,'d2081c1298759d895b2a7be1c819eb4b',$q$[{"titulo": "Idea central", "texto": "Ogbè Ìrosùn es la salida para la amenaza de muerte, enfermedad, juicios, pérdidas y esterilidad. La persona parece vivir de problema en problema y solo lo espiritual le devuelve el equilibrio. La fortuna llega de lugares lejanos y se recoge poco a poco."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene varios problemas a la vez y busca recuperar orden y calma.", "Teme una pérdida, una enfermedad o un problema legal (relato de Àbàtí).", "La oportunidad de dinero viene de fuera o exige salir a buscarla (relato de Òdùkèkèèkè en el bosque).", "Pregunta por hijos o por un embarazo (canto de Òsìn Gàgààgà).", "Necesita avanzar poco a poco en lugar de exigir resultados inmediatos.", "Busca el respaldo de sus antepasados para continuar lo que empezó."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ni la muerte, ni la enfermedad, ni los juicios, ni las pérdidas lo vencerán.", "Fortuna que llega de fuera y se lleva a casa.", "Muchos hijos para quien los pide.", "Recuperar el equilibrio con trabajo espiritual."]}, {"titulo": "Ibi y advertencias", "puntos": ["Dejar las cosas a medias o descuidarlas.", "Enredarse al cargar la fortuna por no ofrecer.", "Esterilidad cuando no se atiende la ofrenda.", "Apartarse de los principios de Ifá."]}, {"titulo": "Enseñanza principal", "texto": "El descuido atrae todos los males, pero con la ofrenda ninguno vence. Lo que se siembra en cantidad regresa en cantidad."}, {"titulo": "Relatos reunidos", "puntos": ["Àbàtí, el descuido. Ifá consultó para Àbàtí, que quiere decir descuido o tarea sin terminar, el hijo mayor de Aramfè, cuando todos los males se le venían encima. El adivino le aseguró que no lo vencería la muerte, ni la enfermedad, ni los juicios, ni las pérdidas, y le marcó un carnero y medicina de Ifá. Él cumplió.", "Òdùkèkèèkè carga la fortuna. Ifá consultó para Òdùkèkèèkè, que iba al bosque a cargar fortunas para llevarlas a su casa. Le pidieron ofrecer para que no se le complicara el camino de regreso. Ofreció, llevó todo lo bueno a su casa y cantó: '¿Quién trae la buena fortuna a mi casa? ¡Òdùkèkèèkè!'.", "Òsìn Gàgààgà y los muchos hijos. Los adivinos de las campanas Agogo y Àjìjà consultaron para Òsìn Gàgààgà, que deseaba hijos. Ofreció en abundancia y tuvo hijos en abundancia: 'Ofrecí en cantidad y di prueba de cantidad'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Àbàtí: un carnero y medicina de Ifá.", "Para la fortuna de fuera: babosas (caracoles) y huevos de gallina a Odù.", "Para una mujer que no ha tenido hijos: dieciséis huevos.", "Òdùkèkèèkè y Òsìn Gàgààgà: ofrenda abundante."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá y Odù reciben la ofrenda. La persona debe vivir conforme a los principios de Ifá."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Babosas, huevos de gallina, carnero."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 20.1 (yorùbá): Onàgbonrangọndon-nti-Ife-wa: / li o dífá fÀbàti / tiiṣe aremo Aramfẹ / eniti gbogbo ibi nkoriti. / Wọ̀n ni: / Ikú a gbee ti, / Àrùn a gbee ti, / Ejo a gbee ti, / Ofo a gbee ti. / Wọ̀n niki o rú. / Agbo kan ati ewé Ifá. / Ó gbọ̀ ó rú.", "REZO: OGBE ROSO UNTELE ASHE EBBO ASHE TO ARIKU BABAWA ORUNMILA AKUALOSIÑA AKUA EBBO RERA ORUNMILA ISOTA OGBE ROSO UNTELE ASHE ATIE DEKU ATIE, ATIE DEYA DEYA ATIE, ATIE AKUKO ATIE, ATIE ADIE ATIE, ATIE ASHE ASHE ADIE.", "SUYERE: OGBE ROSO UNTELE, ATIE KUN ATIE JA ORUNMILA HURUN HURUN MOLE PIN HURUN MOLE PIN HURUN. BOBO BO MI ERAN BOBO BO MI EJE.", "REZO: OGBE ROSO UNTELE ENABORO ADIFAFUN EBBO TINIBELE ELOSO ARUN ABO ELEBO.", "REZO: OGBE ROSO ADIFAFUN OKURIN ODE, OPIPO OBIRIN ORO INDOKO OFIKALE PECULO OPOLOPO OKUNI.", "REZO: OGBE ROSO ADIFAFUN AYAN ASHE LODUN ASHOKO SHOBO AJOGUN LEFA ANAYO ADEDI NILE LODAFUN OLODO.", "REZO: OGBE ROSO MONI OSHA AHEREBO MONI OSHA AHEREBO MONI OSHA ADASHELE.", "REZO: OGBE ROSO KORO AWO OKO ALIA AWO ILE OLOFUN ADIFAFUN AGUNDARE ADIFAFUN SHEKORDA.", "SUYERE: MONI OSHA SESEREBO, MONI OSHA SESEREBO, MONI OLOFUN ORISHA MONI OSHA SESEREBO.", "SUYERE: OGBE ROSO UNTELE, ATIE KUN, ATIE JA, ORUNMILA RURUN RURUN, MOLPIN, RURUN MOLE PIN RURUN. BOBO MI ERAN BOBO BO MI EJE.", "REZO: OGBA ROSO UNTELE ISHIN AWO ORISHOIPKUO OKUN ISHI NI IWIN ORISHA ABANIDIYE AFI YEBA EGOWORO ESAYO OLORUN NI ADIFAFUN ORUNMILA, ADIFAFUN SHANGO, ATI EGGUN.", "REZO: OFA ERI OBA ASHESHE NI ORUN AGBO NAWO OSA OBASHO ERI PERI AWO ODA IYE BU ADIFAFUN OLOFIN TINSHE OKO ABUTUN WO NIGUI OLOLE LEJUN PARUGO KI AYEBE WUNDIA IFA MABA EKUKI GBOGBO ISHE ATI WAHALA ELERI LEYI OBINI NOGBA BO IGUIRIPA DUNKO LEBO ADA LEFE GARUBO KELOPO AYA KOIGBA EDE ODOLOPO KOSI MOPE NOJO MASAN NI AWO IRUN OMOTE ATI AWON EGGUN NITU URUMBO WARIVE IGBA BU OMI OMI OKAN NIMU AWON DIGUN WOYITI EGGUN MOSI OMU OMITI OSI NIBE IBANI POLU TITI", "GBOGBO IGBA OMO BIBIN NIGBA OMO BIRIN OMIFUN EGGUN OBA AGBA BEYIN BORE KAFEREFUN ORUNMILA.", "1ER. SUYERE: OGBATUN OMAKA ODARA INSHE OMU LODE IGBA FIGBA ISHE KOMI ASHE OMOLODE ASHE OMOLODE.", "2DO. SUYERE: (PARA DARLE AGUA A EGGUN). OBA FI OMO ISHE OMI KOBI OSHE OMOLODE ASHE OMOLODE.", "3ER. SUYERE: (PARA DESPEDIR A EGGUN). OYILE IGBE EMO NIJE IJE ORAGUN.", "REZO: OGBE ROSO AFIDI KUE OSORIBENLEKUI OLELE OLELE BABA BIALE OMO OBA LELE OLELE BABA BIALE OMO OBA LALA OLELE OKUA SURE OLELE LAKUA ODA AUN ANIYA BAYAKUNLO SILE ELELE SILE ELELE AUN MAFUFU KETE AUN MALAKUI OROBO.", "REZO: OGBE ROSO, ADIKANKUN, OBININ, OSHISHA UMBO, ALE ODARA, ORUNMILA PELURE, OYA ATI, OSHUN OBIRIN. ODARA LODAFUN OLOFIN."]}]$q$::jsonb),
(21,'0e1fbc81e017dea72f87586f6d174570',$q$[{"titulo": "Idea central", "texto": "Ogbè Ọ̀wọ́nrín es un gran momento, en los negocios y en lo emocional, para atraer gente. Habla de escoger bien entre varios pretendientes, de buena compañía y de bendiciones que llegan a la persona de muchos lados cuando sabe reunir y alimentar a otros."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene que escoger entre opciones de pareja o ver si una unión les conviene a los dos (relato de Koko, Apata y Àkùrò).", "Quiere atraer clientes o fortalecer sus relaciones.", "Hace cosas por otros y nadie se lo agradece (relato de Ṣeşeeşe kò lórí yìn).", "Busca buena compañía y cariño (relato de Ọlọ́fin y Ogbè).", "Se acerca un viaje y puede haber un imprevisto en el camino.", "Algo que parecía mala suerte puede abrirle una salida si actúa con flexibilidad."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Escoger la pareja correcta y tener un matrimonio próspero.", "Atraer clientes, seguidores y afecto.", "Bendiciones de dinero, esposas, hijos, casa y salud.", "Que el mundo entero lo reconozca y alabe."]}, {"titulo": "Ibi y advertencias", "puntos": ["Hacer el bien a otros sin que lo agradezcan.", "Andar por caminos desconocidos que hacen sentir extranjero.", "Escoger pareja sin pensar en el bienestar de los dos."]}, {"titulo": "Enseñanza principal", "texto": "Hay que arreglar bien la propia casa y pisar bien el propio camino. Quien reúne y alimenta a los demás termina rodeado de ellos."}, {"titulo": "Relatos reunidos", "puntos": ["Koko escoge esposo. Koko, el tubérculo, iba a casarse con Àpáta, la roca, o con Àkùrọ̀, la tierra de cultivo. Le marcaron cuatro palomas y cuatro telas anudadas, y cumplió. El adivino le dijo que Àkùrọ̀ sería su esposo favorito: si Koko prospera, la tierra de cultivo prospera con ella.", "Ọlọ́fin y la buena compañía. Okiti-bamba-tiipẹkun-opopo consultó para Ọlọ́fin para que Ogbè fuera su buena compañía, alguien que lo entendiera y le diera cariño. Le marcaron tres gallos y tres recipientes de ñame machacado con sopa. Cumplió.", "El hijo de Àgbọnnìrègún que no era reconocido. Ogbè húnlé: la casa propia es la que se arregla, el camino propio es el que se pisa. Un hijo de Àgbọnnìrègún había probado de todo y nadie le agradecía nada. Le dijeron que consiguiera semillas de palma, las cocinara, reuniera a todos los babaláwo que pudiera y preparara mucha comida para comerla con ellos. Lo hizo, y el mundo entero se levantó a alabarlo; sus asuntos marcharon sin fallar. Cantó: 'Cientos son las hojas de eréyìn; rezaré por riqueza, por mis hijos y por todo lo bueno'.", "Kórewátì y el montón de huesos. Kórewátì, también hijo de Àgbọnnìrègún, preguntó si le llegarían bendiciones. Ofreció, y le llegaron riqueza, hijos, esposas, casas y propiedades, tantas que exclamó sorprendido: '¿A mí?'. El canto compara la llegada de bendiciones con los huesos que se van amontonando en el basurero: así se juntan la riqueza, las esposas, los hijos y la salud."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Koko: cuatro palomas y cuatro telas anudadas.", "Ọlọ́fin: tres gallos y tres recipientes de ñame machacado con sopa.", "Para ser reconocido: semillas de palma cocinadas y comida abundante para los babaláwo, más varias palomas.", "Para que lleguen bienes de fuera: juntar distintos huesos de animales en una cazuela y ofrecerlos."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá y los babaláwo reunidos reciben la comida. Àgbọnnìrègún es el padre de los consultantes de dos relatos."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Koko (tubérculo), semillas de palma, ñame machacado, hojas de eréyìn."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 21.1 (yorùbá): Ajaje: / li o dífá fún Koko / nigbi Koko nlọ ṣe obirin Apata, / nlọ ṣe obirin Àkùrọ̀. / Wọ̀n niki ki ó rú: / Eyẹlé mẹrin / ati aṣo onikoko mẹrin. / Ó gbọ̀ ó rú. / Wọ̀n ni: Akuro ni'le Koko. / Bi orí ba san Koko o san Akurọ. / Ajaje:", "Verso 21.2 (yorùbá): Okiti-bamba-tiipẹkun-opopo: / li o difá fOlófin. / A niki o wa rúbo / ki Ogbè le ye oriwiwọn lọdọ rẹ. / Akuko mẹta, / arabà lyán mọ̀ta / ati obọ ni pbọ. / Ô gbọ̀ ô rú.", "REZO: OGBE WALW ADIFAFUN ADIE YARAKO UNBOWA SILE EÑI ADIE, EKUEKUEYE NI OMO KEKERE ADIRE OROMODIO FUN FUN ARERE LAWA ADIE ERE TASHE ADIE. ADIE WIWO NI OKU LERI ADIFAFUN OGBE WALE KETE WALERI ADIFAIA NI ASIWERE LODAFUN ELEGBA.", "SUYERE: ALA OLE OMO MAYO, MADE ISERE NI MAYO.", "REZO: OGBE WALE OGBE WANIKU OGBE WALE KETO WALE WA NILE ONI BABALAWO ADIFAKOKO KANFUN ORUNMILA OBARABANIREGUN ORUNBO GBOGBO TENUYEN ADIE MEYI, AIKORDIE, EKO, EYA, EPO, AWADO, OPOLOPO OWO.", "REZO: OGBE WALE ITE ADIFAFUN AGUTAN ADIE LEBO, AIKORDIE LEBO GBOGBO YEKU, OBETA OWO, EKU, EYA, OPO, AWADO, EYA TUTU FIFESHU, ORUNMILA LORUGBO.", "REZO: OGBE WANIMU OWUNKO KARIRA ABIMIKU ABERIN OUNKO OKO IFA MORA IFA RAKANSE EMU AJUAN IDI LUARO KOTOWO ADIFAFUN EKUTE.", "REZO: OGBE WANIMU AGO EÑI IBOBORU KO OKUNI PAWO AYAWALA OTO AYAMAWALA OSI MOKUNLE MOKUNLE WALE KETO WALE TO OUN BELONA OTO ETA. ALA OLE OMO MAYE ISERE MI MAYE. AKERE KENKON GBOGBO NISHE OLEDE ATANIGBE ATAMIDA FEKO GBOGBO KOGBO.", "REZO: OGBE WALE KOTOWALE EKINI ENJE AYA OFO ISESHENI ARUN INU AWO ADOFA LOBO KAFEREFUN ORUNMILA LODAFUN AYA.", "REZO: OGBE WALE AMEGO AMONA OREGUN, ELEDA NI AWO OGBE WALE BABARE NI IFA BABARE NI BURUKU, OFONA ILE OGBE WALE, IBETI LESE IGI, OPARALDO OYALORI AWO. KAFEREFUN ORUNMILA LODAFUN IBEYIS.", "REZO: OGBE WALE ELEGBA META, ESHU LAREYE, ALAWANA, EKUTE OKOLEGBANA, AWADO KUKUNDUKUN MARIBO OGU ABITI ABURE MEYI.", "REZO: OGBE WALE AGO ENI IBEBORU KE OKUNI PAWO AYAWALA OTO AYAMAWALA OSI MOKUNLE MOKUNLE WALE KOTOWALE TO UN BELONA TO TO.", "REZO: OGBE WALE IWAKUMA IR IKUNI OMO LODE OSHA AGUANA ORI TOMI AYA IFA UNLE OGBE ILEKUNA ABALIKA OZAIN AGBA BURU OLOKUE BABA OMI TIYA OMO AKEKE OYOKUN OMO OBO IYA IYAO IYA", "OREKUN EYO MEYI OTA SHE OYANLO MOBI OBIA OMO AYAMI ORGUN OMO MIKABAMI TEFA OKOKAN OYO YEGUERE BURE ADIFAFUN KO LOKO IFA BIRE BERE OLONSHE ABANI TEFA ASHOMA DUN DUN AWO ORI OBE OFO BOGANI OSHAWANI IFA LODAFUN OLOFIN.", "SUYERE: ALO ALO OMO MAYE, MADE ISERE NI MAYO.", "SUYERE: ARERE KE KEN BOBONISHE, OLODO ATANIBO ATIMIDA FOKE GBOGBO KO GBO.", "REZO: ELEGBA META, ESHU LAROYE, ALAGWANA, EKUTE, OKELAGBANA AWADO, KUKUNDUKUN ISHUGARA MANIGBE OGU ABITI ABURE MEYI, LODAFUN ORUNMILA.", "REZO: OGBE WARINU, OWUNKO KO RI BA ABIMEKU, AYA, ABERIN, OWUNKO SHE INFANORA INFARAKAN SA EMU, AJUU. IDI LARO YOTOGUO, ADIFAFUN EKUTE.", "REZO: OGBE WALE KETE KETE WENDE GBOGBO FEREKUN KOKO ATEFA IBIGAN LOLOEMI NERE LODAFUN OSHANLA OPOLOPO OWO BURAKATA AGOGO FUN FUN, KAFEREFUN ELEGBA, OSHUN.", "REZO: ADIFAFUN OBATALA ONA SUARE OGBE WALE INLE INLE EYITE AKEKE MARUN OMOKORIN KEKE IBINU TOKU LERI OMODE OGBE WALE INLE, MARUN OMO. IKA ATAPAKO, IFA BELA OBA ARUN ASHO MONGBE OMO DINRIN LODAFUN AMONA ORE.", "REZO: ADIFAFUN ADIE YORAKE UMBO WASILE EÑI ADIE KUEKUEYE NI OMO KEKERE ADIRE ORODIE FUN FUN KO MO ARARE ADIE ORE TASHE ADIE WIWE NI OKU ORO LERI ADIFAFUN OGBE WALE KOTO ADIFAFUN ADIE NI ASIWERO LODAFUN ELEGBA."]}]$q$::jsonb),
(22,'a1a4b6b4088a6e15e0eb06925805536e',$q$[{"titulo": "Idea central", "texto": "Ogbè Ọ̀bàrà habla de enfermedades que vuelven con las estaciones y de una persona que se exige demasiado en el trabajo. Pide calma, cuidar a la pareja —porque por ella llegan las bendiciones— y vigilar a una amistad cercana que puede volverse peligrosa."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se exige demasiado en el trabajo y necesita descansar o avanzar de forma más sostenible.", "Tiene molestias que vuelven cada temporada (relato de las aves en la sequía).", "Busca paz mental y apoyo en su pareja, y no debe tratarla con mezquindad.", "Una amistad cercana se volvió peligrosa (relato de Àfòn e Ìtí).", "Desea formar familia (relato de Ebè y el melón Bàrà).", "Teme una pérdida importante (relato de Ọ̀rúnmìlà ante la visita de Ikú).", "Quiere conocerse mejor y cambiar hábitos que le hacen daño."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Librarse de la muerte que viene a buscar a la casa.", "Muchos hijos de una buena unión.", "Un hijo que ayudará a vencer a los enemigos.", "Paz mental."]}, {"titulo": "Ibi y advertencias", "puntos": ["Enfermedades de temporada, como gripes y alergias; conviene atenderse a tiempo.", "Ser tacaño con la pareja.", "Una amiga o amigo, pequeño de estatura, que se enreda alrededor de uno para hacerle daño.", "Agotarse trabajando."]}, {"titulo": "Enseñanza principal", "texto": "Quien cuida a su pareja recibe a través de ella. Y la falsa amistad se vence con lo que uno sembró: los hijos de Àfòn la defendieron de quien decía ser su amiga."}, {"titulo": "Relatos reunidos", "puntos": ["Las gallinas en la sequía. Ifá consultó para las gallinas y les aconsejó ofrecer diez nueces de kola y 20,000 cauríes para no enfermarse en la temporada seca. Algunas cumplieron y otras no.", "La muerte viene por Ọ̀rúnmìlà. Cuando la muerte venía del cielo a visitar a Ọ̀rúnmìlà, le marcaron una chiva y dieciséis ikin. La chiva se sacrificó a Ifá afuera de la casa para que la muerte no pudiera llevárselo a él ni a los suyos. Ọ̀rúnmìlà cumplió.", "Àfòn y su falsa amiga Ìtí. Àfòn e Ìtí siempre fueron amigas, aunque Ìtí era más bajita. Un día Ìtí mostró su verdadero color: se enredó alrededor de Àfòn y la apretó hasta dejarla en agonía, burlándose de si había ofrecido. Àfòn sí había ofrecido. Sus hijos la desenredaron, tiraron a Ìtí al suelo con fuerza y así su madre venció a la falsa amiga. Ìtí nunca volvió a atacarla.", "El Espinazo y el Melón. Ebè, el espinazo, iba a casarse con Bàrà, el melón. Le dijeron que tendría esposa si ofrecía, pero que no fuera tacaño con ella. Se casó con el melón, y cuando ella empezó a dar hijos tuvo tantos que llenaron todo el suelo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Las gallinas: diez nueces de kola y 20,000 cauríes.", "Ọ̀rúnmìlà: una chiva y dieciséis ikin; la chiva se sacrifica a Ifá afuera.", "Àfòn: un garrote o estaca de madera.", "Ebè: ofrenda para la esposa y no ser tacaño con ella."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá protege la casa frente a Ikú, la muerte. Los hijos son la defensa de la madre en el relato de Àfòn."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Nueces de kola, ikin (nueces de palma de Ifá), melón (bàrà), garrote de madera."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 22.1 (yorùbá): Kuọmi: / a dífá f'Adiye. / A niki wọ̀n wa rúbọ / ki àrùn kan ma baa de / ba wọ̀n nigba oworẹ. / Obi méwà / ati egbáàwa owó li ebọ. / Apakon wọn li ó rúbọ. / Kuọmi:", "Verso 22.2 (yorùbá): Ipalẹro-ab'ẹnúmogimogimamg'nilowọ: / li o difá f'Ọ̀rúnmìlà / nigbi kawokawo óde Orun de. / Wọ̀n niki ó rú: / Ewúrẹ ati Ifá (Ikin) mẹrindilógún. / Pa ewúrẹ fún Ifá ni Ata-nde / ki kawokawo Öde-orun ma baa koo mọ wọn. / Ọ̀rúnmìlà gbọ̀ ó rú.", "REZO: OGBE BARA BI BARA TEREE ADIFAFUN SESE BI ABERE BABA TERERE ADIFAFUN SHANGO BI ABERE BABA TERERE ALORDOFUN OLOFIN BABA YEKU KOLADEE EYO UNLO AGUERE NI ORUNMILA TO IBAN ESHU BI BABA TERE ADIFAFUN OLOFIN.", "SUYERE: ISHONSHON ABE ISHONSHON ABE ODARA KOLORI EYO ISHONSHON ABE", "REZO: OGBE BARA TEMU TEMU PILO ADIFAFUN OLOKUN NI EJE TIOFIN OKUN OJENSHO IRAJON EWE NWENI KI ORUBO KEREUBE YIOBI OMO SHAGBONKI AWO OMOBE MABA MABA ARA SHE OTA NIKI ORUBO, EURE DUN DUN LEBO ASHO ITELERI LEBO AKUKO META LEBO EYILEGUN OWO LEBO KERUN, AKUKO META LEBO OMIKI ENSHABI OMO MOGBATI OMABI OBI SENIN OSIBI AFON.", "REZO: OGBE BARA ORIKOYE AWO AGUARO OMO SHABI OBARALA BALA OGBE BARA ONIKOYE AWO KOKEREY TORI SHEGUA EGGUN BORUN OBA AWO LORUN BABA TOBI SHANGO UN SORO OGBE BARA ORI-KOYE AWO OYORUNLEWA BAGUN IFA OYORUNLEWA OLOFIN KOROÑIRE OYU TISHE ELEGBA ORIYOKE AWO AGBANI SHANGO OBARA-LA BAYABIFA.", "REZO: OGBE BARA ADIFAFUN OBATALA ORIKOSUN ORE OBORISA EYELE ETU ELEGBA OGGUN OSHOSIS EKINI ORISHA FUN FUN BABA KAFEREFUN OLUFON.", "SUYERE: ISHONSHEN ABO ISHONSHEN ABO, ODARA KOLORI EYO ISHONSHEN ABO.", "SUYERE DE EGGUN: MOLERE IKU OBARA BARA MELAYE EGGUN IKU OBA MOLAYE IKU SHANGO MOLAYE EGGUN.", "SUYERE DEL OPARALDO: SARAYEYE EGGUN BOLEKUN LOWA. EGGUN MAWA MORIYEYE BELEKUN OLONA EGGUN IKU SARAYEYE", "SUYERE PARA EBBO MISI Y BAWE LERI: SHOKUIN KUEKUE EWE MOFI YANLAO. SHANGO MOFI YANLAO LORI MOI LANYAO.", "SUYERE: ALAMANA FUNI LALA MOSUKO, ALAMANA FUNI LALA MOSUKO.", "SUYERE: ALAGUANA FUMI LOLA MUSOKO.", "REZO: EYELE ADIFAFUN EYELE LORDAFUN OLOFIN MAFEREFUN ELEGBA KE KONUYA GBOGBO OFO LOKO ISHU.", "REZO: LEKE LEKE LEKEBE AWO AWERE ANILERE BIYE ABRUN MOFUE OYE KUANKUAN LIMIDIO LU ALOMOYE ABERUN FUO EMAWODRUN MAKUO EIYE ABORUN AKODE LODAFUN ORUNMILA APARO ALEBO.", "REZO: BABA TIRIBU ABIRI BABA BALAYA BISHIKO OU ADIFAFUN SESE MERAN EYELE LEBO AYAPA AKUKO LEBO KAFEREFUN SHANGO.", "REZO: OGBE BARA TIELOGAN LEKUN IFASHO BOFO OJUN MIOUN ADIFA-FUN ORUNMILA TIONLE SIAPA OKUN ILAJE ESA MI IWORAN NIBITE EJAGO INSHE GBOGBO LEJU EMI NIWON NIKI ERU LEBO EYA LOBO EYO ERE LOBO EYELE FUN FUN MERIN LOBO MEYOLA OWO LOBO. AYI EMU OWO BA ELA OFUNLO AYIOLE PELU IME OSHO DIE AYIGBA EYELE EKUN AYIOFI SINGBERE OYEKU OYO SIERI. IFA NI ONIRE LEJIN ADIFAFUN ORO OKAN ENIYE LOWO PIPE TIBE BENITO RETOBI IGE BA EWE OKUN OSI WO EWE SHUGBON ATIWO OWO MASHERE.", "REZO: OGBE BARA IKOYO LODAFUN ORIKA MOGAN ODA NILE EGGUN LORUBO AKUKO LEBO BATE AYA ESHU ETA META AKUKO ELEBO OGGUN LORUBO ELEBO ESHU FORUN ORUNMILA UNLO ILE IFE INLE OGGUN LODAFUN ELEGBA.", "REZO: AGBA DIGBO OLEWO LAKU ERU MEDI OSIRIKIKI BAJE KONO KARAN OMO ANABI KOSHEMIBI TANYI KOBO TOKOSO KOLEBO OJUMO KOLA GERI ODUDUWA ALAWANA ENI ETI EGUNGUN ALALA SHENA APA MATA OPE LERI MARIWO ORUNMILA AFURI BI OYE ADABIBARE LODAFUN EGGUN MEYI NI ODARA.", "SUYERE: ALAWANA FUMI LALA MUSOKO.", "SUYERE: EMI OBA OMOLOYUMI EMI OBA OMOLOYUMI AKORIKOBA OMOLOYUMI EMI OBA OMOLOYUMI."]}]$q$::jsonb),
(23,'daf32e002dde2990a93f619b8dc91784',$q$[{"titulo": "Idea central", "texto": "Ogbè Ọ̀kànràn habla de perder lo ganado por hacer las cosas a medias. La persona anda con prisa y necesita ir más despacio. Al mismo tiempo, anuncia logros inesperados: alguien puede llegar a donde nadie imaginaba y una mujer puede dar a luz a un futuro jefe."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se apresuró y dejó algo a medias, y eso pone en riesgo lo que ya tenía.", "Su manera de hacer las cosas ya no funciona; necesita cambiar de método, no solo esforzarse más.", "Busca dinero, pareja o hijos, pero cumplió solo una parte de lo que le pidieron (relato de Ogbè y Otuufe).", "Tiene recursos pero sufre por no tener hijos o por las burlas de otros (relato de Sièjidé).", "Puede lograr algo que nadie esperaba (relato de Lábógundé, que llega a ser Èwí).", "Piensa mudarse o establecerse en otro lugar (relato de Bikibi en el bosque de Ògún)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Dinero, pareja e hijos que salen al paso cuando se cumple.", "Lograr algo que nadie esperaba, incluso una posición muy alta.", "Hijos para una mujer que era objeto de burla.", "Un lugar agradable para establecerse."]}, {"titulo": "Ibi y advertencias", "puntos": ["Ofrecer a medias y luego querer más: lo ganado se pierde y llegan los juicios y las pérdidas.", "La prisa.", "Burlas por no tener hijos.", "Que una mujer de piel clara pierda su buena suerte si no ofrece."]}, {"titulo": "Enseñanza principal", "texto": "Lo que se da incompleto se cobra completo. Ogbè quiso recuperar lo que no había ofrecido y se quedó con las heridas; Sièjidé, en cambio, cumplió y recibió el hijo que le negaban."}, {"titulo": "Relatos reunidos", "puntos": ["Ogbè y las cuatro garras. Ogbè iba a ver a Otuufe y le marcaron cuatro garras y 8,000 cauríes; solo dio tres garras y 6,000 cauríes. El babaláwo le dijo que en el camino real clavara las garras en la tierra una por una. Con la primera brotó un montón de dinero; con la segunda aparecieron mujeres hermosas bailando a su alrededor; con la tercera, muchos niños. Entonces pensó que con la cuarta habría obtenido más, regresó y arrancó la primera garra, que le rasgó la frente. Aparecieron los malos espíritus: juicios, pérdidas y todo tipo de problemas. Desde ese día lo llamaron Ogbè Kànràn, 'Ogbè golpeado por los problemas'.", "Bikibi en el bosque de Ògún. Bikibi iba a establecerse en el bosque de Ògún, y el adivino le dijo que ahí estaría bien. Le marcaron un perro; cumplió.", "Sièjidé, la rica sin hijos. Sièjidé era muy generosa y gastaba en todos, pero no tenía hijos. En una fiesta, mientras repartía dinero bailando, la gente le cantaba burlándose: '¿Dónde están tus hijos? Eres rica pero tienes seco el vientre'. Llorando, fue a ver a Ọ̀rúnmìlà. Los adivinos le prepararon medicina de Ifá y le dijeron que al año, en la misma fecha, sería feliz. En el siguiente festival llegó con su hijo a la espalda, y los que se habían burlado se quedaron callados.", "Lábógundé llega a rey. Lábógundé lloraba porque no le llegaba ninguna bendición. Ofreció sin saber que le tocaba el turno de reinar, y fue coronado Èwí de Adó. Nadie supo nunca cómo llegó a ser rey."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ogbè: cuatro garras y 8,000 cauríes (solo dio tres y 6,000).", "Bikibi: un perro.", "Sièjidé: ofrenda por riqueza e hijos y medicina de Ifá.", "Lábógundé: ofrenda por buenas bendiciones."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà atiende a Sièjidé. Ògún es dueño del bosque donde se establece Bikibi."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Garras, perro, cauríes."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 23.1 (yorùbá): Okitibamba-tii-pẹkun-opopo: / li o difa fOgbe, / Ogbè nlọ si Otuufẹ̀. / Wọ̀n niki ó rú: / Ṣẹrin mẹrin ati egbàá mẹrin owó. / Ṣẹrin mẹta ati ẹgbàá méta owó liọrú. / Babaláwo ti sọ fún un pe: / Nigbati o ba tide ojú-orere (ni popo) / niki o ti bẹrẹsiikan ṣerin naa / mọ'le ni okookan titi lọ. / O de ojú-orere, / ó kan ṣerin kan mọ'lẹ, / owó yẹjade sii, o koo. / Ó tun rin siwájú diẹ, / ó kan ekeji mo'lẹ, / Obirin yojade sii. / Ó ko wọn mọ'ra. / O tun ṣi'sẹ siwájú diẹ, / ó kan ṣerin kẹta mọ'lẹ, / Ọmp seyọ sii. / O ko wọn mọ'ra. / O ni: / Ha! ibaṣepe mo ru ṣerin mẹrin pe, / nba ni ohun pupẹ ju àwọn wọnyi lọ. / Ó pada s'ẹhin o lọ hu ṣerin ekini, / ó wa kan an siwájú. / Ejó, ofo ati bẹebeẹ wa yo sii. / Nje ojo li Ogbè kan ràn / ki a maa pee ni Ogbè'Kànràn.", "Verso 23.2 (yorùbá): Eerindilógún-agbon-koseekodabi-Ifá: / a difá fún Bikibi / nhọ mư lẹ̀ nigbo Ogún. / Wọ̀n ni: / \"ilè ibẹ a gbee\" / Aja kan ni ebo. / Bikibi gbọ̀ ọ rú.", "REZO: OGBE KANA LODAFUN OBATALA ATI SHANGO NI MOTI EWEFA OMODE KOBO ORI OUYEN IYARE ATI BABARE. SHANGO IYEDE BIRINIWA MOFA ADA ELEBO.", "SUYERE: OGOMOLOSHE BIRERE IRU LODAFUN MAYAWAL.", "REZO: OGBA KANA LODAFUN OBATALA ODAFUN SHANGO NI MOTI ALAMO-NI ALAKOSI MONI YEUN EGGUN BABARE ORUNMILA LERUGBO.", "REZO: OGBE KIKANA KOMASE ADIFAFUN OGGUN.", "REZO: ERI KIPE DI ERIKIKAN ELUYU KIPE DI ELUYU EKUN ODE IGBANGBA KIPE DI ODE OMODE ILAUN ADIFAFUN OMO.", "REZO: OGBE KANA AWO NI BEBE NI LORUN AWO NI BONI BOSHE ABE- LEKUN LORUN INLE GANGA NI LODE ASAMI LAYE INLE BORELO ENI OTOTOMI ILO NI SHANGO OMO AWO MONI BOSHEOLORUN SHANGO OGBE KANA OLORUN KOLOYE SHANGO ODARA.", "REZO: EKIKUN KIPO DIN EKIKUN ERIN ABATA KIPE DI ABATA EFON ORERE KIPE OMO ILAUN AWEN ADIFAFUN AWO NI MORE AGBADA NI EJITEBON SI ORUN NI OFUN SHUGBON OLORUN", "SUYERE: OGOLOSHE BIRERE IRU LOFUN KAYAWALE.", "SUYERE: KUDU AKOGBA, EKO, LAYE KOTO ONIKO.", "SUYERE: OSARA MA KOME BEO.", "REZO: OGBE KANA AWO NI BOBE NI LORUN AWO NI MONI BOSHE ABE- LEKUN LORUN INLE GANGA NI LODE ASANI LAYE INLE BORELE ENI OTOTOMI TO NI SHANGO OMO AWO MONI BOSHE LORUN SHANGO OGBE KANA OLORUN KOYELE SHANGO ODARA.", "REZO PARA DARLE EL EYA TUTU Y KLA LERI JUNTO CON SHANGO: ZALARA OREO NI IFA AWO MONI BOSHE EBEYENI IFA KORI BO WO AYE ORI LORUN AGBA NI SHANGO AWO MONI BOSHE ARAGBA NI OBANI LORUN ODUA ORUNMILA AWO IFA MOYARE ODARA, IFA SHANGO AGUANI LORUN.", "SUYERE DEL EYE EN LA LERI: “EYE EYENI YERE ARAGBA FELEGUEGUE FELEGUEGUE AGBA OEREO.”", "REZO: ERIN LAFIAKU ORO LEGEN LABAOWO OROLOWUOKO ORO TIOSHEGI ERIN ABIKUNLO OYEKU OLOFIN ERIN PEREBI AJANAKU TINE-LUIKARA ONI MOWA ERIN OKE MOFOYU LABUTA LABUTA BI OLO- WU KUDU AKOGBA OKE ERI SOFOBU LABATA BI OLUWO KUDU AKOGBA OKE ERIN OTOKU AJANAKU KOTO SILE ADE ERIN LARI ERIN KOLARUN ADIFAFUN ERIN OKO LAYE KOTE NIKO LOJOMO ELOJIN GBRO AFI ORI KUNLO FOKO LODAFUN ORUNMILA.", "SUYERE: KUDU AKOGBA EKE, LAYE KOTE ONIKO."]}]$q$::jsonb),
(24,'5277d64a9c1649328616e527d82912eb',$q$[{"titulo": "Idea central", "texto": "Ogbè Ògúndá anuncia un éxito material cercano. Se presenta una oportunidad que a primera vista parece poca cosa y la persona querrá rechazarla: hay que mirarla con calma. También pide no separarse de sus mayores religiosos ni de quien lo inició."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Le llega una oportunidad o un regalo que por fuera no convence, pero por dentro vale mucho (relato del paquete de hojas de koko).", "Espera la recompensa de un trabajo anterior y no ve que ya se le abrió el camino.", "Busca riqueza y estabilidad familiar (relato de la gente de Egún Majo).", "Se alejó de quien antes lo ayudaba y desde entonces no le va bien (relato de Àyìnnipinpin y Ẹlẹ́gùdumòró).", "Siente que ayudar le sale caro y no valora lo que gana con eso.", "Desea pareja o hijos.", "Se siente mal recibido o menospreciado al intentar una relación (relato de Ọ̀rúnmìlà en Ìwó)."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Gran riqueza para quien recibe lo que le llega.", "Esposa y dinero ofreciendo kola a Ifá.", "Bendiciones que regresan a la casa cuando vuelve el babaláwo de siempre.", "Llegada sin aviso de esposas, riqueza, hijos y casas."]}, {"titulo": "Ibi y advertencias", "puntos": ["Despreciar un regalo por cómo viene envuelto.", "Cambiar al babaláwo que siempre funcionó por ahorrar.", "Separarse de quien lo inició en Ifá."]}, {"titulo": "Enseñanza principal", "texto": "No se juzga por el envoltorio. Alárá y Ajerò rechazaron lo que su madre mandaba en hojas secas, y Ọràngún, que lo aceptó, se hizo rico vendiéndoles a ellos mismos las cuentas que habían despreciado."}, {"titulo": "Relatos reunidos", "puntos": ["La gente de Egún Majo. Kuku-ndukun y Pẹtẹ-inoki consultaron para la gente de Egún Majo y les dijeron que podían llegar a ser muy ricos. Les marcaron cuatro cerdos, 80,000 cauríes y cuatro barriles de vino. Cumplieron.", "Las cuentas envueltas en hojas secas. Los adivinos de Alárá, de Ajerò y de Ọràngún les advirtieron a los tres que iban a recibir algo y que no lo rechazaran. Poco después, la madre de Alárá le mandó un regalo envuelto en hojas secas de koko. Alárá se ofendió y lo rechazó; se lo mandaron a Ajerò, que también lo rechazó; molestos, se lo pasaron a Ọràngún, que lo aceptó. Al desenvolverlo encontró cuentas. Ọràngún hizo su ofrenda —tela de pintas, una paloma y 16,000 cauríes—, ensartó una quinta parte de las cuentas en un collar y se lo mandó a Alárá para que se lo comprara, porque le quedaba bien; Alárá lo compró. Hizo otro con otra quinta parte para Ajerò, y Ajerò también lo compró. Con lo demás se cubrió todo el cuerpo.", "Àyìnnipinpin, el babaláwo de la casa. Àyìnnipinpin era el babaláwo de la casa de Ẹlẹ́gùdumòró. Cada vez que llegaba pedía una botella grande de vino, y con él la casa se llenó de bendiciones. Un día Ẹlẹ́gùdumòró se preguntó por qué tenía que darle tanto vino y llamó a otros sacerdotes, que no le dieron resultado. La gente le dijo: 'Mejor que te pida vino y se resuelvan tus cosas, que no te pida poco y no veas nada'. Volvió a llamar a Àyìnnipinpin, le dio su vino, y la casa se llenó otra vez de bendiciones.", "Ọ̀rúnmìlà y Somúgàgà. Ọ̀rúnmìlà iba a casarse con Somúgàgà. Le dijeron que una rata siempre es pareja de otra rata, un pájaro de otro pájaro y un pez de otro pez. Ofreció dos ratas, dos pájaros y dos peces, compró kola en el mercado y se lo ofreció todo a Ifá. Al poco tiempo, sin aviso, le llegaron esposas, riqueza, hijos y casas. Cantó: 'Somúgàgà, ven a ser esposa de un awo'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Egún Majo: cuatro cerdos, 80,000 cauríes y cuatro barriles de vino.", "Ọràngún: tela de pintas, una paloma y 16,000 cauríes.", "Àyìnnipinpin: botellas grandes de vino para el babaláwo.", "Ọ̀rúnmìlà: dos ratas, dos pájaros, dos peces y nueces de kola a Ifá.", "Festejar a varios babaláwo con vino y comida, y kola a Ifá para esposa y dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Ifá recibe la kola. El babaláwo de la casa y quien inició a la persona son vínculos que no se deben cortar. Alárá, Ajerò y Ọràngún son tres reyes yoruba hermanos en el relato de las cuentas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Hojas secas de koko, cuentas, nuez de kola, vino."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 24.1 (yorùbá): Kuku-ndukun, / Pẹtẹ-inoki: / a dífá fún wọn l'Egún Majo. / I wọ̀n a n'ọrọ yeye. / Elẹdẹ mẹrin, okẹ mẹrin owó / ati agba oti mẹrin ni ebọ. / Wọ̀n gbọ̀ wọ̀n rú.", "Verso 24.2 (yorùbá): Ibinu awo Alára: / li o dífá f'Alárá, / Edofufu awo Ajerò: / li o dífá f'Ajerò, / Pẹlẹturu awo Ọ̀ràngún: / li o difá fOràngún, / Ifá I wọ̀n maa fi inkan / kan ransẹ si wọn ki wọ̀n mama kọ ọ. / Ó pẹ diẹ lẹhin eyi, / iya wọn fi eepa koko / (ewé koko tiotigbẹ) / ti a di ranṣẹ si Aláára. / Alárá binu ó ni: / Eepa koko ni iya oun / ri fi ranṣẹ si oun ninu / gbogbo inkan ti o wa l'ayé yi? / O kọọ. / lya wọ̀n si tun fi ranṣẹ si Ajeró. / Ajeró tun kọo. / Ni ibinu wọn muulọ si ọdọ Ọ̀ràngún. / Ọràngún gbaa. Otuu wo. / O ba ilẹkẹ ninu re. / Oràngún sa ti rúbọ / ti Babaláwo rẹ yan fún un. / Ọràngún ti rú: / Aṣo ẹtu, ẹyẹlé / ati egbàájo owó. / Ọràngún sin ikarun kan ninu wọn o / fi ranṣẹ si Alárá pe ki o raa / nitoripe oun rii pe o baa mu. / Alárá raa. O sanwo. / Otun sin ikarun ekeji o / fi ranṣẹ si Ajerò pe ki o raa. / Ajerò raa. O sanwo. / Nitoripe Oràngún fi ohun / didára dii ni wọ̀n ṣe raa. / O si fi àwọn ilẹkẹ iyokun pamg / fún ilo ti ara rẹ̀.", "REZO: OGBE YONO OBOSORBO OBOKONO ADIFAFUN SHONA.", "SUYERE: ATIPONLA IFA BORU, ATIPONLA IFA BORU. IFA OWE, IFA OMA, IFA IRE. ATIPONLA IFA BORU.", "SUYERE: IYO MALERO IYO MALERO AJALA IYO MALERO. (PARA LA SAL). EPO MALERO EPO MALERO AJALA EPO MALERO. (PARA LA MANTECA DE COROJO). ORI NALERO ORI MALERO AJALA ORI MALERO. (PARA LA MANTECA DE CACAO). EFUN MALERO EFUN MALERO AJALA EFUN MALERO. (PARA LA CASCARILLA).", "REZO: OGBE YONO AYE ADE MOWAYE EREÑI LAYE ADIFAFUN ODUDUWA WANEMI OFA OWAYE ODUDUWA IKU SEGUERE, ARUN SEGUERE, OFE SEGUERE,EYE SEGUERE, OGU SEGUERE, EYU ARAYE SEGUERE ELEMU SEGUERE.", "REZO: ADDE YENI MOWA YENI EWE YENI ADOPE MI LADDE OLUWO POPO IRE ARIKU, IRA OMO, IRE OMA, IRE OWO, IRE ASHEGUN OTA.", "REZO: OGBE YONO, EBOMISI OBASALE OBIMISI NI AGBENIYA ADIFA- FUN OTAPOKON UMBATI ORUBO OMODE.", "REZO: OGBE YONO YONO OKUYEYE, OKUKUYERU ADIFAFUN ORUNMILA OBINI.", "REZO: OGBE YONO IFA OLANLA OBA BINI OBALOLO.", "REZO: OGBE YONO KIRIPUEKE AKITIPOKE KUKUTEKU LODAFUN ABUAN ABUAN LORUBE.", "REZO: OGBE YONO PANRERE OFONAMI FONAKITI ADIFAFUN SIEGUIADO EBUESAN KARASHETE.", "SUYERE: SEDEME DE KAE KENEDEME MADO KAE SHEGUERE NIWA KAO BODEME KAE MADO KE.", "SUYERE: YAE YAE MASHE YAE YAE PAE TAKUARA MAYAKUA KERE YAE YAE.", "SUYERE: BONAN SEBERE IKU, IKU SEBERE, ARUN SEBERE, OFO SEBERE.", "SUYERE: SHEBERE OKUN ABO EKUN, SHEBERE OKUN ABO EKUN.", "REZO: OGBE YONO KUKUNDUKU LAYANI LEKE BEBELEKE ILEKE YOSHE OSHA AUN BABALAWO ADIFAFUN YOKAN ONIFA EGUI MAYO OLOWONO AYO ELEGBA GBOGBO YEYE OTONIFA IDA ILU GBOGBO INSHEGUI AGGUN LOYENI AGGUN.", "GBOGBO OSHE ILEKE LABO ABAYEIFA OMOLOYO ILEKE AGGUN OBONLAYA OYU ARINLA BEBE ILEKE IÑAFA FOROLOYU, IÑAFA KOFERU BOYU FURAWA OTONIBOSHE ERE IKUTASHE NARA NARA JUN ADIFAFUN.", "OLUYEBE OBI ORUN AWO OBI INA AWO OLUYEBE LOBI IKU JUN AWO OLUYEBE LOBI ARON JUN AWO OLUYEBE LOBI EYO JUN AWO OLUYEBE LOBI OFO JUN OKOLOYO YEYE ENIFA ILOKE LOYEYE AWO ILEKE, BEBE ORUNMILA ANIFEKUN GBOGBO OSHA WA GBOGBO OSHA ANU ADIFAFUN ORUNMILA.", "LE REZO A EGGUN ASI: INALE EGGUN KUELE, AWO BELELO IÑAFA KUELE ORUN OTONIBOSHE.", "SUYERE: SHEBERE BOKOMO ABE IKU SHEBERE BOKOMO SOKU", "REZO: BITI EBOKO NIYEDI CUCO ADIFAFUN ORISHAOKO OMO OGGUN ADIFAFUN ORILOMORE OMO YO ORUN ADIFAFUN OFUWAPO TINSHOMO ORUNMILA HIJO TIWO LERE OLODUMARE LORE YERIN AWO MEMOTA TODARUKO WONYI OKENIWO NIGRATODOJE KAN NIWORA OHIMO KERE KAWO OLESILE AYE WONIBI AWO BADE LE AYE BOYA IBALOSAN AWO JU ORUN NA LO AGBALAGBA SUJUWO WON NILATIKOKO LOBI ODO AJACA LOTI IKUIN NIBO EWE KANANIE KILATI SA MEBANLO ILE AJACA NIKI OMA LO SARATA BABARI LONA NIKI WON OTOKON SEDA OSALAIYE ODILA AJACA AJAMO TOMON OSEI BIWON BARINDE NIWE BABE IBIKAN, BOTIWO OPOTUNSU RUN OGBE YONO NI WORI NIGBATI AWO BABALAWO ILE ORUNMILA AWO IFA NA OSUN KOMONA SHERENIKUIN KEKE MINIBE OMIBOPI A KOKO AJALA LEMERE KUILE AJACA JIRASI JEN MIMON BABIN KURE LODARE NIBA TI WUN DELE AJACA JIRASI WUN OBANILE AJACA BADUKUE KURO LODARE NIBA TI WUN DELE AJACA JIRASI IWUN OBANILE AJACA BADUKUE LOWO OTUWARE AJACA NI ORI EYENIDA YORE NI ORI TODELEAYE KODARA KUERI.", "REZO: OGBE YONO OBO NILO OSABO OGBE YONO OBO NILO SABE ABONI LARA AGUO FECHE IRE BOBO LERI OMO LARA YIRE AGUO IFA UNLO YEBA YENILARA LAYO BOBO NI YERE OBARA DADA IFA LADE TINCHE ME AGUO NI LARA OGBE YONO OBAKI OBO IFA LAYE NIFA OMO LALA NIFA OGBE YONO IFA NIYA LE ASHEKUN OTA IFA OMO LADE KEFEREFUN ORUNMILA IFA KAFEREFUN OBA TALA KAFEREFUN OGGUN IFA KAFEREFUN SHANGO."]}]$q$::jsonb),
(25,'3077fe78ebf030af3ba303fb46d9c314',$q$[{"titulo": "Idea central", "texto": "Ogbè Ọ̀sá habla de engaños y mentiras de amigos que pueden llevar a pérdidas, y de terminar lo que se empezó. La persona pasa por una etapa áspera, pero si no se rinde triunfa al final. Las bendiciones le pasan cerca sin tocarla mientras no ofrece."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Lo que está haciendo se puso difícil y piensa dejarlo antes de terminar.", "Va a viajar por trabajo y allá puede encontrar con qué prosperar (relato de Ogbè en Alahusa).", "Un amigo o una propuesta le da desconfianza, o parece demasiado buena (relato de Iki y el carnero Agbo).", "Busca recursos fuera de su entorno y debe evaluar bien el viaje.", "Teme perder por confiar sin revisar los hechos.", "El obstáculo principal puede ser una expectativa propia o una decisión apresurada."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Prosperar en un viaje de trabajo.", "Escapar de la trampa de un falso amigo.", "Que las fortunas dejen de esquivarlo y se le junten.", "Salir con vida de una persecución."]}, {"titulo": "Ibi y advertencias", "puntos": ["Un amigo grande y fuerte, como un carnero, que planea su muerte.", "Ser encarcelado o encerrado.", "Que la buena suerte pase a su lado sin tocarlo.", "Rendirse antes de terminar."]}, {"titulo": "Enseñanza principal", "texto": "No todo juego de un amigo es inocente. Iki sobrevivió porque ofreció y cantó lo que le enseñaron; el carnero, que lo engañó, terminó ofrecido en su lugar."}, {"titulo": "Relatos reunidos", "puntos": ["Ogbè en Alahusa. Lekeleke, el adivino de Ogbè, le dijo que prosperaría mucho en su viaje de adivinación a Alahusa. Le marcaron dieciséis palomas y 32,000 cauríes. Cumplió.", "Iki y el carnero. Los adivinos de la Tierra, del Cielo y del borde de la Tierra le advirtieron a Iki que se cuidara de un amigo grande como un carnero, que planeaba traicionarlo. Le marcaron una jícara con muchas nueces de kola, pulseras de hierro, 22,000 cauríes y un cuenco grande de madera con tapa. Cumplió. Un día el carnero visitó a Ọlọ́fin, vio limpio el lugar de Egúngún y supo que lo habían adorado con kola; se rió y prometió traerle a Iki como ofrenda. Fue con Iki y le habló de un juego que, según él, jugaban con su padre: turnarse para cargarse el uno al otro cuarenta pasos dentro del cuenco tapado. Cuando le tocó a Iki estar adentro, el carnero no lo bajó y siguió caminando. Iki cantó lo que el babaláwo le había enseñado: 'Adivinos de la tierra, del cielo y de abajo, el carnero me lleva a Ọlọ́fin para sacrificarme; vengan a sacar a Iki del cuenco'. Al llegar, el carnero sacudió el cuenco, oyó las pulseras de hierro y creyó que Iki seguía dentro. En el patio de Ọlọ́fin lo abrieron y estaba vacío. Ọlọ́fin sentenció que, por tramposo, el carnero sería el sacrificado a Egúngún. Desde entonces a Egúngún se le da carnero.", "Ifánírègún y las fortunas que se cruzan. Ifánírègún había andado mucho sin encontrar fortuna. Le pidieron ofrecer para encontrarse con ella; cumplió, y pronto le llegaron riqueza, esposas e hijos. Cantó: 'Que no me esquive la fortuna; las fortunas que se cruzan conmigo las voy a juntar'.", "El venado que ladró. Àgbọ̀nrín gàgàlà, hijo de Olúugbó, supo que sus enemigos querían atraparlo. Le dijeron que ofreciera ẹ̀kuru a la Tierra y lo hizo. Lo persiguieron largo tiempo y nunca pudieron agarrarlo; al final el venado ladró, y dijeron que una vez que había ladrado, el día de su muerte había cambiado. Salió con vida frente al cazador y frente al leopardo."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ogbè: dieciséis palomas y 32,000 cauríes.", "Iki: jícara con nueces de kola, pulseras de hierro, 22,000 cauríes y un cuenco de madera con tapa.", "Ifánírègún: ofrenda completa; piel de hiena.", "Àgbọ̀nrín y para no ser encarcelado: ẹ̀kuru espolvoreado con iyẹ̀rosùn y enterrado en la tierra."]}, {"titulo": "Relaciones espirituales", "texto": "Egúngún recibe el carnero desde este relato. Ọlọ́fin es el juez. Olúugbó, el dueño del bosque profundo, es padre del venado. La Tierra recibe el ẹ̀kuru."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Nueces de kola, ẹ̀kuru (pastel de frijol), iyẹ̀rosùn, pulseras de hierro."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 25.1 (yorùbá): Lekeleke awo Ogbè: / li o dífá f'Ogbè / nṣawo lo sile Alahusa. / Wọ̀n ni: / \"a rire lohun papoju\". / Nitorinaa kiorúbo. / Ẹyẹlé mẹrindilógún ati egbàá mẹrindilógún owó. / Ó gbọ̀ ó rú.", "Verso 25.2 (yorùbá): Afẹfelẹgẹlẹgẹ awo ayé, / Efufulẹlẹ awo òde orun, / Kukuteku awo aja-ilẹ: / a difá fún Iki. / Wọ̀n ni: / \"ẹnikan giriṣigiriṣi bi Agbo nbaaṣ'orẹ\". / Wọ̀n niki ó rúbọ / kiomabaa tan an lọ pa. / Apipo-obi, / pawa (egbà-ṣẹrin), ẹgbàá mokanla owó, / ppọ̀n tidetiṣi. / tki gbọ ó rú.", "REZO: OGBE SA YEYEMATERO AFEFE SALU AYE, AFETE SALU OLORUN ADIFAFUN EWE BANA AWAYANI ABO, AWAYENI ORUNMILA AFEFE LONA SHANGO ADIFAFUN EWE BANA. OGBE SA ADIFAFUN ORUNMILA ISHONSHON NABE GBOGBO SIYE INLEOBA OLOFIN ARUYE KAFEREFUN BARAPETU LODAFUN OZAIN ERU WAMALE WAMALE ORISHAOKO AYE AFEFE.", "SUYERE: EKUE MORE SALU EKUE, BABATATA EKUE MOLOBOLO UN YERE DUN.", "REZO: ERU WAN ERU MALE ORISHAOKO AYE AFEFE.", "REZO: SHEBELO KUE ABO KU SHEBELO MEDE LE MEKU SHEBELO KUSHESHEBELE KUE ABO KU SHEBELE ABO MELE SHIKU. JOBO SATOLE MOEKU EGGUN.", "SUYERE: KUSHENE ABO KUNE SHEBOLE ABO JUE SHEBELE.", "REZO: SHANGO LONGO ARAO FILANI OGBE SA BILARI EKOSI LARIO OGBE SA AFEFE INTO AFEFE LAO SALU AYE. OGBE SA AFEFE INTO AFEFE LAO LAO AWO SALU OLORUN APONTE PEKITA LORUBO EBBO OBO ORUN OGBE SA YEYEMETERO AFEFE OMO OLOFIN ILU FULEYE OMI IYAYE IKU BONILO LIJI LOMA.", "SUYERE: ABONSA ABONIYA AWO LODA IWI (SE REPITE).", "REZO: OGBE SA OGBERIKUSA OLOFIN NIYIN KUTUN ESADO ORI OASNI OLOFIN IWI EBATE ABE ONIONIONI IWI OMIGA ILE OLOFIN AFEFE LEGUE GUEGUE AWO OGUI OGALONLO AWE ESHURA MEYI LOQUITISIA OUPA.", "SUYERE: EKUE MORE SALU EKUE, BABATATA EKUE MOLOBORO UN YEREDUN.", "REZO: OGBE SA OYA BORI BOKUN LAROYE IYA IYA TOKU ORU OSHE ABOYERE OGBA IFA GRELOKO LORE ONI OGBE SA OSI YEYELINA.", "SUYERE: AWO KALEBO AWO OBA MOYOYE IKU EGGUN OBONIYE IKU AWO BOSIKEO AWO.", "REZO: ADIFAFUN ORUNMILA ISHONSHON NABE GBOGBO AIYE INLE OBA OLOFIN ARUYE KAFEREFUN BARAPETU LODAFUN OZAIN.", "REZO: OGBESA OGBERIKUSA OLOFIN NIYIN KUTUN ORI OAMI OLOFIN", "IKI OBATE ABO ONIONIONI IKI OMIGA ULE OLOFIN AFEFE LEKE KEKE. AWO OWI OGALONLO AWO IWI OSHERA MEYI LOKITISA OSHUPA.", "REZO: OGBE SA, OGBE YONO, OTI IKU, ANSI ALABO IKU, ATILA BIYA, OGBE SA PARA OBASAKUASA, KUASA OKIKAN KI DUBULO IKU, BORO OMOSHUBUN, BORO OMO DIDE.", "REZO: OGBE SA ATEMOLETA OSHU AWO NANIO. OGBE SA ORI AFEFE-LORUN AFEFE MAWA ORUN OÑI LEKAN IGUEDE FIERUBAYE AWO OGBE SA. OMO OLOFIN ENEFA ELEGBA ATEMOLETA SHANGO MEYERI ODDUN. TENTE ABURE OKANA GIO, ABURE OKANA SA. ORI NIFA TENTE MONI LAYE, ABURE OKANA YEKUN OLOWO ORUN ABURE OGBE TUA KATIYEBE NIFA AYEWARA, TONTI ABURE, ODI KAKA OGUERE ORI ORONI LAYE OKUN TENTE ORI LAYE NIFA, OJUANI SHOGBE IMBELARIO ORI OGBE SA ATEMOLETA ORI BAWA ORUN MAYENI IFA AGBANI BOSHE ADELE NIFA OGBE SA AGBA- NILE OSHUN IKAYO ADELE OLERIFA OMO TONIGBASHE UNTEFA ORUN LADEYE ORUN LADEYE NIFA ORI OGBE SA AWO ODARA BORI OLOFIN OMOKIO IFA ORUN LAYE IFA ODARA AWO DANIO."]}]$q$::jsonb),
(26,'b0ff65dea52a223cc99bfcd12f06b5c5',$q$[{"titulo": "Idea central", "texto": "Ogbè Ìká habla de vencer los celos, la desconfianza y la envidia para llegar a la fama y al respeto. Una fortuna salió de la casa y está regresando; lo que es de uno vuelve a uno. Pide más sentido común y menos imaginación en el día a día."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Imagina ofensas o desconfía sin pruebas; debe revisar los hechos antes de reaccionar.", "Quiere que respeten su trabajo, sus derechos o su lugar.", "Una fortuna o una oportunidad salió de su casa y espera que vuelva.", "Una pareja se separó y alguno piensa en regresar (relato de Ìtipónọlá y Ahoro).", "Desea reconocimiento en su profesión (relato del médico Arinwaka).", "Se siente arrastrado por lo que otros le piden (relato de la corriente Ogbàrá-ojo).", "Necesita parar, aceptar consejo y no perder amistades por orgullo."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Fama en todo el mundo para quien ejerce bien su oficio.", "Respeto a sus derechos, que nadie le podrá quitar en vida.", "La fortuna que se fue regresa, y quien se fue de la casa vuelve.", "Recuperar lo que siempre fue suyo."]}, {"titulo": "Ibi y advertencias", "puntos": ["Dejarse arrastrar por lo que otros quieren.", "Imaginar ofensas que no existen.", "Perder la casa o la pareja por no ofrecer completo."]}, {"titulo": "Enseñanza principal", "texto": "Lo que es de uno termina regresando. La tortuga recuperó su caparazón sin pelear; solo esperó, porque siempre había sido suyo."}, {"titulo": "Relatos reunidos", "puntos": ["La corriente de agua. Èṣùmàrè, el arcoíris, consultó para Ọ̀gbàrá-ojo, la corriente que deja la lluvia, y le aconsejó ofrecer un azadón, un machete y un chivo para que nadie la guiara dentro del bosque. Ella se negó, y mucha gente empezó a dirigir su curso. Cuando por fin ofreció, con el tiempo empezaron a respetarla.", "Arinwaka, el médico. Los adivinos le dijeron a Arinwaka, médico del Ọwọni, que su nombre sería famoso en todo el mundo. Le marcaron una rata, un pescado y una gallina. Cumplió.", "Ìtipónọlá vuelve con Ahoro. Ìtipónọlá se había divorciado de Ahoro. Ifá le dijo: 'La casa que dejaste, a ella tendrás que volver'. Ella ofreció, y Ahoro dijo lo mismo que los babaláwo: de donde te vayas, ahí regresarás. Volvió y formalizó con su primer esposo.", "El caracol y el caparazón de la tortuga. El caparazón era de la tortuga, pero el caracol se lo quedó. A la tortuga le aconsejaron dejárselo y le dijeron que con el tiempo volvería a ella. La tortuga se buscó otra casa. Mucho después, la gente atrapó al caracol, le sacó la carne y tiró la concha, y desde entonces ya no la llamaron 'concha del caracol' sino 'caparazón de la tortuga'. Siempre le había pertenecido."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀gbàrá-ojo: un azadón, un machete y un chivo.", "Arinwaka: una rata, un pescado y una gallina.", "Ìtipónọlá y la casa: ofrenda completa para que las bendiciones no vuelvan a salir."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣùmàrè, el arcoíris, es el adivino de la corriente. Ọwọni es el rey al que sirve el médico."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Azadón, machete, rata, pescado, gallina."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 26.1 (yorùbá): Èṣumàrè abidi-dododo: / li o dífá f'Ogbàrá-ojo / A niki ó wa rú: / oką, àdá ati òbúko / ki àwọn ọmọ aráyé / ma ba maa dari rẹ sinu ígbó. / O gbọ̀ ebọ ko mama rú. / Oun ni ọmo aráyé / bẹrẹsii dari rẹ sinu ígbó. / Nigbati o wa rúbo / ni ikẹhin ni àwọn omọ aráyé too / bẹrẹsii maa tún iwa rẹ ṣe diẹdiẹ.", "Verso 26.2 (yorùbá): Qwą ni pẹbẹ, / Esẹ̀ ni pẹbẹ: / li o dífá fún Arinwaka / ti iṣe Oniṣègùn Qwọni. / Wọ̀n ni kaakiri ayé / ni wọ̀n maagbọ orukọ rẹ. / Nitorinaa kiorú: / Eku, ẹja ati abo-adiyẹ. / Ó gbọ̀ ó rú.", "REZO: OGBE KA LAFILA AWO OGBE LOSHUDE ELEGBA IBA FILA ASIA AKETEFUN OMO SHEREGUN IFA LAYENI FILA AWO.", "SUYERE: LASHEWA LASHEWA OMO SEMEWA.", "REZO: OGBE KA ADIFAYOKO KAFUN ASHEBEREBERE OMO OLOFIN OBA.", "REZO: OGBE OKALA OKOE OKONURE AWO OKAMBA OMO OLOFIN BARA BARA ARAWE NIREGUN AGRI KUALONUBE OWUNKO OPA AKUKO EWE EYA OPO EWEYEWO OGBE KA ABABIKO ADIFAFUN IYA OYUPAN ADIE.", "REZO: OGBE KANLA LASHEBANA ADIFAFUN PEISHEBA OMA ESHU AMEGUN", "REZO: OGBE KA ORUNMILA, OGGUN Y OSHOSI, OGBE KA ADIFAFUN ASHIBEROBRE OMO OLOFIN.", "REZO: OGBE IKA EBBO YEKU TU ANARE ANANA EKUTALE YEKE ABEREKU YEKU IYELA KUTALO NANA.", "SUYERE: NANA OKUNAYE EKUTALE, NANA ANANIYO, KUTALE NANA.", "SUYERE: LASHEWA LASHEWA OMO SEMOWA.", "SUYERE: OWENE WENE ABIGBO, OWENE WENE ABIGBO, OFO TANSHE SHEMISHE ABIGBO, OWENE WENE ABIGBO.", "SUYERE: KINI WANILE NNILEKE, AWO KINI WANILE AWO.", "SUYERE: OWUENE WENE ABIGBO, AFETAN SHEMENI ORUNMILA ABIGBO OKERE KERE, ABIGBO AFETAN SHEMENI.", "SUYERE: OJUMO AWO AWO RIREO, OJUMO AWO AWO RIRE AJIBOWA, BALA BALA LOWO, OJUMO AWO AWO RIRE.", "REZO: ORUNMILA ADIFAFUN KANFU ASHEREBEREBE OMO OLOFIN.", "REZO : AILELE ATENI OJUMO MOKONI ADAWU NIPOYIRERE KOLA OKU LOKUNI AGBELE LOOJIN BUMBUN OPI OJO ADAFUN ORUNMILA OJO INSHE AWO OGBE IKA WEN NIKI ORUTO OGBE BAGUNDA KANTI OWA MUNU AKE IWOOBI ADA ABEBO ADIE MEYI, EKU, EYA, NITORI KIWON NABA NUÑELE NIBRIN TINLO OSI TUNIBO AWON BABALAWO LOWON SISE LEMPE KI OTUN WA NI EBBO", "AIKONU KONKOLE SHUGBON ONILATE MONI ILOPO MEYI ORUN-MILA OLOFIN GBOGBO IMALO ORANO OLORUN KALE ERIN A WARA BAWOS IRAWE OLOKUN OLARE OSUPA GBOGBO IMALE AINA EMI OLORI OKAN IPIN IMPORI GBOGBO ONONLO FI OGBO BAGUNDA MAGUN IDI ESHU LORDAFUN GBOGBO ORUNALE ESHU.", "SUYERE: OJUMO AWO AWO RIREO, OJUNMO AWO AWO RIRE AJILOWA, BALA BALA LOWO, OJUMO AWO AWO RIRE.", "SUYERE: AWENE WENE ABIBO ORUNMILA. ADEFE ITANAE ABIBO ORUNMILA. AWENE WENE ABIBO ORUNMILA.", "REZO: ADIFAFUN BARA PETU KOBORI OLE YEWA ONILU OPALYE ORUNMILA OGBE IKA KEFEREFUN ELEGBA.", "REZO: OGBE IKA EBBO YEKU TU AMARE ANANA EKUTALE YEKE ABEREKU IYELA KUTALE NANA.", "SUYERE: OKUNAYE OKUTALE NANA, OKUNAYE OKUTALE NANA, ANANAYE ARA NAYE KUTALE NANA."]}]$q$::jsonb),
(27,'05563401b549739098e8da914a57e460',$q$[{"titulo": "Idea central", "texto": "Ogbè Òtúrúpọ̀n habla de competencia: la persona puede quedarse atrás y gana con la ofrenda. Un nuevo vínculo con el Òrìṣà le trae un despertar espiritual. Pide obedecer a los padres, no malgastar la herencia y cuidar el buen nombre que dejaron los antepasados."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Se compara con otros y teme perder su lugar (relato de la vaca y el caballo).", "Desea hijos o busca guía espiritual (relato de Alaworo-Oriṣà).", "Pregunta a la vez por dinero, pareja e hijos (relato de Sèkèrè).", "Recibió un nombre o una herencia familiar y debe cuidarla sin malgastar.", "Quiere dejar un buen nombre que la gente recuerde (relato del árbol Ìrókò).", "Un problema de salud o un plan frustrado necesita atención práctica.", "Debe escuchar a sus padres o mayores antes de una decisión importante."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Ganar un estatus que antes era de otro.", "Hijos para quien los busca, y riqueza inesperada.", "Un nombre respetado que se recuerda aun cuando uno ya no está.", "Bendiciones a través del Òrìṣà."]}, {"titulo": "Ibi y advertencias", "puntos": ["Desobedecer a los padres.", "Despilfarrar la herencia de los antepasados.", "Perder un lugar por no ofrecer."]}, {"titulo": "Enseñanza principal", "texto": "El rango se gana cumpliendo. La vaca tenía más estatus que el caballo, pero el caballo ofreció y ella no; desde entonces el caballo va adornado."}, {"titulo": "Relatos reunidos", "puntos": ["La vaca y el caballo. Antes la vaca tenía más estatus que el caballo. A los dos les marcaron tres azadones y 66,000 cauríes para tener el lugar del otro. La vaca no quiso; el caballo cumplió. Èṣù convenció a la gente de tratar al caballo como compañero, porque siempre favorece a quien cumple. Desde entonces el adorno de honor va en el cuello del caballo.", "La sacerdotisa sin hijos. Alaworo-Òrìṣà sufría porque no tenía hijos y andaba de un lado a otro como el buitre. Le marcaron una tela blanca para poner sobre el Òrìṣà, 32,000 cauríes y dos gallinas. Cumplió.", "Sèkèrè, hijo de Àlákòlé. Sèkèrè preguntó si tendría riqueza, esposas, hijos y una vida mejor. Le pidieron ofrecer una buena cantidad de dinero para que bailara de gusto el resto de su vida. Cumplió, y la riqueza llegó de golpe; no tenía dónde guardarla y se la ató al cuerpo. La gente decía: '¿Tanto dinero tiene Sèkèrè?'. El canto dice: 'Tu ropa está hecha de cuentas; en tu cuerpo germina la riqueza'.", "El nombre del Ìrókò. Uno que preguntaba si tendría un buen nombre como el de su padre ofreció, y resultó ser el árbol Ìrókò. Aunque lo corten y ya no esté, la gente sigue diciendo 'junto al Ìrókò' para señalar el lugar. Su nombre se proclamó en todas partes con respeto."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["El caballo: tres azadones y 66,000 cauríes.", "Alaworo-Òrìṣà: tela blanca sobre el Òrìṣà, 32,000 cauríes y dos gallinas.", "Sèkèrè: una buena cantidad de dinero.", "Ìrókò: ofrenda por el buen nombre."]}, {"titulo": "Relaciones espirituales", "texto": "Èṣù favorece a quien cumple. El Òrìṣà recibe la tela blanca. Los antepasados cuidan el nombre de la familia."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Árbol Ìrókò, tela blanca, azadones, cuentas."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 27.1 (yorùbá): Jigbinni: / li o difá fẸṣin, / o dífá f'Eranla. / Wọn niki Ẹranla wa rúbọ / ki iwa rẹ ma baar'ẹhin sit'Ẹṣin. / Qkọ méta / ati ẹgbẹtalélọgbọ̀n owó ni ẹbọ. / Eranla gbọ ẹbọ ko ma rú o. / Eṣin gbọ̀ ebọ, ó ruu. / Eranla li o tijẹ ègbọ̀n Eṣin tẹlẹ ri / Èṣú wa sọ fún ẹ̀niyàn / pe kiwọn fa Ẹṣin mọra / nitori eniti ó rúbọ ni Eṣú ngbe. / Orin Ifá naa: / Jigbinni o, / O wa l'orùn Eṣin / Jigbinni o, / O wa l'orùn Eṣin.", "Verso 27.2 (yorùbá): AP / Ogbètúnmopon-Sunmosi, / Bi-omo-ba-nke-iyá-rẹ-ni-aagbefun: / li o difá f'Alaworo-Oriṣà / ti kor'omọgbepòn tio nba igún kiri. / Wọ̀n niki ó rú. / Aṣọ funfun kan / bayi tiowa lori Oriṣà l'ẹbọ, / egberindilógún owó ati abo adiyẹ Méjì. / Ô gbó ó rú.", "REZO: OGBE TUMAKO KUKUYE AYA KUKUYE AYU ARUN ATANA YUBARA KUMISAYA ADELEWA ORUNMILA AGBANI IBA, ABO LEBO. ORUN IRE NIRA KILODA FUN ESHU.", "SUYERE: KUYE KUYE IKU KUYE BINI, KUYE KUYE BERE AWO ATA MAYURU ILU BERE AWO ELEGBA OMODE.", "REZO: OGBE TUMAKO IKU YEYE NISHE OBINI IKUKU NISHE OBINI AMU ATAMU OBINI NISHE OMO ODUDUWA ADIFAFUN ALA ORUMILA AGBANIROGUN TAMALA MALA BALANSHE IWI ESHU NI OKUTE KULALEKE IWI BALELE IFA OMOKEKERE OFA MEYA GBOGBO ARAYE TOKU OSODE IFA LODAFUN ELEGBA.", "REZO: OGBE TUMAKO KAKUYE AYA KUKUYE AYA ARUN ATANA YUBARA KUMISAYA ADELEWA ORUNMILA ABUANI LEBO ABO LEBO ORUN IRE NIRA KEFEREFUN ESHU.", "SUYERE: KUYE KUYE IKU BINI ATA MAYARU IKU BERE ELEGBA ABA- LONKA.", "SUYERE: KUELKE KUTE IKUMBILE KUYE IKU BERE UNLO ATA MAYARU IKU BERE UNLO ELEGBA OMODE.", "SUYERE: OZAIN SHIWIRI KUI KUI, OZAIN SHIWIRI KUI KUI OUN FERE MOLE EÑI ORUN EÑI ORUN, OZAIN SHIWIRI KUI KUI.", "REZO: OGBE TUMAKO IKU YEYE NISHO OBINI IKU KUKU NISHE OBINI AMU ATANU OBININISHO OMO ODUDUWA ADIFAFUN ALA ORUNMILA AGBONIREGUN TOMALA BELANSHE IGI ESHU NI OKUTA KULA-LALEKE IGI BELELE IFA OMOKEKE OFA MEYI GBOGBO ARAYE TOKU OSODE IFA LODAFUN ELEGBA."]}]$q$::jsonb),
(28,'6521a1256914a490800e0ce5f2e962f5',$q$[{"titulo": "Idea central", "texto": "Ogbè Òtúrá habla de ofrecer para tener paz, tranquilidad y felicidad. Un conflicto de trabajo se resolverá a favor de la persona. La fortuna puede llegarle tarde en la vida, y no debe entristecerse por eso: le toca trabajar en la juventud y ofrecer por larga vida."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Tiene un conflicto en el trabajo y quiere resolverlo sin perder la calma.", "Desea adquirir bienes o que le lleguen oportunidades a casa (relato de Ọlomo-Agbeti).", "Se impacienta porque el éxito material tarda; puede llegar en una etapa más avanzada de la vida.", "Debe repartir bien su esfuerzo entre la juventud y la madurez (relato del Amanecer y el Crepúsculo).", "Busca paz o dirección espiritual (relato de Ọ̀rúnmìlà al llegar al mundo).", "Está tan cómodo con lo que tiene ahora que puede descuidar el futuro."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["El conflicto en el trabajo se resuelve a su favor.", "Que los bienes lleguen solos hasta su puerta.", "Paz, felicidad y que nunca caiga en desgracia.", "Hijos y paz mental."]}, {"titulo": "Ibi y advertencias", "puntos": ["Descuidar la juventud y llegar sin nada a la vejez.", "Vivir sin ofrecer: no hay paz sin ofrenda.", "Perder la calma."]}, {"titulo": "Enseñanza principal", "texto": "Ni siquiera Ọ̀rúnmìlà tiene paz sin ofrecer. Quien hace el bien, sobre todo a los pobres, siempre tendrá felicidad; y quien trabaja en su amanecer tiene un buen atardecer."}, {"titulo": "Relatos reunidos", "puntos": ["Ọ̀rúnmìlà nunca cae en desgracia. Cuando Ọ̀rúnmìlà venía a este mundo, le dijeron que nunca caería en desgracia si ofrecía una chiva, una rata y un pescado. Ofreció, y desde la creación no ha caído. Él creó la tierra, fue el primero en pisarla, formó a los adivinos y puso a cada Odù en su lugar, y aun así nunca dejó de hacer sus ofrendas: demostró que nadie tiene paz sin ofrecer.", "Ọlomo-Agbeti. Ajiwoye-odẹdẹ le dijo a Ọlomo-Agbeti que todo lo que adquiriera le llegaría fácil, hasta la puerta de su casa. Le marcaron una rata, un pescado y dos imágenes. Cumplió.", "El Amanecer y el Crepúsculo. Ifá consultó para el Amanecer y para el Crepúsculo y les pidió ofrecer a los dos. El Amanecer cumplió y el Crepúsculo no. Por eso, quien está en el amanecer de su vida debe trabajar y formar su hogar, y eso le dura hasta sus últimos días. Canto: 'Este es mi amanecer; si mi atardecer es bueno, tendré muchas bendiciones'.", "Oníjùmu y los muchos niños. La esposa de la casa vale más que la amante. Oníjùmu preguntó si tendría hijos; ofreció, tuvo paz y exclamó sorprendido: '¡Ando con muchos niños!'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀rúnmìlà: una chiva, una rata y un pescado.", "Ọlomo-Agbeti: una rata, un pescado y dos imágenes.", "Larga vida: ofrenda a su Ẹgbẹ́ (compañeros espirituales) y dar de comer a niños pequeños."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà es el modelo de quien ofrece siempre. El Ẹgbẹ́, los compañeros del cielo, reciben ofrenda para la larga vida."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Rata, pescado, chiva."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 28.1 (yorùbá): Para Oluku oko, / Odẹdẹ Oluku Àdá: / li o difá f'Ọ̀rúnmìlà / nigbi oun mi bowa si òde Ayé. / Wọn ni: \"koniitẹ titi\" / Ewúrẹ, eku ati ẹja li ebọ. / Ọ̀rúnmìlà gbọ̀ ebọ ó rú. / Nitorinaa lati igbati a ti da Ayé, / Ọ̀rúnmìlà ko tẹ titi o fidi ònì olóni yi. / Ọ̀rúnmìlà li o da llẹ̀, Ôun li o kọ tẹ̀ẹ̀. / Òun li o kọ àwọn awo ni Ẹkọ Ifá / tio si fi àwọn Odù si ayé wọn. / Sibẹsibẹ oun kiikọ eti didi si ebo / tiaba yan fún un, / nitori ti oun ti fihan / gbogbo ẹda alaayé pe: / A kiigbaiṣẹbọ ki ara kioro'ni. / Nibi pupo ninu Ẹkọ Ifá / li a si nri apẹẹrẹ rere rẹ pe: / Ọmọ èniyàn ko le gbaiṣẹbọ / ki ara ki o rọọ. / Ati pe: / Ẹbọ kekeke ni nigba alàikú la. / Ẹniti o ba si nwa ire liomaa nṣ'ẹbọ. / Eniti o ba si fẹran iwà ooreṣiṣe paapaa / fún àwọn alaini oun paapaa / ko niiye ni idunnu. / Para, el amigo del azadón (oko) / Odẹdẹ, el amigo del machete (Àdá):", "Verso 28.2 (yorùbá): Ajiwoye-odẹdẹ: / li o difá fQlọmo-Agbeti. / Wọ̀n ni: / \"Gbogbo inkan ti o maa ni, / odẹdẹ ni wón o maa wa baa\". / Eku, ẹja, ati aworan Méjì li ebọ. / Ô gbọ̀ ó rú.", "REZO: OGBE TUANILARA MOFOU SESI ONIBARABANIRE AYEGUE OLUWOPOPO FUYERE ADDE KUE BAYAMI ARAGBA KALEKUN ABEKUN MOFOU SESI AYERE NI IFA OLOFIN ADIFAFUN OLUWO-POPO.", "SUYERE: AWO OBA YEMILO ORUNMILA AWO YEMILO ASHEBO ASHETE ASHE LOMO ASHE LOWO ARIKU BABAWA.", "REZO: OGBE TUA MOFEU SESI ADIFAFUN OLUWO ALADE MOFEU SESI ADIFAFUN AYAPA TIROKO LELE NIFA EYEGUE ODUDUWA MOWALE YERE OLOFIN.", "REZO: OGBE TUA GUA GUA AWOSOYU ADIFAYOKE KONDUN OYA IBON MERUN ADIFAFUN AYA UMBATOLO IYA META GBOGBO IGI INYA OMA ORUNMILA LORUBO.", "REZO: OGBE TUA LARA KATIYERE EKU OGDABA ARO SHAROMODO LARO SHARO OBATALA EDUN SHEPO EKUTE INA KAFEREFUN OBATALA KAFEREFUN OZAIN ADIFAFUN ORUNMILA LODAFUN ELEGBA.", "REZO: OGBE TUA ADIFAFUN AWONI MERIDILOGUN OBGADO IFA ODDUN OGIDE EWINI ODDUN IYASI EDUN POKON LADO EJEPA OKOTASHE INLE OGBE TUAMORO OYA IFE OBA LODAFUN OLOFIN, KAFERE-FUN ODUDUWA, ADIFAFUN ORUNMILA.", "REZO: OGBE TUA NIKO TINSHOMO GUAYE ADIFAFUN OBA YEBE UN KAHIN ALE OMO SHANGO LORUBO.", "REZO: OGBE TUALARA ADIFAFUN AWO LARERE ILOBAYE NI OBALUMA ADIFAYOKO OLOFIN LADE ABAYE ONI BABALAWO LARRE AYE BARABO NIREGUN OLUO SIWAYU LODAFUN ORUNMILA SHANGO Y OGGUN.", "REZO: OGBE TUANILARA OBANI SHANGO ONI IRE IYA OBOYENI IFA ORUNMILA ILE YENYO SHANGO OBANI OKUE JEKUE OZAIN ORUPUE OBA YENTE OKO EWO NI SHANGO OBANI LORUN OBEBUFUN EYELE MEDILOGUN APARO MEDILOGUN BEYEKU IFA.", "REZO: ADIFAFUN IYABAFUN IYA OGIEDAY OMO BI OBA MAKASHE BABA OSAWANI IYA NI OBONO IYABAFUN IYA NI OBONO IYABAFUN IYA OLONO LELE INLE OGUNDAY IWA METETA LERI ASANI OMOLOGO OGUNDAY BABAWA IYABAFUN IYA KERE OGUNDAY IYA IWE METETA LERI OBALELE ODARA BI EGGUN BABA OSAWANI ARUBO YAKON LALE OSA RA BIEMESAN ODDUN MESAN ODDUN MESAN IYABAFUN ASHE ALO OMO OGUEDAY NIWAGUE ALAKAN SHOSHO AYO LERI OGBE TUANILARA OSAWANI SATAMASIA AWO OSHENBOKO LELU LELE KAFERFUN ORUNMILA LODAFUN OLOFIN.", "SUYERE: AWO OBA YEMILO ORUNMILA AWO YEMILO, ASHEBO ASHETO ASHE LOMO ASHE LOWO ARIKU BABAWA.", "SUYERE: AWO TENIYO NI EBBO GUNUGUN ASHE NI EBBO GUNUGUN ASHE NI OLORUN GUNUGUN ASHE NI ASHE GUNUGUN ASHE ORISHA OLORUN.", "SUYERE: OGUEDAY ASHE OMO FUN WAWAO OMO KEKE ODARA NI LAYE.", "SUYERE: ORUGBA LELE OMO INLE SHEPE OMO LELE ENI BONSI EUN NI KAYE.", "SUYERE: INLE OGUERE AWO LOYA ADIE, ADIE BABA OGBE TUANILARA,BABA AWO MOREYA, AWO LOYA ADIE, ADIE BABA.", "SUYERE: ODUDUWA AREMO SOKUN LOMASHE MUDARE ODARA EMIDARA.", "SUYERE: AJA BEKUN BELO KOIÑA, AJA BELE KOIÑA KOIÑA APUANIYE.", "REZO: ADIFAFUN AWONI ERIDILOGUN OBAGDO IFE AWO ODDUN OGIDE EWENI ODDUN IYASI EDUN POKON LADE EJEPA OKOTASHE INLE OGBE TUAMORA OYA OBA LODAFUN OLOFIN, KAFEREFUN ORUNMILA, KAFEREFUN ODUDUWA."]}]$q$::jsonb),
(29,'ce9f7945a3db1bc8cf21a9e3dff84a9a',$q$[{"titulo": "Idea central", "texto": "Ogbè Ìrẹtẹ̀ habla de evitar problemas y de viajes prometedores. Hay riesgo de perder un trabajo o una relación. Tres personas que no son hermanas de sangre pueden unir esfuerzos y hacerse ricas; la fortuna llega desde otra ciudad o del campo."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Teme perder un empleo o una relación y debe ver qué cuidar y qué cambiar.", "Planea un viaje y debe saber si es una oportunidad real o un movimiento sin propósito.", "Personas que no son familia pueden unirse y salir ganando (relato de Erin, Ẹfọn y Eṣinṣin).", "Un negocio en otra ciudad o un trabajo de campo puede traer dinero a casa (verso de Ọ̀rúnmìlà).", "No quiere escuchar una advertencia concreta (relato de Ewọn, Iro e Ìgèdè).", "Se siente estancado y la terquedad no le deja cambiar el plan."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Riquezas que llegan por los caminos, desde la ciudad.", "Una sociedad entre personas que no son familia que da mucho fruto.", "Influencia, honor y riqueza.", "Vencer en una disputa por algo deseado."]}, {"titulo": "Ibi y advertencias", "puntos": ["Perder el trabajo o la pareja.", "Ir a donde Ifá prohibió ir.", "Que los enemigos deseen que caiga en manos de los ajogun."]}, {"titulo": "Enseñanza principal", "texto": "Cuando Ifá dice que no se vaya, no se va. Ewọn e Iro desobedecieron y murieron en la granja; solo Ìgèdè volvió, gracias a la ofrenda de Àgbọnnìrègún."}, {"titulo": "Relatos reunidos", "puntos": ["Ewọn, Iro e Ìgèdè en la granja. Iyalẹtajaja consultó para Ewọn (la cadena), para Iro (la opinión) y para Ìgèdè (el encantamiento), descendiente de Àgbọnnìrègún, y les advirtió que no fueran a la granja porque ahí encontrarían a la muerte. No hicieron caso. A la mañana siguiente fueron, y Ikú mató a Ewọn y a Iro y se tragó a Ìgèdè. Àgbọnnìrègún fue a ver a su babaláwo, que le marcó una pluma de loro, cuentas tutu-opon, tres recipientes de ñame machacado y siete palomas, para ofrecerlos en la granja al amanecer. Al llegar encontró los cuerpos de Ewọn y de Iro en el suelo. Ikú lo llamó, vomitó a Ìgèdè en su mano y le pidió que se lo tragara, diciéndole: 'Àgbọnnìrègún, tú siempre lo devolverás cada vez que haya grandes problemas'.", "Los caminos traen riqueza. Asanigboro, Arinnigboro y Oburin-burin consultaron para Ọ̀rúnmìlà y le dijeron que los caminos le traerían riquezas desde la ciudad. Le marcaron una rata, un pescado y una gallina, y con ellos se apaciguó a Ifá.", "El elefante, el búfalo y la mosca. 'El gallo que cantó ayer cantó de buen agüero.' Así consultaron para el elefante, que lloraba porque no tenía influencia; para el búfalo, que lloraba porque no tenía honor; y para la mosca, que iba a escoger tierra virgen para la cosecha. Los tres ofrecieron. El elefante se volvió influyente, el búfalo honorable y la mosca regresó del campo inmensamente rica.", "La pata solitaria de Ogbè. Le deseaban la muerte a uno que construía una mansión tras otra pero dormía en el suelo, vestía harapos y no tenía con quién jugar. Era la pata solitaria de Ogbè, que iba a pelear por conseguir a Ìrẹtẹ̀. Ofreció y ganó."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Àgbọnnìrègún: una pluma de loro, cuentas tutu-opon, tres recipientes de ñame machacado y siete palomas, en la granja al amanecer.", "Ọ̀rúnmìlà: una rata, un pescado y una gallina a Ifá.", "El elefante, el búfalo y la mosca: ofrenda por influencia, honor y riqueza."]}, {"titulo": "Relaciones espirituales", "texto": "Ikú, la muerte, devuelve a Ìgèdè por la ofrenda. Àgbọnnìrègún (Ọ̀rúnmìlà) es quien rescata. Ifá recibe la rata, el pescado y la gallina."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Pluma de loro, cuentas tutu-opon, ñame machacado."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 29.1 (yorùbá): lyalẹtajaja: / li o difá f'Ẹwọn6a, / Iyalẹtajaja: / li o difá fún Iro, / lyalẹtajaja: / li o difá fún lgèdè / ti nṣe qmọ Àgbọnnìrègún. / A niki wọ̀n ma dẹ ṣi yun oko. / Wọ̀n nì: / \"Bi wọn ba lọ si oko naa / wọn a ba ikú pade\". / Wọ̀n ko gbọ̀. / llẹ mo wọ̀n lọ si oko. / Wọn si ba ikú pade. / Ikú pa Ewọn, o pa Iro, / o gbe İgèdè qmọ Àgbọnnìrègún mi. / Àgbọnnìrègún gbọ̀, / O tọ Babaláwo lọ wọn difá fún un / wọn niki ó rúbọ: / Ikoodẹ, / llẹkẹ tutu-opon, / àràbà-iyán mẹta / ati eyẹlé méje, / wọ̀n ni: / \"ki o gbe ẹbọ naa lẹsi oko ni iyalẹta\" / Ó gbọ̀ ó rú. / O d'oko o ba oku Ẹwọn nilẹ. / O ba oku Iro nilẹ. / Ikú pe Àgbọnnìrègún / o pọ lgèdè lee lọwọ o niki o gbee mi. / O ni: / \"ọjọ ti ọràn ba dun un niki O maa pọo\".", "Verso 29.2 (yorùbá): Asanigboro, / Arinnigboro, / Oburin-burin bu-omi igboro bọ'jú: / li o difá f'Ọ̀rúnmìlà. / Wọ̀n ni: / \"igboro ni Ọ̀rúnmìlà ma laa si\". / Nitorinaa ki ó wa rúbọ: / eku, ẹja, ati abo-adiyẹ. / Ó gbọ̀ ó rú. / Wọ̀n fi eku, eja ati abo-adiyẹ bo Ifá.", "REZO: OGBEREKUNTELE ODANDE IFA MAFEREFUN OGGUN. OGBEREKUNTELE ADDE IFA OBARABANIREGUN ORISHA WANEYI IFA MORI YEYEO ADIFAFUN ORUNMILA AKUALOSIÑA OMO IFA.", "SUYERE: OBAIKU BABA YERERE OMO OBOKOYE IKU SEWERE, ARUN SEWERE, OFO SEWERE, EYO SEWERE, BERELADE OBENIRE OBAYE.", "REZO: OGBE ATE OSADE ODANDE MERI YEYEO APETEBI WADA MAIBERU,APETEBI WADA MAIYOBA, APETEBI WADA MAIBOSHESHE. OSHUN MORI YEYEO IFA AYE MOWA EYE EYIDE EYERI OLOFIN BABA ORUN. ORUN LOYEBONI IFA OMO LAYE IKU AYEÑI IFEI ODEDE ORUN LAYE.", "REZO: OGBEREKUNTELE OSODE ODANDE ODANDE LAYE ODANDE ORISHA ODANDE ELA. ORUNMILA OMO IFA OLOFIN AGUENO AWETE ASHE OLOFIN, ASHE OGGUN OBAYE IFA EBBO SHANGO OBA KOSO OBAYE ORUNMILA OGBEREKUNTELE LETE OZAIN LAYE OBI KUALARA LAYE.", "REZO: OGBE ATE OGBE MATA ALUMEMATA OMO AWOSHE MAFITARUN ADIFAFUN OMO OBANISHE AIKORDIE, ADIE, EKU, EYA, ILA, EFUN, OU, OBATALA OWO MESAN.", "REZO: OGBE DANDE ADIFAYOKO ADIFAFUN ORUNMILA IFA FOTOLUSHO ADIFAFUN YALORDE.", "REZO: OGBE ATE OBA OBE IKUN ABURE IFA BEYE IDARE OBOKOYE.", "REZO: OKPELE EBEYEKUN WA EUMINIYO IYALORDE OWA NILORUN SUNINIYE OGGUN, OGGUN ARERE OWO OKPELE BANIYEKUN ORUNMILA APALOSIÑA OWO YEKUN OWONU ODARA AWENA WEÑA YEYEKUN OKPELE NISHABO IYALORDE OBEYARI OLORUN OKPELE MEYI AWANIEBANIWA ALA ALABOYARI ORUNMILA OKPELE NIKE YIRIKA OKUEBA BUKERE OBA BOKARE ONI OLORUN EYERE EGGUN OKPELE OGGUN ODARA.", "REZO: OGBE ATE AWO NIFA OSHAWA OGBONI OTORUN IFA OBADAWO OMO AWONI EMIMOLE BUBURU OSHA MAWO TOMBU IJERI OGBETE OMO- NI FAUNSODE NIFA OGBEATE TOKU ESHU BELU BELEBU OJO AWO GUNUGUN UMBO WAIYE BI AWO TINLU AWO DI OKE BELEBU KOMOPE IJERIJKU ANAIRERI OFELOSODE AWO LODAFUN IMOLE ORUN KAFEREFUN ORUNMILA.", "REZO: OGBE ATE ADIFAFUN OMOBIRIN ATOLE SHAWO EGUNGUN LAISUN ORUN EFE AKARE LODAFUN OSANYIN OMODERE OLOBINU ONI OLOSA.", "REZO: ORUN KAWADO OGBE ATE ARUN KOWADO OGBE ATE OMOLOGU,OGBE ATE ADAFORI ADI FAYOKO OSHUN ADIFAJOKO LODAFUN SHANGO OBANIREGUN ORUNMILA.", "SUYERE: ARERE OGGUN LAYEO OGGUN LAYE, BABA OGGUN LAYEO OGGUN LAYE.", "SUYERE DE EGGUN: EUERE WERE NITO WERE, AFARAMOYO KOTO FADILAMA OMO IKU WAMBE WAMBE FADILAMA FABAMANBE FADILAMA, EBBO EBBO FEREYE EÑI EBBO FEREYE UNYEN OLOYU WERE IKOKO.", "SUYERE DE EGGUN: EGGUN EKUN FEYU TANA ELUKEREKUN BEKUNSUN EGGUN LELE.", "SUYERE: OBOIKUN BABA YEYERE OWO OBOKOYE IKU SEWERE ORUN SHEWERE OFO SHEWERE EYO SHEWERE BERELADE ABENIRE ABOKOYE.", "SUYERE: EYE EYA LORIDEO OGGUN ALAGUEDE OGGUN LAYABA NILEO OGGUN OKPELE.", "SUYERE ARABA: EJU NIKOO O NANKO ESOFA MIKUO OMANKO AFA YOIBE MEDI LETE.", "REZO: ADIFAFUN OBERU KUNTELE YEDO AWO OBEDANDE ABERU OBERY TASHERE QUERE INLE TINWANILLE PAYA WE INTIVA AKUELE AWO OTOKAN ESON AKUELERI OBEDANDE OBERE KUNTELE LODAFUN YEMAYA KAFEREFUN AGOTEKU KAFEREFUN YALORDE.", "SUYERE: OBERU KUNTELE EYE MOKUE ENENKO ORISHA MIJUE OMANKO IFA EJIOGBE AWENDA IRETE.", "REZO: OGBE ATE AWO NIFA OSHAWO OGBONI OGBONI OTORUN EFA OBADAWO OMO AWONI EMIMOLE BUBURU OSHA MAWO TOMBU IJERI OGBE ATE OMONI EAUSODE NIFA OGBE ATE TOKU ESHU BELU BELEBU OJO AWO GUNUGUN UMBO WAIYE BI AWO TINLU AWO DI OKE BELEBU KOMOPE IJERIKU OFELOSODE AWO LODAFUN IMOLE ORUN KAFEREFUN ORUNMILA.", "SUYERE: LAMI LAMI OLORI AWO ALAWO IKU ONISHEGUN A ORUN OGBEDANDE AWO ODARA."]}]$q$::jsonb),
(30,'ebcb18145571e00ee496bf0e687ac2e9',$q$[{"titulo": "Idea central", "texto": "Ogbè Ọ̀ṣẹ́ trae buenas noticias y logros que se celebran con otros. Anuncia cambios buenos en la relación de pareja. También habla de alguien que lo ha intentado todo sin éxito, o que compró algo de lo que se arrepiente: Ifá dice que a la larga eso le traerá riqueza."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Espera que mejore su relación de pareja o que llegue una celebración compartida (relato de Oloidẹ y Ami).", "Ha probado de todo sin resultado y se pregunta si algún día prosperará (relato del loro Odídẹré).", "Hizo una compra que lo dejó con dudas, pero puede valer más adelante.", "Necesita atender su cabeza (Orí) y revisar cómo toma decisiones (relato de Irẹṣu-ele).", "Busca dinero o hijos y lleva tiempo sin ver avances.", "Hay motivo para celebrar con otros, sin dejar que el interés económico mande en la relación."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Celebración compartida y prosperidad en pareja.", "Que todo el mundo venga a festejar con uno.", "Lo que parecía una mala compra se convierte en fortuna.", "Hijos para quien no los tenía."]}, {"titulo": "Ibi y advertencias", "puntos": ["Desesperarse antes de tiempo.", "Despreciar lo que se tiene porque no se le ve valor.", "Descuidar la cabeza (Orí)."]}, {"titulo": "Enseñanza principal", "texto": "Lo que parece inútil puede ser la fuente de la riqueza. El esclavo cojo que Òòṣààlá creyó una pérdida fue quien lo hizo rico."}, {"titulo": "Relatos reunidos", "puntos": ["Oloidẹ presenta a Ami. Oloidẹ iba a tomar a Ami como novia y le dijeron que todo el mundo vendría a celebrar con ellos cuando prosperaran. Le marcaron una chiva y cumplió. Un día todos los pájaros le pidieron conocer a Ami; Oloidẹ los citó en la plaza con vino de palma y bebidas. Después de comer y beber, el loro les presentó a Ami cantando: 'Vengo a mostrarles a Ami'. Todos cantaron y bailaron con él.", "Ìrẹṣu-ele y la cabeza. Ṣẹẹṣẹ y Wopwọ le dijeron a Ìrẹṣu-ele, que venía de Òde Àjàláyé, que Ògún sería el único que le arreglaría la cabeza. Le marcaron un cesto lleno de cáscaras de nuez de palma, tres gallos, un ñame asado y 6,600 cauríes. Cumplió.", "El loro y su sangre de cada mes. Odídẹré, el loro, había intentado de todo sin lograr nada; no tenía riqueza ni hijos, y cada mes sangraba. Le pidieron ofrecer y cumplió. La vida le cambió: sus plumas rojas de la cola se volvieron fuente de riqueza, y su sangre de cada mes se convirtió en un hijo.", "Òòṣààlá y el esclavo cojo. Òòṣààlá compró como primer esclavo a un hombre cojo y se lamentó de haber tirado el dinero. Lo mandó a su milpa creyendo que ahí tampoco serviría. Un día de descanso, Òòṣààlá se fue a la ciudad. El cojo vio que los loros se comían las mazorcas, aflojó la tierra al pie de las matas, y cuando los loros se posaron las matas cayeron y las aves quedaron atrapadas con las patas en la tierra. Las fue metiendo en un gran cesto. Al regresar, Òòṣààlá vio la milpa destruida y se enfureció, pero en la casa encontró el cesto lleno de loros. El cojo le dijo que vendieran sus plumas rojas, y fue un gran negocio. Le cantaron: 'El esclavo que compraste te hizo rey; no gastaste en vano'."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Oloidẹ: una chiva.", "Ìrẹṣu-ele: un cesto de cáscaras de nuez de palma, tres gallos, un ñame asado y 6,600 cauríes.", "Odídẹré: ofrenda; sacar con una vasija el agua que se junta junto al lugar de Èṣù."]}, {"titulo": "Relaciones espirituales", "texto": "Ògún arregla la cabeza de Ìrẹṣu-ele. Òòṣààlá es protagonista del relato del esclavo. Èṣù tiene su lugar junto a la hondonada donde se junta el agua."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Cáscaras de nuez de palma, ñame asado, maíz, plumas rojas de loro, vino de palma."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 30.1 (yorùbá): Ero-ilé-komopet'ònà-nbọ: / lo dífá f'Oloidẹ, / nlọ ngbe Ami ni iyàwó. / Wọ̀n ni: / \"gbogbo ayé liomaa wa pe mọọ / nigbi ayé ba yẹwọn yewọn\". / Ewúrẹ kan li ebọ. / Ó gbọ̀ ó rú.", "Verso 30.2 (yorùbá): Sppse, Woowọ: / li o dífá fún Irẹṣu-ele, / nwa ni Òde Àjàláyé. / Wọ̀n ni: / \"Ôgún ni o maa tún orí rè ṣe\". / Nitorinaa ki ó rú: / Apẹrẹ[69] iwẹn[70], / akuko-adiẹ mẹta, ẹsun iṣu / ati ẹgbẹtaelógbọ̀n owó. / Ó gbó ó rú.", "REZO: OGBE SHE BATOLOSHE ESHU OSHE AWADI EBONI OLE OBA OLUWO OBASHE OMOSHE OMO IYA LODE IFA KAFEREFUN ORUNMILA,YEMAYA, OGGUN, ELEGBA, OSHUN, OLUWO LAYE OGBE SHE BARABASHE BAWA OMO ONIRE AYE TIMBELAYE OLUWO ASHAUDE.", "SUYERE: IBAYE DEWA WASHE DIDE, IBAYE DEWA WAO DIDE GBOGBO AYE ORE IBAYE DOWA AWA SODIDE.", "REZO: OGBE SHE AWO NIRE OLOFIN IRE EYA NI BAWA EYENLO GBOGBO IKU ONIRE OBA NI OLORDUMARE ORI BAWA EYA IRE OBA NI.", "REZO: OGBE SHE BALOBOSHE OBATO WOSHE ADIBA DIBA ONI BABALAWO LODAFUN OLUWO DIDE.", "REZO: OGBE SHE KANTON OBAYE DEWA KODIDE SARAUNDERE OLOLODIDE IYALODE OKERE YI MORO ENIDESUN EFIDEBORO OTOLAREFA EYIBOYO NILA ODDUN AYIBAGADARA NAWASI IKOWOBOSHE IYANI NORO YEYEO SHIYANI MORO YEYEO.", "REZO: OYO OTO EGBA MI OLUWO OGBE SHE LODAFUN AKATAMBO UNTO- RODIYA OWODORE ERIN BATI OTOGBA TOBOSILE ORUNMILA.", "REZO: OGBE SHE OWORI WOWO ADIFA OLOFIN AKARO WAYA.", "REZO: BABA OGBE SHE AYE BABA DAWESHE AMUERUN KARAKU TANSI DEWESHE LOBIODUN KEKERE DIONEGUN TIOKO ADIFAFUN OLUO EBBO.", "REZO: ORUNMILA DIFA ADAFUN AYE ALIAKA ONTIGUO YOKO ORUBO ARAYE EMALKIDA OTUNDA AWO UMBO ELESE ORUNMILA ILESE ORISHA EBINKUAKO.", "REZO: OGBE SHE IKU KALENLEKU OGBA OMO NIEGBA UMBATINILE OMODE OPA OLUGWA YALORDE, LODAFUN SHANGO Y OBA.", "REZO: OGBE SHE AWO ERI IFA ONIOSHE KABASHE ASHO NISHELE AWO NIRE ENI IFA JUNJUN AWONI IFA SHANGO AWO EBA KOLA ENIRE IFA.", "REZO: ADIFAFUN LEKE LEKE EWARADA OBETOLOMIRA NO OSHA LEKE LEKE OFOTILO OUMINI LATIBASI IKOKO OGU OZAIN OFOYUDE OYONOWA TAQUEYO OYU ONI ADIFAFUN OZAIN OLOROFUN.", "SUYERE: LEKE LEKE LAWAO OYU ODARA, AFELA AYE NBO NI ODO OYU ODARA, LEKE LEKE LAMBO LAWAO. SUYERE: IBAYE DEWA WASHE DIDE, IBAYE DEWA WAO DIDE GBOGBO", "AYE ORE IBAYE DEWA AWA SODIDE.", "SUYERE: EYA LEWE ENI LEWE, EYA TUTU MOFORI BAWAO ORI NALAWONI EWE OWE OGGUN YARUKURU OGGUN MASENIWEWE AWO MALAYONI AWO IFA OGBE SHE BORIBOSHE BORITOYO AWO ABONIBOSHE.", "SUYERE DEL OPARALDO: SARAYE IBA KILODE IFA INTORI ARAYE KAURE", "SUYERE DEL KOBORI: EYA BEWA ORI LAWADE EYA WA WA FARI MAMA FARI EYA TUTU BELEKE ORI FELEKEKE ORI FELEKEKE MAMA FARA.", "SUYERE DEL ELLA TUTU A EGGUN: EYA LEKE ENI LEKE EYA TUTU MOFORI BAWAO ERI MALAGUIDI EWE EWE OGGUN YANYA OTE OGGUN MASHE NIGUEGUE OGGUN MALA YENI AWO IFA OGBE SHE BORIBOSHE.", "REZO: OGBE SHE ORIBONOSHE ALALALELEKUN SHANGO OBONIBOSHE ORI OMO OLUO ASHE ARANLALE BI EWA OGGUN IFA ENIEWA OGGUN ORIBOSHE ATENI LARA ONIBARANIREGUN ENI FIFE OYA ANIRE- YE ONIBOSHE ENIFA INLE IYESEWA IFA KAFEREFUN SHANGO, KAFEREFUN ORUNMILA KAFERFUN OYA.", "SUYERE DE ESTA CEREMONIA DEL EYA TUTU: EYA LOWE ENI ELEWE, EYA TUTU MOFORIBAWAO ORI MALAWENI EWE EWE OGGUN YANYA URO OGGUN MASENIWEWE AWO MALAYENI AWO IFA OGBE SHE BORIBOSHE. AWO OBORIBOSHE.", "SI EL EGGUN ES AWO SOLO SE PONE EL SIGNO.", "REZO: OGBE SHE BOLOBOSHE AYE BALOSHE OSU OSHIKALIKA NI NI PAUBESHE NILA ADIFAFUN ODIDE ABANKEKE ADIFAFUN ODIDE TIOLOSI IWOSHALA.", "REZO: ODE LAIWO ADIFAFUN ORUNMILA UNLO IGBO OFE TILE IGBIN AGBANI JORO JORO IWO OPEO OLORUN LODAFUN ELEGBA OPEO OLORUN ODE OPOLOPO OWO OPOLOPO ASHE SODAKE UNSORO OBINI ODE OFETILE ASHURI OLORUN AGBANI OMO OSHOSI ODE ODARA OPOLOPO OWO KAFEREFUN ORUNMILA.", "REZO: ADIFAFUN AYABA OBA MANIBU YAKUA SILE ODOÑE ASHABA", "NIADA ADA OGGUN OFO LERI TOKU EYI NI GBOGBO ENI ARAYE NI OFO TURA LADE NI LATIBA NI LATIBA OSA UMBO ELESE IGI ERO ESON LABA ERO NI ADIMU OBA LODAFUN OSHUN MORI YEYEO OBA OFO AI OTI AYRANI ENYA ASHIRI NI ADA OBA ORISHA.", "REZO: ADIFAFUN OLOFIN MEBBO ESE LOKIKAN MASIBU GBOGBO ARIANA OBAYE ELEWE MOJABAE FAYA SABERE OMI SHANGO ODIDE EAYIA SE OLORISHA ARO ERE FERDA BE LODAFUN SHANGO."]}]$q$::jsonb),
(31,'0abff1af691d166f559cde7b738ccbe4',$q$[{"titulo": "Idea central", "texto": "Ogbè Òfún habla de la medicina tradicional y de los sonidos e instrumentos que ahuyentan a la muerte y a los malos espíritus. Advierte que la promiscuidad y meterse con alguien comprometido causan dolor. Pide ofrecer para tener seguidores y atender pronto a los ancestros."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Piensa en una relación que puede causar dolor porque una de las partes ya tiene compromiso (relato de Ogbè y la esposa de Òfún).", "Busca dinero, pareja, hijos o casa (relato de Owó leléwà).", "Quiere reunir seguidores o reconocimiento (relato del Ọba).", "Cree que ya tiene lo que quería, pero quizá descuidó otras responsabilidades.", "Teme la muerte o la enfermedad (relato de Ikú y Àrùn).", "Está a cargo de un grupo y debe ver cómo ejerce y comparte esa autoridad."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Seguidores en abundancia.", "Dinero, pareja, hijos y casa.", "Vencer a la muerte con lo que Ifá enseña."]}, {"titulo": "Ibi y advertencias", "puntos": ["Una relación con alguien que ya tiene compromiso.", "Desatender a los ancestros (Egúngún).", "Comer de lo del rey sin reconocerlo."]}, {"titulo": "Enseñanza principal", "texto": "No siempre gana el más fuerte. La muerte juntó las doscientas una cabezas, pero el que se llevó a la novia fue la enfermedad, que había ofrecido. El sonido correcto vence al miedo."}, {"titulo": "Relatos reunidos", "puntos": ["Ogbè y la esposa de Òfún. Moṣaa-li-o-ni-opa y Erogbonre-o-mẹsẹ consultaron para Ogbè cuando iba a seducir a la esposa de Òfún y le dijeron que tendría éxito. Le marcaron una gallina, una rata, un pescado y 44,000 cauríes. Cumplió. A quien le sale este Odù se le advierte ofrecer para no sufrir por una relación nueva, sobre todo si esa persona está comprometida con otra.", "La muerte, la enfermedad y la hija del Òrìṣà. Ikú y Àrùn querían casarse con Lasunwontan, la hija del Òrìṣà, y el Òrìṣà dijo que se la daría a quien le trajera doscientas una cabezas. Ikú fue a la granja, mató a doscientas una personas, ató las cabezas y se las llevó. En el camino oyó a alguien cantar: 'Si veo a Ikú pelearé con él, si veo a Àrùn pelearé con él'. Asustado de que alguien se atreviera a amenazarlo, soltó las cabezas y huyó. No sabía que era Àrùn: su babaláwo le había pedido doscientos caracoles, se los había ensartado en un collar y le había enseñado el canto, y el choque de los caracoles marcaba el ritmo. Àrùn recogió las cabezas, se las llevó al Òrìṣà y se casó con su hija. De ahí el dicho: 'La muerte tuvo que trabajar para que la enfermedad triunfara'. Por eso la medicina tradicional usa instrumentos y sonidos contra la muerte, en el àbíkú y en los niños enfermizos.", "El rey y los frijoles blancos. El rey venía del cielo y lloraba porque no tenía quién lo siguiera. Le dijeron que preparara frijoles blancos (irú) y les diera de comer a todos. Lo hizo, y desde entonces quien come frijoles blancos es servidor del rey; el que los come y no le corresponde se daña a sí mismo. Así el rey se volvió señor de señores.", "Owó leléwà, el dinero que embellece. Owó leléwà venía del cielo a la tierra y ofreció para tener de todo. Le dijeron: no tener dinero es malo, no tener pareja es torpe, no tener hijos es pasar por la vida como turista, y no tener casa es vivir inquieto. Ofreció y tuvo dinero, pareja, hijos, casa y salud. Junto al dinero va la belleza de la pareja; la casa es la belleza de los hijos."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ogbè: una gallina, una rata, un pescado y 44,000 cauríes.", "Àrùn: doscientos caracoles ensartados en un collar, con su canto.", "El rey: frijoles blancos cocidos para dar de comer a la gente.", "Para seguidores: una cazuela de frijoles blancos o de carita cocidos para Ifá; ofrenda pronta a los Egúngún."]}, {"titulo": "Relaciones espirituales", "texto": "El Òrìṣà es el padre de Lasunwontan. Ikú y Àrùn son la muerte y la enfermedad. Los Egúngún, ancestros de fuerte presencia, piden atención pronto."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Frijoles blancos (irú), caracoles, aceite de palma, sal."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 31.1 (yorùbá): Moṣaa-li-o-ni-opa, / Erogbonre-o-mẹsẹ: / li o dífá f'Ogbè. / Ogbè nlọ gb'obirin Òfún. / Wọ̀n ni: \"a gbaa gbe\". / Abo-adiyẹ, eku, ẹja / ati ẹgbẹjielógún owó li ebọ. / Ó gbọ̀ ó rú.", "Verso 31.2 (yorùbá): Oliwowoji, Oliwowojiwo: / a dífá fún Ikú, / a difá fún Arùn, / wọn lọ fẹ Lasunwọntan ọmọ Oriṣà. / Oriṣà I: / \"ẹnití o ba le ba oun wa orí tutu / Mọ̀kànlerugba ṣa ni oun / maa fi omọ oun fún\". / Gbogbo wọn pada lowa biwọn o ti ṣe ri. / Ikú gba ònà-oko lowa ẹni pa ni warawara / o ti da orí Mokanlerugba jo silẹ. / O di wọn pọ. / O gbe wọn ru. / Bi o ti nlọ lợ'na o ngbọ iro?2 / enikan ti nkorin bayi: / Bi mo r'Ikú ma baa ja. / Oliwowoji. Oliwowojiwo. / Bi mo r'Àrùn ma baa ja. / Oliwowoji. Oliwowojiwo. / Bi Ikù ti gbọ iro yi, / o yara da orí Mókànlerugba naa silẹ. / O salo nitoripe o yaa lẹnu pupo pe / enikan si tun wa tiol'aya / tobẹẹ tiole maa leri oun ati Àrùn. / Ko mọ pe Arùn liowa nidi iwà burúkú yi. / Àrùn sa ti lọs'odo Babaláwo kan / pe ki o jọwọ ba oun wa ọ̀nà / bi oun yoo tiṣe ti oun lefi ni Lasunwontan / ọmọ Òriṣà li aya. / Babaláwo sọ fun un pe: / Kio lọmu igba karahun igbin wa. / Ó ko wọn wa. / Babaláwo so wọn po. / O fi kọọ l'ọrùn. / O kọọ ni orin ti yoo maa kọ ati bẹẹbẹẹ. / Nigbati Ikú da orí Mokánlerugba / naa nu tiosa: / Àrùn ko àwọn orí naa lọ fún Oriṣà. / Oriṣà si fa Lasunwontan omọ rẹ / fún un gẹgẹbi adehun.", "REZO: OGBE FUN FUNLO IKU PUANI ORI BAWA IKU MAYOYORI WANI ADIFAFUN ERUBA OUN LOFE OMA OBATALA ASHO LEBO, JEKUA OSHUSHE IGUNGUN MARIWO LEBO, AIKORDIE MEYI LEBO,AKUKO MEYI LEBO, EKU, EYA, AWADO, LEBO.", "SUYERE PARA HACER ASHINIMA: OGBE FUN FUNLO ENI OYA EWE ASHINIMA ELUDERE OGGUN YEYE OGBE BA ILE, OGUNDE OSHE ARA IKOKO OGUNDE ARIWO TALE.", "REZO: ORUNMIA ADIFAFUN KUBITE TEKAYO OKUNI OLAFUN LAISHE OBINI EURE MEYI LEBO ADOFA OWO LEBO OLOFIN OFUN OBINI ODARA IYAWO KUBITO OLOTIYAKO LOWO ARAYE META ODDUN LESE IGBO, LESE ELEGBA ASHIRI LESE IBU ODE, LODAFUN ELEGBA, KAFEREFUN ORUNMILA.", "REZO: OGBE FUN FUNLO IKU UNLO ARUN UNLO, EYO UNLO, OFO UNLO,IÑA UNLO, ARAYE UNLO, ALKOBA UNLO, OKUMOLORUN INLE, OGBE FUN FUNLE FOSHE FUNLO OLOGARO GOLOWO OMO LAYE OZAIN MOWO OZAIN OSILITUKU WOWO LAYENI OMO OZAIN IÑA OGUNERI IFA OMO OGBE FUN FUNLO ORUNMILA ENI OYA, OTURAO, LODAFUN ORUNMILA, OBATALA OYE OMORABISHE.", "REZO: OGBE FUN IKU FUESAI ORUGABUN YEKI WASI EKUAL ADIFAFUN ERUGBA ESILOPE ESE OBATALA ASHELESE JEKUA ODUSHE GOROGUA MARIBO DIDE AFEFE OTE AFEFE ETA SALUD AYE.", "REZO: ARERE EGGUN YIYEKU NO WAYE SHANGO YEYEREKUN EGGUN MOLELE EGGUN SARAYE OBA KORDARE EGGUN A WAYARE IBA OLORUN KOFIEDEMO EBBO KAYIKO EGGUN EBBO KAYIKO OBA.", "REZO: OGBE FUN FUNLO FOSHE FUNLO OLOGAROGOLOWO MOWO OMO LAYE OZAIN OSILIITKU WONWO LAYENI OMO OZAIN IÑA OWERENI IFA OMO OGBE FUN FUNLO OMO ORUNMILA, ORUNMILA ORUBO.", "REZO: ABITA LOGUN ORUNMILA, ORUNMILA NIKAN TIWO KOMO, OGGUN NI EKETA IMALE KOFIDAN ORUNMILA UMANI ERU IFA, OKUNI KAMPURU ORUNMILA TO BA NIKI IKU ONA LEWA, EDIBADA ABA OLOWARE AKUBI ETU ALU KUBI EKERI AGBA NI IKU ODIJA ABITA TI ORUNMILA, ODIJA ALAFIA BURURU APATAKI IMALE ALA KAIYE IFA ALAFIA. LODAFUN ORUNMILA.", "SUYERE: ONIDE KUYO NIDE, AYARAWO ONIDE KUYU NIDE AYARAWO.", "SUYERE: BARIKU MEBAYA ELEWE WEYI, WEWEYI WEWE OMO BARANU,", "MEBAYA EYE MEBAYA MONA OFO MEBAYA.", "SUYERE: AKUALOYARE ABATILODE EGGUN IKU OFONA.", "SUYERE: OGBE FUN FUNLO OWONIKI AMAIYEGUN OMOKEKERE.", "SUYERE PARA ASHINIMA: OGBE FUN ENI OYA OWO SHINIMA FLUEDERO OGGUN YOYA EGE BAILE FLUDERO OGGUN YOYA EGE BA ILE, OGUNDE OGUNDE ISHE ARA IKOKO OGGUN DE ARIWO.", "SUYERE: ONI KUYU SIDE, ONI KUYU SIDE, ONI KUYU SIDE, AYARABE IALO AFEFE UNTE, UNTE ISLE AFEFE LAE, IKU KUASI IKU MAYEBI OSI NI OPA.", "REZO: ORUNMILA ADIFAFUN KUBITO TOKAYO OKUNI OLAFUN LAISHE OBINI EURE MEYI LEBO ADOFA OWO LEBO OLOFIN OFUN OBINI ODARA IYAWO KUBITO OLOTIYAKO LOWO ARAYE META ODON LESE IGBO LESE ELEGBA ASHIRI LESE IBU ODO, LODAFUN ELEGBA, KAFEREFUN ORUNMILA.", "REZO: ABURE PERRE, PERE, ADIFAFUN ORUNMILA MOBUAN MOBO MOBUAN ORISHA IKU ALASHO ALASHONA.", "REZO: OWENIKU AGBA ASHIRI AMAIYEGUN, LESUN, LABO LERI OGGUN SHANGO ATI AMOKERE, A LO AWONIKU EGUNGUN OMOKERE, AGBA ASHIRI EGGUN EBORA OSHA IMOLE LODAFUN AMAIYEGUN.", "SUYERE: OGBE FUNLO OWONIKU AMAIYEGUN, OMOKERE.", "REZO: OGBE FUNLO FUNLO IKU, UNLO ARUN, UNLO EYO, UNLO OFO,UNLO IÑA, UNLO ARAYE, UNLO AKOBA, OKUMOLORUN INLE, OGBE FUN FUNLO FOSHE FUNLO OLOGARE GOLOWO OMO LAYE OZAIN MOWO OZAIN OSILITU KU WOWO LAYENI OMO OZAIN IÑA, IÑA OGUERENI IFA, OMO OGBE FUN FUNLO ORUNMILA, ENI OYA, OTURAO, LODAFUN ORUNMILA, OBATALA OYE OMORABISHE.", "+++"]}]$q$::jsonb),
(32,'9c9d9c3e741de008ad3c1d431321c6f8',$q$[{"titulo": "Idea central", "texto": "Ọ̀yẹ̀kú Ogbè anuncia que la persona se topará con un pleito ajeno. Si en lugar de meterse actúa como mediador, sale ganando. También advierte que hay que cuidarse de las visitas y de la gente que se recibe en casa, porque pueden destruir el hogar. El trabajo o la carrera parecen trabados."}, {"titulo": "WO · Qué puede estar ocurriendo", "puntos": ["Su trabajo o su carrera está bloqueado y necesita cambiar de método o de etapa.", "Un pleito entre visitas o gente cercana amenaza la paz de la casa (relato de los dieciséis reyes y Ọ̀rúnmìlà).", "Dejó entrar a alguien en su casa y necesita poner límites (relato del lagarto y el muro de barro).", "Está cerca una mejora de dinero o de amor y teme perderla (relato de Ọ̀rúnmìlà en Àjitòròo Ṣègì).", "Termina una etapa de aprendizaje y le toca asumir responsabilidades de adulto.", "Siente ganas de responder con orgullo a un problema que se puede arreglar con calma."], "cierre": "Estas son situaciones posibles; en la consulta se confirma cuál corresponde."}, {"titulo": "Iré", "puntos": ["Riqueza y cosas buenas que quedan en la casa después de un pleito entre extraños.", "Paz, que vale más que la riqueza.", "Fortunas que se pegan a la persona y no se le despegan.", "Volver a casa a ocupar el lugar que le corresponde."]}, {"titulo": "Ibi y advertencias", "puntos": ["Aceptar en la casa a alguien que la va a dañar desde adentro.", "Echar de la casa a quien trae la fortuna, por no tener paciencia.", "Perder la fortuna que ya está cerca por no ofrecer."]}, {"titulo": "Enseñanza principal", "texto": "Los reyes tienen riquezas pero no tienen paz; Ọ̀rúnmìlà, que ofreció y medió, tuvo las dos cosas. Por eso todo el que manda debe tener un babaláwo como consejero."}, {"titulo": "Relatos reunidos", "puntos": ["Los extraños que pelean en casa de Ọ̀rúnmìlà. Agila Awo y Opa-gilagila Awo consultaron para los dieciséis reyes y para Ọ̀rúnmìlà, y les avisaron que llegarían unos extraños que se iban a pelear entre ellos. Les marcaron dieciséis babosas, dos chivas y 32,000 cauríes para tener buena fortuna y paz cuando se fueran. Solo Ọ̀rúnmìlà cumplió. Los extraños llegaron a casa de Alárá y empezaron a golpearse; Alárá los echó. Lo mismo hicieron Ajerò y los otros catorce reyes. Cuando llegaron a casa de Ọ̀rúnmìlà, él trató de calmarlos, y mientras peleaban iban dejando dinero, cuentas y joyas, que Ọ̀rúnmìlà recogía. La pelea duró días, hasta que su casa quedó llena de riqueza. Los dieciséis reyes son Olówu, Olibini, Alárá, Ajerò, Ọràngún, Èwí, Aláàfin de Ọ̀yọ́, Owore, Ẹlẹpẹ, Ọba Adada, Alaajogun, Olú Oyinbo, Olú Ṣabẹ, Ọlọ́wọ̀, Olú Tapa y Olóko.", "El lagarto y el muro de barro. Arun-poṣe-ireke consultó para el lagarto de la casa cuando iba a vivir en un muro de barro. Al lagarto le marcaron cuatro palomas para tener un lugar cómodo, y cumplió. Al muro le marcaron un gallo para que no aceptara a alguien que lo fuera a escarbar por dentro, y no quiso. Por eso el lagarto vive cómodo dentro del muro y lo va agujereando.", "La riqueza que se pega. Ifá consultó para Ọ̀rúnmìlà el día que iba a la ciudad de Àjitòròo Ṣègì, y le preguntó si sus asuntos marcharían bien, si se establecerían seguros y si no perdería lo bueno. Le marcaron una paloma vieja y bastante dinero. Ofreció, y la riqueza se le pegó y no se le cayó, igual que las esposas, los hijos y todo lo bueno. Cantó: 'La riqueza se pegó a mí y no se cayó, wonkoko, como los racimos se pegan al tronco de la palma'.", "El bejuco del campo. Ifá consultó para Awóńwón, el bejuco trepador, que era adivino en el campo. Le dijeron que su destino era que la fortuna llegara a él, que ofreciera y fuera a su lugar de trabajo. Ofreció, todo lo bueno empezó a entrar bajo su techo, y le pidieron volver a casa a sentarse en su trono."]}, {"titulo": "Ẹbọ y prácticas tradicionales", "puntos": ["Ọ̀rúnmìlà y los dieciséis reyes: dieciséis babosas, dos chivas y 32,000 cauríes.", "El lagarto: cuatro palomas. El muro (rechazado): un gallo.", "Para que la riqueza se pegue: una paloma vieja y bastante dinero."]}, {"titulo": "Relaciones espirituales", "texto": "Ọ̀rúnmìlà es el mediador que gana la paz. Los dieciséis reyes representan el poder sin consejo. Ifá recibe las ofrendas."}, {"titulo": "Plantas, alimentos y elementos", "texto": "Babosas, palomas, cuentas preciosas, racimos de la palma, bejuco awóńwón."}, {"titulo": "Rezos, versos y cantos", "puntos": ["Verso 32.1 (yorùbá): Agila Awo, / Agila Awo, / Ọpa-gilagila Awo: / wọ̀n dífá f'Alade Mérindílógún, / wọ̀n dífá f'Ọ̀rúnmìlà. / wọ̀n nì: / \"Awon àlejò kan nbọ, / ijà ni wọ̀n mi a maa / jà nigbati wọ̀n ba de\". / Nitorinaa kiwọn rúbọ / ki adẹhinbọ akoko / ti àwọn àlejò naa wa le bosi ire fún wọn. / İgbin mẹrindilógún, / ewúrẹ Méjì, égbàá mẹrindilógún owó. / Ọ̀rúnmìlà nikansoso li o rúbo ninu won. / Nigbati o pẹ diẹ àwọn àlejo / naa de si llé Alárá. / Nigbati wọ̀n bẹrẹsiina ara wọn, / Alárá le wọn jade. / Wọ̀n de ilé Ajerò / ati gbogbo àwọn Alade Mérinlá iyokun. / Wọ̀n le wọ̀n jade / Ṣùgbọ̀n nikẹhin àwọn àlejò / naa wade ilé Ọ̀rúnmìlà, / wọ̀n bẹrẹsii na ara wọn. / Ọ̀rúnmìlà nla wọ̀n nijà, owó nbọ, / ilẹkẹ nbọ silẹ. / Ọ̀rúnmìlà nko gbogbo àwọn / inkan alumoni ti nbosilẹ / li ara wọ̀n s'ile. / Bẹẹ ni wọn nṣe li ojoojumo / titi ilé Ọ̀rúnmìlà / fi kun fún owó / ati awon ohun rere miran gbogbo. / Qyèkúlogbè! ara mi tu Ẹdú nẹne. / Oruko àwọn Aladé mẹrindilógún / agbà naa ni: / Olówu, Olibini, Alárá, Ajerò, / Oràngún, Èwí, Alaafin-Qyọ̀, Owore, / Flẹpẹ, Ọba Adada, Alaajogun, / Olú-Oyinbo, Olú-Ṣabẹ, Ọlówọ, / Olú-Tapa, Olóko tabi Oṣinlẹ. / Àwọn Ọba wọ̀n ni owó / tabi ohun rere miran, / sibẹsibẹ wọ̀n ko ni itura. / Ọ̀rúnmìlà nikansoso / ti o rúbọ lioni itura pipe. / Nitori Ìdí eyi ni àwọn Ọba / kò le wa laini / Babaláwo gẹgẹbi òkan / ninu àwọn ti yoo maa / fún wọn ni imoran paapaa / nigbati iyonu tabi wahala ba de ba wọn.", "Verso 32.2 (yorùbá): Arun-poṣe-ireke: / li o dífá f'Ọmo-nlé / nlọ ṣe ibakalẹ (Orọ) ipalero. / Wọ̀n niki Ọmo-nlé rú: / Fiyẹle mẹrin / ki o baa le ribi rere joko si. / Ó rú bọ. / Wọ̀n niki Ọrọ rúbọ / kioma baa gba ibakalẹ buburú / ti o mi a maa waa ni'di s'ode. / Akuko-adiyẹ kan ni ẹbọ. / Ọro, eyini ni Ogiri, kò rúbọ.", "REZO: OYEKUN NILOBE BABA AMALU KOMA ARUGBO NISHE EKUN BAYE AVALO BOGBO NISHE AYALO OUN BISYE OMODE BAYA OMA ARUGBO NITU AYE SHE OBIFIN OBIFA KONINIBO.", "REZO: BARA OYEKUN SEMI LOGUE RAULO ASHESE BODO LORISHA.", "SUYERE: ORO NIDE IKU DEDE OMI ODUDUWA AWODE TESIODE ODIRISHE.", "SUYERE: ARARA SOBEYEYO BADO AKUE DAYOKUN YEKU LOBE SOBEYEYO BANOWI BAMIESI YEKU LOGBE.", "SUYERE: OKOKIDI IKIDI KUADE OMO DUDU DESHESI OKOKIDI IKIDI KUADE OMO DUDU DESHESI AWO.", "REZO: BABA ODAJUN RA UNLO LORI ESHESI ODO ORISHA.", "REZO: ONILA SHANGO Y EBELLI OBATALA NI OLOGUN NI ORUNMILA ORONIN SHAGUE OFA OLLEGUNGUI EGUIN ECHIGUELLE OLIROBO NINCHE COLA OYA ONI SHOSHORO ICRINOCU GUEGUERE COLLE KOBAYO ELIROBO NI TA LLECHE COMO FICAN ILUA TOBAFO PE LE OLLE EBBO LUBO EGUO LA MELLO.", "REZO: OGBE EKO OYEKUN OGGUN OLOKOSHE EYANKA ELULU EYIOSA EIYE, LODAFUN OZAIN, KAFEREFUN ORUNMILA.", "REZO: UMBOIFA INLE OLOFIN AWO MERILOGUN OMO IFA OUNTISHE ATEFA AYO OMODE OLOFIN OMO LAYE LOVI OMO OLUO INTORI KEKERE ODDUN."]}]$q$::jsonb))
update estera_sintesis e set secciones=v.sec from nuevas v where e.numero=v.numero and md5(e.secciones::text)=v.viejo returning e.numero;
